import { HEX_SIZE, ISO_SCALE_Y } from "../../../constants";

// 1. Static Geometry Cache (Standard Pointy Top Hexagon)
// Angles: 330, 30, 90, 150, 210, 270 degrees.
// Vertex 0: Top-Right, Vertex 1: Bottom-Right, Vertex 2: Bottom... Vertex 5: Top.
const START_ANGLE = -Math.PI / 6; 

// Pre-calculate base vertices (Flat 2D, Radius 1.0)
const BASE_VERTICES: {x: number, y: number}[] = [];
for (let i = 0; i < 6; i++) {
    const angle = START_ANGLE + i * Math.PI / 3;
    BASE_VERTICES.push({
        x: Math.cos(angle),
        y: Math.sin(angle)
    });
}

// 2. Performance Cache
let CACHED_PATH_STD: Path2D | null = null;

export const HexGeometry = {

    /**
     * Get exact vertices for a hex at (0,0) with specified radius.
     * Applies ISO scaling to Y axis.
     * @param radius - The outer radius of the hex (usually HEX_SIZE)
     * @param applyIso - Whether to squash Y for 2.5D view (default true)
     */
    getVertices(radius: number, applyIso: boolean = true): {x: number, y: number}[] {
        const scaleY = applyIso ? ISO_SCALE_Y : 1.0;
        return BASE_VERTICES.map(v => ({
            x: v.x * radius,
            y: v.y * radius * scaleY
        }));
    },

    /**
     * Draw a hex path on the context at (x,y).
     * @param x - Center Screen X
     * @param y - Center Screen Y
     * @param radius - Size
     * @param applyIso - Use ISO projection
     */
    traceHex(ctx: CanvasRenderingContext2D, x: number, y: number, radius: number, applyIso: boolean = true) {
        // Optimization: Use Path2D for standard grid size
        const isStandard = Math.abs(radius - HEX_SIZE) < 0.01 && applyIso;

        if (isStandard) {
            if (!CACHED_PATH_STD) this.rebuildCache();
            ctx.translate(x, y);
            // Path2D must be filled/stroked by caller using the path object, 
            // but to support generic context drawing we manually trace here if not using explicit path API.
            // Using the pre-calc cache is still faster.
        }

        const verts = this.getVertices(radius, applyIso);
        ctx.beginPath();
        ctx.moveTo(x + verts[0].x, y + verts[0].y);
        for (let i = 1; i < 6; i++) {
            ctx.lineTo(x + verts[i].x, y + verts[i].y);
        }
        ctx.closePath();
    },

    rebuildCache() {
        const path = new Path2D();
        const verts = this.getVertices(HEX_SIZE, true);
        path.moveTo(verts[0].x, verts[0].y);
        for (let i = 1; i < 6; i++) {
            path.lineTo(verts[i].x, verts[i].y);
        }
        path.closePath();
        CACHED_PATH_STD = path;
    },

    /**
     * Get vertices for a rotated hexagon (used by VFX).
     */
    traceRotatedHex(ctx: CanvasRenderingContext2D, x: number, y: number, radius: number, rotation: number, applyIso: boolean = true) {
        ctx.beginPath();
        const scaleY = applyIso ? ISO_SCALE_Y : 1.0;

        for (let i = 0; i < 6; i++) {
            const angle = START_ANGLE + i * Math.PI / 3 + rotation;
            const px = x + Math.cos(angle) * radius;
            const py = y + Math.sin(angle) * radius * scaleY;

            if (i === 0) ctx.moveTo(px, py);
            else ctx.lineTo(px, py);
        }
        ctx.closePath();
    }
};

import { Hex, Point, Cube } from "../../types";
import { HEX_SIZE, ISO_SCALE_Y } from "../../constants";

export { Cube };

const SQRT3 = Math.sqrt(3);

export const HexMath = {

    // --- COORDINATE SYSTEMS ---

    axialToCube(h: Hex): Cube {
        return { x: h.q, z: h.r, y: -h.q - h.r };
    },

    cubeToAxial(c: Cube): Hex {
        return { q: c.x, r: c.z };
    },

    cubeRound(frac: Cube): Cube {
        let q = Math.round(frac.x);
        let r = Math.round(frac.z);
        let s = Math.round(frac.y);

        const q_diff = Math.abs(q - frac.x);
        const r_diff = Math.abs(r - frac.z);
        const s_diff = Math.abs(s - frac.y);

        if (q_diff > r_diff && q_diff > s_diff) {
            q = -r - s;
        } else if (r_diff > s_diff) {
            r = -q - s;
        } else {
            s = -q - r;
        }
        return { x: q, y: s, z: r };
    },

    // --- PROJECTION CORE (STRICT SOURCE OF TRUTH) ---

    /**
     * Converts Hex(q, r) to Screen Pixel(x, y).
     * @returns The CENTER POINT of the hexagon's GROUND BASE (Z=0).
     */
    hexToPixel(q: number, r: number, offsetX: number, offsetY: number): Point {
        // Standard Pointy Top Hex to Pixel
        const x = (SQRT3 * q + SQRT3 / 2 * r) * HEX_SIZE;
        const y = (3 / 2 * r) * HEX_SIZE;

        // Apply ISO Squash (2.5D Projection)
        // Only scale Y.
        return {
            x: x + offsetX,
            y: (y * ISO_SCALE_Y) + offsetY
        };
    },

    /**
     * Converts Screen Pixel(x, y) to Fractional Hex.
     * Inverse of hexToPixel. Assumes Z=0 input.
     */
    pixelToHex(x: number, y: number, offsetX: number, offsetY: number): Hex {
        const dx = x - offsetX;
        const dy = (y - offsetY) / ISO_SCALE_Y; // Un-squash

        const q = (SQRT3 / 3 * dx - 1 / 3 * dy) / HEX_SIZE;
        const r = (2 / 3 * dy) / HEX_SIZE;

        return { q, r };
    },

    // --- GEOMETRY UTILS ---

    distance(a: Hex, b: Hex): number {
        const ac = HexMath.axialToCube(a);
        const bc = HexMath.axialToCube(b);
        return Math.max(Math.abs(ac.x - bc.x), Math.abs(ac.y - bc.y), Math.abs(ac.z - bc.z));
    },

    lerp(a: Hex, b: Hex, t: number): Hex {
        const ac = HexMath.axialToCube(a);
        const bc = HexMath.axialToCube(b);
        const cubeLerp = {
            x: ac.x + (bc.x - ac.x) * t,
            y: ac.y + (bc.y - ac.y) * t,
            z: ac.z + (bc.z - ac.z) * t
        };
        return HexMath.cubeToAxial(HexMath.cubeRound(cubeLerp));
    },

    line(a: Hex, b: Hex): Hex[] {
        const N = HexMath.distance(a, b);
        const results: Hex[] = [];
        const ac = { x: a.q + 1e-6, z: a.r + 1e-6, y: -a.q - a.r - 2e-6 };
        const bc = { x: b.q + 1e-6, z: b.r + 1e-6, y: -b.q - b.r - 2e-6 };
        for (let i = 0; i <= N; i++) {
            const t = N === 0 ? 0.0 : i / N;
            const cubeLerp = {
                x: ac.x + (bc.x - ac.x) * t,
                y: ac.y + (bc.y - ac.y) * t,
                z: ac.z + (bc.z - ac.z) * t
            };
            results.push(HexMath.cubeToAxial(HexMath.cubeRound(cubeLerp)));
        }
        return results;
    },

    range(center: Hex, n: number): Hex[] {
        const results: Hex[] = [];
        for (let q = -n; q <= n; q++) {
            for (let r = Math.max(-n, -q - n); r <= Math.min(n, -q + n); r++) {
                results.push({ q: center.q + q, r: center.r + r });
            }
        }
        return results;
    }
};

import { GameEngine, Agent } from "../../game";
import { GridCache } from "./GridCache";
import { RenderList, RenderOpType } from "../../renderers/RenderList";
import { Hex, Skill, Projectile } from "../../../types";
import { TERRAIN_THEMES, HEX_SIZE } from "../../../constants";
import { HexUtils, getTransitionOffset } from "../../utils";
import { HexMath } from "../../math/HexMath";

const OBSTACLE_Z_INDEX = 10;
const PROJ_LIGHT_RADIUS_SQ = 1600;

export class GridRenderStrategy {

    // Transient Sets for faster lookup
    private _unitPresence = new Set<string>();
    private _unitVisualStatus = new Map<string, string>();

    public submit(
        cache: GridCache,
        renderList: RenderList,
        engine: GameEngine, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null, 
        highlightAgent: Agent | null, 
        projectiles: Projectile[],
        transitionT: number,      
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        globalTime: number
    ) {
        if (transitionPhase === 'OUT' && transitionT > 0.95) return;

        cache.ensure(engine);
        const scene = engine.currentScene;
        const theme = TERRAIN_THEMES[scene.textureType] || TERRAIN_THEMES['VOID'];

        // 1. Pre-calc Unit Presence
        this._unitPresence.clear();
        this._unitVisualStatus.clear();
        for (const a of engine.agents) {
            if (a.hp > 0) {
                const key = `${a.q},${a.r}`;
                this._unitPresence.add(key);
                if (a.visualStatus !== 'NONE') this._unitVisualStatus.set(key, a.visualStatus);
            }
        }

        // 2. Iterate Tiles
        const len = cache.tileList.length;
        for (let i = 0; i < len; i++) {
            const tile = cache.tileList[i];
            const { q, r, px, py, h, key } = tile;

            // Visual Transition Offset
            const offset = getTransitionOffset(px, py, engine.mapConfig, transitionT, transitionPhase);
            if (Math.abs(offset) > 800) continue;

            // --- STRICT COORDINATE DEFINITION ---
            // Base Y: The bottom of the terrain column (Ground Level 0).
            // Surface Y: The top of the terrain block (Where units stand).
            // 
            // Screen Y = IsometricY - Z_Height

            const visualBaseY = py + offset;        // Screen Y of the bottom
            const visualSurfaceY = visualBaseY - h; // Screen Y of the top surface

            const sortY = visualBaseY; // Sort by base position for correct occlusion

            // A. Obstacles (Sit on SURFACE)
            const obstacleType = engine.obstacles.get(key);
            if (obstacleType) {
                const op = renderList.next();
                op.type = RenderOpType.OBSTACLE;
                op.y = sortY; 
                op.z = OBSTACLE_Z_INDEX;
                op.tx = px; 
                op.ty = visualSurfaceY; // Anchor to top
                op.ttype = obstacleType;
            }

            // B. Terrain Block
            const op = renderList.next();
            op.type = RenderOpType.TERRAIN;
            op.y = sortY; 
            op.z = 0; 

            op.tx = px; 
            op.ty = visualBaseY; // Base of column
            op.th = h;           // Height to extrude UP from base

            op.tsize = HEX_SIZE;
            op.ttheme = theme;
            op.ttype = scene.textureType;
            op.tdetail = theme.detail;
            op.tq = q; op.tr = r;

            // Overlays (Drawn on SURFACE)
            // The renderer uses op.ty - op.th to find the top surface.
            op.oStatus = this._unitVisualStatus.get(key);
            op.oDanger = engine.zones.getZoneAt(q, r);
            op.oHazard = engine.hazards.getHazardAt(q, r);

            // D. Interactive & Lighting
            let lightColor = null;
            let lightIntensity = 0;
            for (const p of projectiles) {
                // Projectiles emit light relative to their ground position proximity
                const distSq = (p.x - px)**2 + (p.y - py)**2;
                if (distSq < PROJ_LIGHT_RADIUS_SQ) {
                    lightColor = p.skill.color;
                    lightIntensity += (1 - Math.sqrt(distSq) / 40);
                }
            }
            op.oLightCol = lightColor;
            op.oLightInt = Math.min(1, lightIntensity);

            // Range Highlight
            let isRange = false;
            let rangeColor = '';
            if (hoveredSkill && highlightAgent) {
                const agentH = engine.map.getTerrainHeight(highlightAgent.q, highlightAgent.r);
                const deltaH = agentH - h;
                const bonus = Math.max(0, Math.floor(deltaH / 24)); 
                const dist = HexMath.distance({q, r}, {q: highlightAgent.q, r: highlightAgent.r});

                if (dist <= hoveredSkill.range + bonus) { 
                    isRange = true; 
                    rangeColor = hoveredSkill.color; 
                }
            }

            op.oRange = isRange; op.oRangeCol = rangeColor;
            op.oHover = hoveredHex ? (hoveredHex.q === q && hoveredHex.r === r) : false;
            op.oHasUnit = !engine.isRunning && this._unitPresence.has(key);
            op.time = globalTime;
        }
    }
}

import { GameEvent } from "../../../types";
import { GameEngine } from "../../game";
import { VFXSystem } from "../vfx";
import { GridSystem } from "../grid";
import { CameraSystem } from "../CameraSystem";
import { HexUtils } from "../../utils";
import { UNIT_BODY_OFFSET } from "../../../constants";

// Sub-Handlers
import { CombatVFXHandler } from "./handlers/CombatVFXHandler";
import { UnitVFXHandler } from "./handlers/UnitVFXHandler";
import { CinematicVFXHandler } from "./handlers/CinematicVFXHandler";

// Types
export interface Point3D { x: number; y: number; z: number; }

export class EventVFXMapper {

    public process(
        event: GameEvent, 
        engine: GameEngine, 
        vfx: VFXSystem, 
        grid: GridSystem, 
        camera: CameraSystem
    ) {
        // 1. Resolve Spatial Context with Full 3D Logic
        const origin = this.resolvePoint(event.pos.x, event.pos.y, event.sourceId, engine, grid);
        let target = this.resolvePoint(event.pos.x, event.pos.y, event.targetId, engine, grid);

        // Resolve Pure Ground Z for effects that must sit on the floor
        const groundHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const groundZ = grid.getTerrainHeight(groundHex.q, groundHex.r, engine);

        // Fallback for non-unit targets (ground click actions)
        if (!event.targetId) target.z = groundZ + 20;

        // 2. Route to Specialized Handlers
        switch (event.type) {

            case 'DAMAGE': 
            case 'PROJECTILE_HIT': 
            case 'IMPACT_AOE':
                CombatVFXHandler.handle(event, vfx, camera, target, groundZ);
                break;

            case 'DEATH':
            case 'SPAWN':
            case 'CAST_BREAK':
                UnitVFXHandler.handle(event, engine, vfx, camera, origin, groundZ);
                break;

            case 'VISUAL_SLASH':
            case 'VISUAL_BEAM':
                CinematicVFXHandler.handle(event, engine, vfx, grid, camera, origin, target);
                break;
        }
    }

    private resolvePoint(defaultX: number, defaultY: number, agentId: string | undefined, engine: GameEngine, grid: GridSystem): Point3D {
        let agent = agentId ? engine.agents.find(a => a.id === agentId) : null;

        // If ID matches, snap to that unit's physical center
        if (agent) {
            const terrainH = grid.getTerrainHeight(agent.q, agent.r, engine);
            return {
                x: agent.px,
                y: agent.py,
                // Critical: Target is Chest Height (Terrain + PhysZ + Offset)
                z: terrainH + agent.physics.z + UNIT_BODY_OFFSET
            };
        }

        // Otherwise, resolve terrain height at the event coordinates
        const hex = HexUtils.fromPx(defaultX, defaultY, engine.mapConfig);
        const terrainH = grid.getTerrainHeight(hex.q, hex.r, engine);

        return { x: defaultX, y: defaultY, z: terrainH };
    }
}

import { Agent } from "../../../../game";
import { SpriteManager } from "../../../sprites";
import { UnitIndicatorPainter } from "./UnitIndicatorPainter";
import { MovementType } from "../../../../../types";
import { UnitFlightPainter } from "./UnitFlightPainter";
import { VFXFactory } from "../../../graphics/VFXFactory";

export const UnitShadowPainter = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, px: number, py: number, pz: number, t: number, isSilhouette: boolean) {
        if (isSilhouette || agent.visualStatus === 'POLYMORPH') return;

        const assets = SpriteManager.getUnitImages(agent.role, agent.team);

        // Calculate Surface Y (Where the shadow falls)
        // py passed here is Base Y. pz is Total Height.
        // We assume we want shadow at Surface.
        // We need the Terrain Height from somewhere. 
        // NOTE: UnitVisualProcessor calculates terrainHeight. 
        // pz = terrainHeight + physicsZ.
        // We can approximate surface if we don't have explicit terrainHeight here by assuming physicsZ is 0 if grounded.
        // BUT, for flying units, we need strict separation.
        // For now, we will assume 'py' passed to this function is the Base, 
        // and we need to draw at Base - TerrainHeight.
        // However, standard call signature in UnitRenderSystem passes 'th' which is 'totalHeight'.
        // Let's rely on the passed coordinates which are usually correct for the body.
        // BUT Shadows need to be on the floor.

        // Correction: UnitRenderSystem passes (px, py, pz) where py is BASE ground Y.
        // We need to subtract terrain height to get to the visual surface.
        // Since we don't have terrain height passed explicitly, we derive it:
        // terrainH = pz - agent.physics.z;
        const terrainH = Math.max(0, pz - agent.physics.z);
        const surfaceY = py - terrainH;

        ctx.save();
        ctx.translate(px, surfaceY); // Draw at SURFACE level

        // 1. Drop Shadow (Optimized)
        // Shadow shrinks as unit jumps high
        const jumpHeight = agent.physics.z;
        const shadowScale = Math.max(0.6, 1.0 - (jumpHeight / 400));
        const shadowAlpha = Math.max(0.2, 1.0 - (jumpHeight / 200));

        const shadowBlob = VFXFactory.getTexture('SHADOW_BLOB', 'rgba(0,0,0,0.5)'); 

        ctx.save();
        ctx.scale(shadowScale, shadowScale);
        ctx.globalAlpha = shadowAlpha;
        ctx.drawImage(shadowBlob, -48, -24, 96, 48); 
        ctx.restore();

        // 2. Base Token (Stays on ground)
        // Token renders at Surface Level too.
        ctx.save();
        ctx.scale(shadowScale, shadowScale); // Scale token slightly if jumping? No, usually tokens stay flat.
        ctx.globalAlpha = shadowAlpha; // Fade token if jumping high?
        ctx.drawImage(assets.base, -64, -64); 
        ctx.restore();

        // 3. Class Icon (Anchored to ground)
        if (agent.hp > 0) {
            ctx.save();
            const iconBaseY = -20; 
            ctx.translate(0, iconBaseY);
            const breath = Math.sin(t * 2) * 1.5;
            ctx.translate(0, breath);

            ctx.fillStyle = 'rgba(0,0,0,0.4)';
            ctx.beginPath(); ctx.ellipse(0, 28, 14, 6, 0, 0, Math.PI*2); ctx.fill();

            ctx.globalAlpha = 1.0; 
            ctx.shadowColor = 'rgba(0,0,0,0.3)'; ctx.shadowBlur = 5;
            ctx.drawImage(assets.icon, -32, -32, 64, 64);
            ctx.restore();
        }

        // 4. Casting Indicators (Surface Level)
        if (agent.castingSkillIdx !== -1) {
            const skill = agent.skills[agent.castingSkillIdx];
            if (skill) {
                const progress = 1 - (agent.castTimer / skill.cast);
                const radius = skill.aoeRadius || 1;
                const isAOE = skill.type === 'AOE';
                const visualRadius = isAOE ? 0.8 : radius;
                UnitIndicatorPainter.drawSkillGroundIndicator(ctx, 0, 0, skill.color, t, progress, visualRadius, skill.tag, isAOE);
            }
        }

        ctx.restore();

        // 5. Flying Anchor Line (Draws from Surface UP to Body)
        if (agent.movementType === MovementType.FLYING && jumpHeight > 5) {
            // Draw relative to Surface
            UnitFlightPainter.drawFlyingAnchor(ctx, agent, t, px, surfaceY, jumpHeight);
        }
    }
};

import { GameEngine } from "../../../game";
import { Vector, HexUtils } from "../../../utils";
import { RenderList, RenderOpType } from "../../../renderers/RenderList";
import { getTransitionOffset } from "../utils";
import { Point } from "../../../../types";
import { PROJECTILE_VISUALS, DEFAULT_PROJECTILE, ProjectileVisualDef } from "../../../../data/vfx/projectile_visuals";
import { TrajectoryMath } from "../../../math/TrajectoryMath";
import { UNIT_BODY_OFFSET } from "../../../../constants"; 

export const ProjectileRenderer = {
    submit(
        renderList: RenderList,
        engine: GameEngine,
        getTerrainHeight: (q: number, r: number) => number,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ) {
        engine.projectiles.forEach(p => {
             const offsetP = getTransitionOffset(p.x, p.y, engine.mapConfig, transitionT, transitionPhase);
             if (offsetP > 800) return;

             const lookupKey = p.skill.visualProjectileEffect || p.skill.id || p.skill.visual || 'BOLT';
             const def: ProjectileVisualDef = PROJECTILE_VISUALS[lookupKey] || DEFAULT_PROJECTILE;

             // --- STRICT Z-AXIS CALCULATION ---
             const startHex = HexUtils.fromPx(p.startX, p.startY, engine.mapConfig);
             const targetHex = HexUtils.fromPx(p.targetPos.x, p.targetPos.y, engine.mapConfig);

             // Start Height: Default to (Terrain + BodyOffset) if not stored
             const hStartTerrain = getTerrainHeight(startHex.q, startHex.r);
             const hStart = (p.startZ !== undefined) ? (hStartTerrain + p.startZ) : (hStartTerrain + UNIT_BODY_OFFSET);

             // End Height: Dynamic. If targeting a unit, aim for their current Chest Height.
             let hEnd = getTerrainHeight(targetHex.q, targetHex.r) + UNIT_BODY_OFFSET; // Default ground target height

             const targetAgent = engine.agents.find(a => a.id === p.targetId);
             if (targetAgent) {
                 const tHex = HexUtils.fromPx(targetAgent.px, targetAgent.py, engine.mapConfig);
                 const tTerrain = getTerrainHeight(tHex.q, tHex.r);
                 // Aim for Chest: Terrain + JumpHeight + BodyOffset
                 hEnd = tTerrain + targetAgent.physics.z + UNIT_BODY_OFFSET;
             }

             let totalDist = Vector.dist({x: p.startX, y: p.startY}, p.targetPos);
             if (totalDist < 1) totalDist = 1;

             // Helper to calculate visual position
             const getVisualPos = (lx: number, ly: number, flightProgress: number): { x: number, y: number, shadowY: number, visualZ: number } => {
                 const t = flightProgress;

                 // Linear height interpolation
                 const idealBaseH = hStart + (hEnd - hStart) * t;

                 // Real-time terrain sample for shadow
                 const currentHex = HexUtils.fromPx(lx, ly, engine.mapConfig);
                 const currentGroundH = getTerrainHeight(currentHex.q, currentHex.r);

                 // Trajectory offsets
                 let heightOffset = 0;
                 let lateralOffset = 0;

                 if (def.trajectory === 'ARC') {
                     const distFactor = Math.min(150, totalDist * 0.25);
                     const baseArc = def.arcHeight || 50;
                     const arcHeight = baseArc + distFactor;
                     heightOffset = TrajectoryMath.arcOffset(t, arcHeight);
                 } 
                 else if (def.trajectory === 'WOBBLE') {
                     const freq = def.wobbleFreq || 0.2;
                     const amp = def.wobbleAmp || 10;
                     lateralOffset = TrajectoryMath.wobbleOffset(lx, ly, freq, amp);
                 }

                 const transOffset = getTransitionOffset(lx, ly, engine.mapConfig, transitionT, transitionPhase);
                 const totalZ = idealBaseH + heightOffset; 

                 // Visual Y = BaseY - TotalZ
                 const visY = ly - totalZ + transOffset;

                 // Shadow Y = BaseY - GroundZ
                 const shadY = ly - currentGroundH + transOffset;

                 return {
                     x: lx + lateralOffset,
                     y: visY,
                     shadowY: shadY,
                     visualZ: totalZ
                 };
             };

             // 3. Current Position Calculation
             const currentDist = Vector.dist({x: p.startX, y: p.startY}, {x: p.x, y: p.y});
             const progress = Math.min(1, Math.max(0, currentDist / totalDist));
             const headVis = getVisualPos(p.x, p.y, progress);

             // 4. Rotation Lookahead
             const lookAheadDist = 10;
             const rawDir = Vector.normalize(Vector.sub(p.targetPos, {x: p.startX, y: p.startY}));
             const nextLx = p.x + rawDir.x * lookAheadDist;
             const nextLy = p.y + rawDir.y * lookAheadDist;
             const nextProgress = Math.min(1, Math.max(0, Vector.dist({x: p.startX, y: p.startY}, {x: nextLx, y: nextLy}) / totalDist));
             const nextVis = getVisualPos(nextLx, nextLy, nextProgress);

             const angle = Math.atan2(nextVis.y - headVis.y, nextVis.x - headVis.x);
             const spin = def.spinSpeed ? (progress * def.spinSpeed) : 0;

             // 5. Trail
             const visualTrail: Point[] = [];
             if ((def.trailLength || 0) > 0 && p.trail.length > 1) {
                 visualTrail.push({ x: headVis.x, y: headVis.y });
                 const pointsToProcess = Math.min(p.trail.length, (def.trailLength || 5) + 1);

                 for (let i = p.trail.length - 1; i >= p.trail.length - pointsToProcess; i--) {
                     if (i < 0) break;
                     const tp = p.trail[i];
                     const tDist = Vector.dist({x: p.startX, y: p.startY}, tp);
                     const tProg = Math.min(1, Math.max(0, tDist / totalDist));
                     const tv = getVisualPos(tp.x, tp.y, tProg);
                     visualTrail.push({ x: tv.x, y: tv.y });
                 }
             }

             // 6. Submit Op
             const op = renderList.next();
             op.type = RenderOpType.PROJECTILE;
             op.y = p.y + offsetP; 
             op.z = 50; 

             op.proj = p;
             op.pVisX = headVis.x;
             op.pVisY = headVis.y;
             op.pVisShadowY = headVis.shadowY;
             op.pSkillVis = def.spriteKey || p.skill.visual || 'BOLT';
             op.pColor = def.colorOverride || p.skill.color;
             op.pIsUlt = p.skill.tag === 'ULT';
             op.pAngle = angle;
             op.pSpin = spin;
             op.pTrail = visualTrail; 

             if (def.renderType === 'RAY' || def.renderType === 'BEAM') {
                 op.pSkillVis = 'BEAM'; 
             }
        });
    }
};

import { GroundHazard } from "../../../../../types";
import { HEX_SIZE, ISO_SCALE_Y } from "../../../../../constants";
import { HAZARD_VISUALS } from "../../../../../data/vfx/hazard_visuals";
import { VFXFactory } from "../../../graphics/VFXFactory";
import { SurfacePainter } from "../../../graphics/painters/SurfacePainter";
import { VolumePainter } from "../../../graphics/painters/VolumePainter";

export const HazardPainter = {
    // x, y here are now VISUAL SURFACE COORDINATES (Top of the block)
    draw(ctx: CanvasRenderingContext2D, x: number, y: number, hazard: GroundHazard, globalTime: number) {
        const def = HAZARD_VISUALS[hazard.type] || HAZARD_VISUALS['GENERIC'];

        if (def.type === 'FOG') {
            const texture = VFXFactory.getTexture('CLOUD', def.primaryColor);
            const size = HEX_SIZE * 3.5;
            const speed = globalTime * def.speed;

            ctx.save();
            ctx.translate(x, y);
            ctx.scale(1, ISO_SCALE_Y);

            ctx.globalCompositeOperation = 'source-over';
            ctx.globalAlpha = def.intensity * 0.4;

            ctx.save();
            ctx.rotate(speed * 0.2);
            ctx.drawImage(texture, -size/2, -size/2, size, size);
            ctx.restore();

            ctx.save();
            ctx.rotate(-speed * 0.3 + 1.0);
            ctx.scale(0.7, 0.7);
            ctx.globalAlpha = def.intensity * 0.6;
            ctx.drawImage(texture, -size/2, -size/2, size, size);
            ctx.restore();

            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = 0.2;
            const glow = VFXFactory.getTexture('GLOW', def.secondaryColor);
            ctx.drawImage(glow, -size*0.4, -size*0.4, size*0.8, size*0.8);

            ctx.restore();
        }
        else if (def.type === 'LIQUID') {
            const speed = globalTime * def.speed;
            const intensity = def.intensity * (0.85 + Math.sin(speed) * 0.15);
            SurfacePainter.drawLiquid(ctx, x, y, def.primaryColor, speed, intensity);
            if (def.cracks) SurfacePainter.drawCracks(ctx, x, y, def.secondaryColor, intensity);
        }
        else if (def.type === 'CRYSTAL') {
            if (def.extrude) VolumePainter.drawExtrusion(ctx, x, y, HEX_SIZE, 8, def.primaryColor, 0.5);

            ctx.save();
            ctx.translate(x, y);
            ctx.scale(1, ISO_SCALE_Y);

            const texture = VFXFactory.getTexture('SHARD', def.secondaryColor);
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = 0.4;

            for(let i=0; i<3; i++) {
                const angle = i * 2.0;
                const dist = 10;
                const px = Math.cos(angle) * dist;
                const py = Math.sin(angle) * dist;
                ctx.drawImage(texture, px-10, py-10, 20, 20);
            }
            ctx.restore();
        }
        else if (def.type === 'VOID_HOLE') {
            ctx.save();
            ctx.translate(x, y);
            ctx.scale(1, ISO_SCALE_Y);

            ctx.fillStyle = '#000';
            ctx.globalAlpha = 0.8;
            ctx.beginPath(); ctx.arc(0, 0, HEX_SIZE * 0.7, 0, Math.PI*2); ctx.fill();

            const grad = ctx.createRadialGradient(0,0,HEX_SIZE*0.5, 0,0,HEX_SIZE);
            grad.addColorStop(0, def.primaryColor);
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = def.intensity;
            ctx.beginPath(); ctx.arc(0, 0, HEX_SIZE, 0, Math.PI*2); ctx.fill();

            ctx.rotate(globalTime * def.speed);
            ctx.strokeStyle = def.secondaryColor;
            ctx.lineWidth = 2;
            ctx.setLineDash([5, 10]);
            ctx.beginPath(); ctx.arc(0, 0, HEX_SIZE * 0.8, 0, Math.PI*2); ctx.stroke();

            ctx.restore();
        }
    }
};

import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { ISO_SCALE_Y } from "../../../constants";

export const ZoneRenderer = {

    /**
     * Renders zone effects on a SPECIFIC TILE.
     * x, y should be the VISUAL SURFACE coordinates (Top of the block).
     */
    drawTileZoneEffect(
        ctx: CanvasRenderingContext2D,
        x: number, y: number, // Visual Top Face
        size: number,
        distToCenter: number, 
        zoneRadius: number,
        color: string,
        progress: number, 
        isEnemy: boolean
    ) {
        ctx.save();
        ctx.translate(x, y);

        const currentWaveRadius = progress * (zoneRadius + 0.5);
        const distDiff = Math.abs(distToCenter - currentWaveRadius);
        const waveWidth = 1.5; 

        let waveIntensity = 0;
        if (distDiff < waveWidth) {
            waveIntensity = (Math.cos((distDiff / waveWidth) * Math.PI) + 1) * 0.5;
        }

        const isInside = distToCenter < currentWaveRadius;
        const drawColor = isEnemy ? '#ef4444' : color;

        // 1. Base Fill
        let baseAlpha = 0;
        if (isEnemy) baseAlpha = 0.2; 
        if (isInside && !isEnemy) baseAlpha = 0.15; 

        if (baseAlpha > 0) {
            ctx.fillStyle = drawColor;
            ctx.globalAlpha = baseAlpha;
            HexGeometry.traceHex(ctx, 0, 0, size * 0.95, true);
            ctx.fill();
        }

        // 2. The Ripple
        if (waveIntensity > 0.05) {
            ctx.strokeStyle = drawColor;
            ctx.lineWidth = 2 + waveIntensity * 2;
            ctx.globalAlpha = waveIntensity;

            const pulseSize = size * (0.9 + waveIntensity * 0.1);

            HexGeometry.traceHex(ctx, 0, 0, pulseSize, true);
            ctx.stroke();

            ctx.lineWidth = 1;
            HexGeometry.traceHex(ctx, 0, 0, pulseSize * 0.7, true);
            ctx.stroke();
        }

        // 3. Border
        if (isEnemy || isInside) {
            const isBorder = Math.abs(distToCenter - zoneRadius) < 0.5;
            if (isBorder) {
                ctx.strokeStyle = drawColor;
                ctx.lineWidth = 1;
                ctx.globalAlpha = 0.5;
                if (isEnemy) ctx.setLineDash([4, 4]);
                HexGeometry.traceHex(ctx, 0, 0, size, true);
                ctx.stroke();
                ctx.setLineDash([]);
            }
        }

        ctx.restore();
    }
};

import { ISO_SCALE_Y } from "../../../constants";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { SurfacePainter } from "../../graphics/painters/SurfacePainter";

export const TerrainRenderer = {

    /**
     * Renders a solid 2.5D hexagonal prism (The Block).
     * @param x Screen X of the base center
     * @param y Screen Y of the base center (Ground Level)
     * @param size Hex radius
     * @param height Vertical extrusion amount (Positive value)
     */
    drawBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number
    ) {
        // Pre-calc visual coordinates
        const topOffset = -height; // Y axis goes down, so height moves Up (Negative Y)

        // Vertices relative to (0,0) center.
        // Indices for Pointy Top (-30 deg start):
        // 0: Top-Right (330)
        // 1: Bottom-Right (30)
        // 2: Bottom (90)
        // 3: Bottom-Left (150)
        // 4: Top-Left (210)
        // 5: Top (270)
        const vertices = HexGeometry.getVertices(size, true); 

        ctx.save();
        ctx.translate(x, y);

        // --- 1. DRAW SIDE WALLS (The Pedestal) ---
        // We draw the two "Front" faces visible from South Camera:
        // Face A: Vertex 3 -> Vertex 2 (Bottom Left Wall)
        // Face B: Vertex 2 -> Vertex 1 (Bottom Right Wall)

        if (height > 0) {
            // Left Face (Lit)
            this.drawSideFace(ctx, vertices, 3, 2, topOffset, theme.sideLight);

            // Right Face (Shadow)
            this.drawSideFace(ctx, vertices, 2, 1, topOffset, theme.sideDark);
        }

        // --- 2. DRAW TOP FACE (The Platform) ---
        ctx.translate(0, topOffset);

        // Gradient Top
        const topGrad = ctx.createLinearGradient(-size, -size, size, size);
        topGrad.addColorStop(0, theme.rim); // Light source top-left
        topGrad.addColorStop(0.5, theme.top);
        topGrad.addColorStop(1, theme.sideDark); // Shadow bottom-right

        ctx.fillStyle = topGrad;

        ctx.beginPath();
        ctx.moveTo(vertices[0].x, vertices[0].y);
        for (let i = 1; i < 6; i++) {
            ctx.lineTo(vertices[i].x, vertices[i].y);
        }
        ctx.closePath();
        ctx.fill();

        // --- 3. EDGE HIGHLIGHT (The Bevel) ---
        // Highlight the top-front edges for distinctness
        ctx.strokeStyle = theme.rim;
        ctx.lineWidth = 1.5;
        ctx.stroke();

        // --- 4. SURFACE DETAILS ---
        if (type === 'MAGMA') {
            SurfacePainter.drawLiquid(ctx, 0, 0, '#ef4444', globalTime, 1.0);
        } else if (type === 'VOID') {
            ctx.strokeStyle = '#334155';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(-10, 0); ctx.lineTo(10, 0);
            ctx.moveTo(0, -10); ctx.lineTo(0, 10);
            ctx.stroke();
        }

        ctx.restore();
    },

    drawSideFace(ctx: CanvasRenderingContext2D, verts: {x:number, y:number}[], i1: number, i2: number, topOffset: number, color: string) {
        ctx.fillStyle = color;
        ctx.beginPath();
        // Start at Bottom-Left of the face
        ctx.moveTo(verts[i1].x, verts[i1].y);
        // Draw to Bottom-Right of the face
        ctx.lineTo(verts[i2].x, verts[i2].y);
        // Draw Up to Top-Right
        ctx.lineTo(verts[i2].x, verts[i2].y + topOffset);
        // Draw to Top-Left
        ctx.lineTo(verts[i1].x, verts[i1].y + topOffset);
        ctx.closePath();
        ctx.fill();

        // Seam/Edge line for definition
        ctx.strokeStyle = 'rgba(0,0,0,0.2)';
        ctx.lineWidth = 0.5;
        ctx.stroke();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        baseX: number, baseY: number, // Base coords
        height: number,
        type: string, 
        detailColor: string,
        q: number, r: number
    ) {
        // Details sit on top face
        const visualY = baseY - height;

        if (type === 'FOREST') {
            const seed = Math.abs(Math.sin(q * 12.9898 + r * 78.233));
            if (seed > 0.6) {
                SurfacePainter.drawDetailTexture(ctx, baseX, visualY, type, detailColor, seed);
            }
        }
    }
};

import { OBSTACLE_STYLES } from "../../constants";
import { createCanvas } from "./CanvasUtils";

export const EnvironmentFactory = {

    generateObstacle(styleKey: string): HTMLCanvasElement {
        // Dimensions
        const width = 80;
        const height = 110;
        const { canvas, ctx } = createCanvas(width, height);
        const cx = width / 2;
        const cy = height - 15; // Bottom anchor point (Ground level)

        // Default Fallback
        const style = OBSTACLE_STYLES[styleKey] || OBSTACLE_STYLES['WALL'];

        // Common Shadow (Matches Hex Shape)
        ctx.fillStyle = 'rgba(0,0,0,0.4)';
        ctx.filter = 'blur(4px)';
        ctx.beginPath();
        // Squashed hexagon shadow approximation
        ctx.moveTo(cx - 20, cy);
        ctx.lineTo(cx, cy + 10);
        ctx.lineTo(cx + 20, cy);
        ctx.lineTo(cx, cy - 10);
        ctx.fill();
        ctx.filter = 'none';

        if (styleKey === 'TREE') {
            // --- STYLIZED PINE ---
            // Trunk
            ctx.fillStyle = '#291815'; 
            ctx.beginPath();
            ctx.moveTo(cx - 6, cy); 
            ctx.lineTo(cx + 6, cy);
            ctx.lineTo(cx + 4, cy - 25);
            ctx.lineTo(cx - 4, cy - 25);
            ctx.fill();

            const layers = 3;
            const topY = cy - 95;
            const bottomY = cy - 20;

            for (let i = 0; i < layers; i++) {
                const ratio = i / layers;
                const layerY = topY + (bottomY - topY) * ratio;
                const spread = 15 + i * 14;

                const grad = ctx.createLinearGradient(0, topY, 0, bottomY);
                grad.addColorStop(0, style.highlight); 
                grad.addColorStop(0.4, style.main); 
                grad.addColorStop(1, style.dark); 

                ctx.fillStyle = grad;
                ctx.beginPath();
                ctx.moveTo(cx, layerY - 18); // Tip
                ctx.quadraticCurveTo(cx - spread * 0.5, layerY + 5, cx - spread, layerY + 15);
                ctx.quadraticCurveTo(cx, layerY + 10, cx + spread, layerY + 15);
                ctx.quadraticCurveTo(cx + spread * 0.5, layerY + 5, cx, layerY - 18);
                ctx.fill();

                ctx.strokeStyle = style.light;
                ctx.lineWidth = 1;
                ctx.beginPath();
                ctx.moveTo(cx, layerY - 18);
                ctx.lineTo(cx - spread, layerY + 15);
                ctx.stroke();
            }

        } else if (styleKey === 'ICE_CRYSTAL') {
            // --- SHARP CRYSTAL CLUSTER ---
            const drawCrystal = (x: number, y: number, w: number, h: number, angle: number, color: string) => {
                ctx.save();
                ctx.translate(x, y);
                ctx.rotate(angle);

                // Left Face
                ctx.fillStyle = style.dark;
                ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(-w, 0); ctx.lineTo(0, 5); ctx.fill();

                // Right Face
                const grad = ctx.createLinearGradient(0, -h, 0, 5);
                grad.addColorStop(0, '#ffffff');
                grad.addColorStop(0.3, style.light);
                grad.addColorStop(1, style.main);
                ctx.fillStyle = grad;
                ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(w, 0); ctx.lineTo(0, 5); ctx.fill();

                ctx.strokeStyle = style.highlight;
                ctx.lineWidth = 2;
                ctx.stroke();
                ctx.restore();
            };

            drawCrystal(cx - 15, cy - 5, 10, 40, -0.2, '#fff');
            drawCrystal(cx + 12, cy, 12, 35, 0.3, '#fff');
            drawCrystal(cx, cy + 5, 16, 65, 0, '#fff'); 

        } else if (styleKey === 'OBSIDIAN_PILLAR') {
            // --- MONOLITH (Hexagonal Prism) ---
            const topY = cy - 75;
            const w = 20;

            // Left Face (Lit)
            ctx.fillStyle = style.main;
            ctx.beginPath();
            ctx.moveTo(cx, topY);
            ctx.lineTo(cx - w, topY + 10);
            ctx.lineTo(cx - w, cy - 10);
            ctx.lineTo(cx, cy);
            ctx.fill();

            // Right Face (Dark)
            ctx.fillStyle = style.dark;
            ctx.beginPath();
            ctx.moveTo(cx, topY);
            ctx.lineTo(cx + w, topY + 10);
            ctx.lineTo(cx + w, cy - 10);
            ctx.lineTo(cx, cy);
            ctx.fill();

            // Top Face
            ctx.fillStyle = style.light;
            ctx.beginPath();
            ctx.moveTo(cx, topY);
            ctx.lineTo(cx + w, topY + 10);
            ctx.lineTo(cx, topY + 20);
            ctx.lineTo(cx - w, topY + 10);
            ctx.fill();

            // Emissive Veins
            ctx.strokeStyle = style.detail;
            ctx.shadowColor = style.highlight;
            ctx.shadowBlur = 10;
            ctx.lineWidth = 2;

            ctx.beginPath();
            ctx.moveTo(cx - 5, cy - 10); ctx.lineTo(cx + 5, cy - 30); ctx.lineTo(cx, cy - 50);
            ctx.stroke();
            ctx.shadowBlur = 0;

        } else {
            // --- WALL / STONE BLOCK (Correct ISO Geometry) ---
            const w = 28; // Half width
            const h = 50; // Height
            const topY = cy - h;
            const tilt = 15; // Isometric skew

            // 1. Left Face (Lit) - Matches Terrain Left Face
            ctx.fillStyle = style.main;
            ctx.beginPath();
            ctx.moveTo(cx, topY + tilt);     // Top Center
            ctx.lineTo(cx - w, topY);        // Top Left
            ctx.lineTo(cx - w, cy - tilt);   // Bottom Left
            ctx.lineTo(cx, cy);              // Bottom Center
            ctx.closePath();
            ctx.fill();

            // 2. Right Face (Dark) - Matches Terrain Right Face
            ctx.fillStyle = style.dark;
            ctx.beginPath();
            ctx.moveTo(cx, topY + tilt);     // Top Center
            ctx.lineTo(cx + w, topY);        // Top Right
            ctx.lineTo(cx + w, cy - tilt);   // Bottom Right
            ctx.lineTo(cx, cy);              // Bottom Center
            ctx.closePath();
            ctx.fill();

            // 3. Top Face (Highlight)
            ctx.fillStyle = style.light;
            ctx.beginPath();
            ctx.moveTo(cx, topY + tilt);
            ctx.lineTo(cx + w, topY);
            ctx.lineTo(cx, topY - tilt);     // Top Back
            ctx.lineTo(cx - w, topY);
            ctx.closePath();
            ctx.fill();

            // 4. Highlight Edges
            ctx.strokeStyle = style.highlight;
            ctx.lineWidth = 1;
            ctx.lineJoin = 'round';

            // Vertical Spine
            ctx.beginPath(); ctx.moveTo(cx, topY + tilt); ctx.lineTo(cx, cy); ctx.stroke();
            // Top Diamond Outline
            ctx.beginPath(); 
            ctx.moveTo(cx, topY + tilt); ctx.lineTo(cx + w, topY); ctx.lineTo(cx, topY - tilt); ctx.lineTo(cx - w, topY); ctx.closePath();
            ctx.stroke();

            // Rivet Details
            ctx.fillStyle = style.dark;
            ctx.beginPath(); ctx.arc(cx, topY + tilt + 10, 2, 0, Math.PI*2); ctx.fill();
            ctx.beginPath(); ctx.arc(cx, topY + tilt + 25, 2, 0, Math.PI*2); ctx.fill();
        }

        return canvas;
    },

    generateIceBlock(): HTMLCanvasElement {
        const width = 96;
        const height = 128;
        const { canvas, ctx } = createCanvas(width, height);
        const cx = width / 2;
        const cy = height - 20;

        // Ice block uses ICE_CRYSTAL theme
        const style = OBSTACLE_STYLES['ICE_CRYSTAL'] || { 
            main: '#7dd3fc', light: '#bae6fd', dark: '#0ea5e9', detail: '#e0f2fe', highlight: '#ffffff' 
        };

        const drawShard = (x: number, y: number, w: number, h: number, angle: number) => {
            ctx.save();
            ctx.translate(x, y);
            ctx.rotate(angle);

            // Left Face
            ctx.fillStyle = style.dark;
            ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(-w, 0); ctx.lineTo(0, w/2); ctx.fill();

            // Right Face
            const grad = ctx.createLinearGradient(0, -h, 0, w/2);
            grad.addColorStop(0, '#fff');
            grad.addColorStop(0.4, style.light);
            grad.addColorStop(1, style.main);
            ctx.fillStyle = grad;

            ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(w, 0); ctx.lineTo(0, w/2); ctx.fill();

            // Highlights
            ctx.strokeStyle = style.highlight;
            ctx.lineWidth = 1;
            ctx.stroke();
            ctx.restore();
        };

        // Cluster of ice shards
        drawShard(cx - 20, cy, 15, 60, -0.3);
        drawShard(cx + 20, cy - 5, 18, 50, 0.3);
        drawShard(cx, cy + 10, 25, 90, 0); // Main center shard

        // Ground ice
        ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';
        ctx.beginPath();
        ctx.ellipse(cx, cy, 30, 10, 0, 0, Math.PI*2);
        ctx.fill();

        return canvas;
    }
};

import { HEX_SIZE, ISO_SCALE_Y } from "../../../constants";

// 1. Static Geometry Cache (Standard Pointy Top Hexagon)
// Angles: 330, 30, 90, 150, 210, 270 degrees.
// Vertex 0: Top-Right, Vertex 1: Bottom-Right, Vertex 2: Bottom... Vertex 5: Top.
const START_ANGLE = -Math.PI / 6; 

// Pre-calculate base vertices (Flat 2D, Radius 1.0)
const BASE_VERTICES: {x: number, y: number}[] = [];
for (let i = 0; i < 6; i++) {
    const angle = START_ANGLE + i * Math.PI / 3;
    BASE_VERTICES.push({
        x: Math.cos(angle),
        y: Math.sin(angle)
    });
}

// 2. Performance Cache
let CACHED_PATH_STD: Path2D | null = null;

export const HexGeometry = {

    /**
     * Get exact vertices for a hex at (0,0) with specified radius.
     * Applies ISO scaling to Y axis.
     * @param radius - The outer radius of the hex (usually HEX_SIZE)
     * @param applyIso - Whether to squash Y for 2.5D view (default true)
     */
    getVertices(radius: number, applyIso: boolean = true): {x: number, y: number}[] {
        const scaleY = applyIso ? ISO_SCALE_Y : 1.0;
        return BASE_VERTICES.map(v => ({
            x: v.x * radius,
            y: v.y * radius * scaleY
        }));
    },

    /**
     * Draw a hex path on the context at (x,y).
     * @param x - Center Screen X
     * @param y - Center Screen Y
     * @param radius - Size
     * @param applyIso - Use ISO projection
     */
    traceHex(ctx: CanvasRenderingContext2D, x: number, y: number, radius: number, applyIso: boolean = true) {
        // Optimization: Use Path2D for standard grid size
        const isStandard = Math.abs(radius - HEX_SIZE) < 0.01 && applyIso;

        if (isStandard) {
            if (!CACHED_PATH_STD) this.rebuildCache();
            ctx.translate(x, y);
            // Path2D must be filled/stroked by caller using the path object, 
            // but to support generic context drawing we manually trace here if not using explicit path API.
            // Using the pre-calc cache is still faster.
        }

        const verts = this.getVertices(radius, applyIso);
        ctx.beginPath();
        ctx.moveTo(x + verts[0].x, y + verts[0].y);
        for (let i = 1; i < 6; i++) {
            ctx.lineTo(x + verts[i].x, y + verts[i].y);
        }
        ctx.closePath();
    },

    rebuildCache() {
        const path = new Path2D();
        const verts = this.getVertices(HEX_SIZE, true);
        path.moveTo(verts[0].x, verts[0].y);
        for (let i = 1; i < 6; i++) {
            path.lineTo(verts[i].x, verts[i].y);
        }
        path.closePath();
        CACHED_PATH_STD = path;
    },

    /**
     * Get vertices for a rotated hexagon (used by VFX).
     */
    traceRotatedHex(ctx: CanvasRenderingContext2D, x: number, y: number, radius: number, rotation: number, applyIso: boolean = true) {
        ctx.beginPath();
        const scaleY = applyIso ? ISO_SCALE_Y : 1.0;

        for (let i = 0; i < 6; i++) {
            const angle = START_ANGLE + i * Math.PI / 3 + rotation;
            const px = x + Math.cos(angle) * radius;
            const py = y + Math.sin(angle) * radius * scaleY;

            if (i === 0) ctx.moveTo(px, py);
            else ctx.lineTo(px, py);
        }
        ctx.closePath();
    }
};

import { Hex, Point, Cube } from "../../types";
import { HEX_SIZE, ISO_SCALE_Y } from "../../constants";

export { Cube };

const SQRT3 = Math.sqrt(3);

export const HexMath = {

    // --- COORDINATE SYSTEMS ---

    axialToCube(h: Hex): Cube {
        return { x: h.q, z: h.r, y: -h.q - h.r };
    },

    cubeToAxial(c: Cube): Hex {
        return { q: c.x, r: c.z };
    },

    cubeRound(frac: Cube): Cube {
        let q = Math.round(frac.x);
        let r = Math.round(frac.z);
        let s = Math.round(frac.y);

        const q_diff = Math.abs(q - frac.x);
        const r_diff = Math.abs(r - frac.z);
        const s_diff = Math.abs(s - frac.y);

        if (q_diff > r_diff && q_diff > s_diff) {
            q = -r - s;
        } else if (r_diff > s_diff) {
            r = -q - s;
        } else {
            s = -q - r;
        }
        return { x: q, y: s, z: r };
    },

    // --- PROJECTION CORE (STRICT SOURCE OF TRUTH) ---

    /**
     * Converts Hex(q, r) to Screen Pixel(x, y).
     * @returns The CENTER POINT of the hexagon's GROUND BASE (Z=0).
     * Updated for POINTY TOP orientation.
     */
    hexToPixel(q: number, r: number, offsetX: number, offsetY: number): Point {
        // Standard Pointy Top Hex to Pixel
        // x = size * (sqrt(3) * q + sqrt(3)/2 * r)
        // y = size * (3/2 * r)
        const x = (SQRT3 * q + SQRT3 / 2 * r) * HEX_SIZE;
        const y = (3 / 2 * r) * HEX_SIZE;

        // Apply ISO Squash (2.5D Projection)
        // Only scale Y.
        return {
            x: x + offsetX,
            y: (y * ISO_SCALE_Y) + offsetY
        };
    },

    /**
     * Converts Screen Pixel(x, y) to Fractional Hex.
     * Inverse of hexToPixel. Assumes Z=0 input.
     */
    pixelToHex(x: number, y: number, offsetX: number, offsetY: number): Hex {
        const dx = x - offsetX;
        const dy = (y - offsetY) / ISO_SCALE_Y; // Un-squash

        const q = (SQRT3 / 3 * dx - 1 / 3 * dy) / HEX_SIZE;
        const r = (2 / 3 * dy) / HEX_SIZE;

        return { q, r };
    },

    // --- GEOMETRY UTILS ---

    distance(a: Hex, b: Hex): number {
        const ac = HexMath.axialToCube(a);
        const bc = HexMath.axialToCube(b);
        return Math.max(Math.abs(ac.x - bc.x), Math.abs(ac.y - bc.y), Math.abs(ac.z - bc.z));
    },

    lerp(a: Hex, b: Hex, t: number): Hex {
        const ac = HexMath.axialToCube(a);
        const bc = HexMath.axialToCube(b);
        const cubeLerp = {
            x: ac.x + (bc.x - ac.x) * t,
            y: ac.y + (bc.y - ac.y) * t,
            z: ac.z + (bc.z - ac.z) * t
        };
        return HexMath.cubeToAxial(HexMath.cubeRound(cubeLerp));
    },

    line(a: Hex, b: Hex): Hex[] {
        const N = HexMath.distance(a, b);
        const results: Hex[] = [];
        const ac = { x: a.q + 1e-6, z: a.r + 1e-6, y: -a.q - a.r - 2e-6 };
        const bc = { x: b.q + 1e-6, z: b.r + 1e-6, y: -b.q - b.r - 2e-6 };
        for (let i = 0; i <= N; i++) {
            const t = N === 0 ? 0.0 : i / N;
            const cubeLerp = {
                x: ac.x + (bc.x - ac.x) * t,
                y: ac.y + (bc.y - ac.y) * t,
                z: ac.z + (bc.z - ac.z) * t
            };
            results.push(HexMath.cubeToAxial(HexMath.cubeRound(cubeLerp)));
        }
        return results;
    },

    range(center: Hex, n: number): Hex[] {
        const results: Hex[] = [];
        for (let q = -n; q <= n; q++) {
            for (let r = Math.max(-n, -q - n); r <= Math.min(n, -q + n); r++) {
                results.push({ q: center.q + q, r: center.r + r });
            }
        }
        return results;
    }
};

import { ISO_SCALE_Y } from "../../../constants";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { SurfacePainter } from "../../graphics/painters/SurfacePainter";

export const TerrainRenderer = {

    /**
     * Renders a solid 2.5D hexagonal prism (The Block).
     * @param x Screen X of the base center
     * @param y Screen Y of the base center (Ground Level)
     * @param size Hex radius
     * @param height Vertical extrusion amount (Positive value)
     */
    drawBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number
    ) {
        // Pre-calc visual coordinates
        const topOffset = -height; // Y axis goes down, so height moves Up (Negative Y)

        // Vertices relative to (0,0) center.
        // Indices for Pointy Top (-30 deg start):
        // 0: Top-Right (330)
        // 1: Bottom-Right (30)
        // 2: Bottom (90) - The Prow
        // 3: Bottom-Left (150)
        // 4: Top-Left (210)
        // 5: Top (270)
        const vertices = HexGeometry.getVertices(size, true); 

        ctx.save();
        ctx.translate(x, y);

        // --- 1. DRAW SIDE WALLS (The Pedestal) ---
        // We draw the two "Front" faces visible from South Camera:
        // Face A: Vertex 3 -> Vertex 2 (Bottom Left Wall)
        // Face B: Vertex 2 -> Vertex 1 (Bottom Right Wall)

        if (height > 0) {
            // Left Face (Lit)
            this.drawSideFace(ctx, vertices, 3, 2, topOffset, theme.sideLight);

            // Right Face (Shadow)
            this.drawSideFace(ctx, vertices, 2, 1, topOffset, theme.sideDark);
        }

        // --- 2. DRAW TOP FACE (The Platform) ---
        ctx.translate(0, topOffset);

        // Gradient Top
        const topGrad = ctx.createLinearGradient(-size, -size, size, size);
        topGrad.addColorStop(0, theme.rim); // Light source top-left
        topGrad.addColorStop(0.5, theme.top);
        topGrad.addColorStop(1, theme.sideDark); // Shadow bottom-right

        ctx.fillStyle = topGrad;

        ctx.beginPath();
        ctx.moveTo(vertices[0].x, vertices[0].y);
        for (let i = 1; i < 6; i++) {
            ctx.lineTo(vertices[i].x, vertices[i].y);
        }
        ctx.closePath();
        ctx.fill();

        // --- 3. EDGE HIGHLIGHT (The Bevel) ---
        // Highlight the top-front edges for distinctness
        ctx.strokeStyle = theme.rim;
        ctx.lineWidth = 1.5;
        ctx.stroke();

        // --- 4. SURFACE DETAILS ---
        if (type === 'MAGMA') {
            SurfacePainter.drawLiquid(ctx, 0, 0, '#ef4444', globalTime, 1.0);
        } else if (type === 'VOID') {
            ctx.strokeStyle = '#334155';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(-10, 0); ctx.lineTo(10, 0);
            ctx.moveTo(0, -10); ctx.lineTo(0, 10);
            ctx.stroke();
        }

        ctx.restore();
    },

    drawSideFace(ctx: CanvasRenderingContext2D, verts: {x:number, y:number}[], i1: number, i2: number, topOffset: number, color: string) {
        ctx.fillStyle = color;
        ctx.beginPath();
        // Start at Bottom-Left of the face
        ctx.moveTo(verts[i1].x, verts[i1].y);
        // Draw to Bottom-Right of the face
        ctx.lineTo(verts[i2].x, verts[i2].y);
        // Draw Up to Top-Right
        ctx.lineTo(verts[i2].x, verts[i2].y + topOffset);
        // Draw to Top-Left
        ctx.lineTo(verts[i1].x, verts[i1].y + topOffset);
        ctx.closePath();
        ctx.fill();

        // Seam/Edge line for definition
        ctx.strokeStyle = 'rgba(0,0,0,0.2)';
        ctx.lineWidth = 0.5;
        ctx.stroke();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        baseX: number, baseY: number, // Base coords
        height: number,
        type: string, 
        detailColor: string,
        q: number, r: number
    ) {
        // Details sit on top face
        const visualY = baseY - height;

        if (type === 'FOREST') {
            const seed = Math.abs(Math.sin(q * 12.9898 + r * 78.233));
            if (seed > 0.6) {
                SurfacePainter.drawDetailTexture(ctx, baseX, visualY, type, detailColor, seed);
            }
        }
    }
};

import { OBSTACLE_STYLES } from "../../constants";
import { createCanvas } from "./CanvasUtils";

export const EnvironmentFactory = {

    generateObstacle(styleKey: string): HTMLCanvasElement {
        // Dimensions
        const width = 80;
        const height = 110;
        const { canvas, ctx } = createCanvas(width, height);
        const cx = width / 2;
        const cy = height - 15; // Bottom anchor point (Ground level)

        // Default Fallback
        const style = OBSTACLE_STYLES[styleKey] || OBSTACLE_STYLES['WALL'];

        // Common Shadow (Matches Hex Shape)
        ctx.fillStyle = 'rgba(0,0,0,0.4)';
        ctx.filter = 'blur(4px)';
        ctx.beginPath();
        // Squashed hexagon shadow approximation
        ctx.moveTo(cx - 20, cy);
        ctx.lineTo(cx, cy + 10);
        ctx.lineTo(cx + 20, cy);
        ctx.lineTo(cx, cy - 10);
        ctx.fill();
        ctx.filter = 'none';

        if (styleKey === 'TREE') {
            // --- STYLIZED PINE ---
            // Trunk
            ctx.fillStyle = '#291815'; 
            ctx.beginPath();
            ctx.moveTo(cx - 6, cy); 
            ctx.lineTo(cx + 6, cy);
            ctx.lineTo(cx + 4, cy - 25);
            ctx.lineTo(cx - 4, cy - 25);
            ctx.fill();

            const layers = 3;
            const topY = cy - 95;
            const bottomY = cy - 20;

            for (let i = 0; i < layers; i++) {
                const ratio = i / layers;
                const layerY = topY + (bottomY - topY) * ratio;
                const spread = 15 + i * 14;

                const grad = ctx.createLinearGradient(0, topY, 0, bottomY);
                grad.addColorStop(0, style.highlight); 
                grad.addColorStop(0.4, style.main); 
                grad.addColorStop(1, style.dark); 

                ctx.fillStyle = grad;
                ctx.beginPath();
                ctx.moveTo(cx, layerY - 18); // Tip
                ctx.quadraticCurveTo(cx - spread * 0.5, layerY + 5, cx - spread, layerY + 15);
                ctx.quadraticCurveTo(cx, layerY + 10, cx + spread, layerY + 15);
                ctx.quadraticCurveTo(cx + spread * 0.5, layerY + 5, cx, layerY - 18);
                ctx.fill();

                ctx.strokeStyle = style.light;
                ctx.lineWidth = 1;
                ctx.beginPath();
                ctx.moveTo(cx, layerY - 18);
                ctx.lineTo(cx - spread, layerY + 15);
                ctx.stroke();
            }

        } else if (styleKey === 'ICE_CRYSTAL') {
            // --- SHARP CRYSTAL CLUSTER ---
            const drawCrystal = (x: number, y: number, w: number, h: number, angle: number, color: string) => {
                ctx.save();
                ctx.translate(x, y);
                ctx.rotate(angle);

                // Left Face
                ctx.fillStyle = style.dark;
                ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(-w, 0); ctx.lineTo(0, 5); ctx.fill();

                // Right Face
                const grad = ctx.createLinearGradient(0, -h, 0, 5);
                grad.addColorStop(0, '#ffffff');
                grad.addColorStop(0.3, style.light);
                grad.addColorStop(1, style.main);
                ctx.fillStyle = grad;
                ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(w, 0); ctx.lineTo(0, 5); ctx.fill();

                ctx.strokeStyle = style.highlight;
                ctx.lineWidth = 2;
                ctx.stroke();
                ctx.restore();
            };

            drawCrystal(cx - 15, cy - 5, 10, 40, -0.2, '#fff');
            drawCrystal(cx + 12, cy, 12, 35, 0.3, '#fff');
            drawCrystal(cx, cy + 5, 16, 65, 0, '#fff'); 

        } else if (styleKey === 'OBSIDIAN_PILLAR') {
            // --- MONOLITH (Hexagonal Prism) ---
            const topY = cy - 75;
            const w = 20;

            // Left Face (Lit)
            ctx.fillStyle = style.main;
            ctx.beginPath();
            ctx.moveTo(cx, topY);
            ctx.lineTo(cx - w, topY + 10);
            ctx.lineTo(cx - w, cy - 10);
            ctx.lineTo(cx, cy);
            ctx.fill();

            // Right Face (Dark)
            ctx.fillStyle = style.dark;
            ctx.beginPath();
            ctx.moveTo(cx, topY);
            ctx.lineTo(cx + w, topY + 10);
            ctx.lineTo(cx + w, cy - 10);
            ctx.lineTo(cx, cy);
            ctx.fill();

            // Top Face
            ctx.fillStyle = style.light;
            ctx.beginPath();
            ctx.moveTo(cx, topY);
            ctx.lineTo(cx + w, topY + 10);
            ctx.lineTo(cx, topY + 20);
            ctx.lineTo(cx - w, topY + 10);
            ctx.fill();

            // Emissive Veins
            ctx.strokeStyle = style.detail;
            ctx.shadowColor = style.highlight;
            ctx.shadowBlur = 10;
            ctx.lineWidth = 2;

            ctx.beginPath();
            ctx.moveTo(cx - 5, cy - 10); ctx.lineTo(cx + 5, cy - 30); ctx.lineTo(cx, cy - 50);
            ctx.stroke();
            ctx.shadowBlur = 0;

        } else {
            // --- WALL / STONE BLOCK (Correct ISO Geometry) ---
            const w = 28; // Half width
            const h = 50; // Height
            const topY = cy - h;
            const tilt = 15; // Isometric skew

            // 1. Left Face (Lit) - Matches Terrain Left Face
            ctx.fillStyle = style.main;
            ctx.beginPath();
            ctx.moveTo(cx, topY + tilt);     // Top Center
            ctx.lineTo(cx - w, topY);        // Top Left
            ctx.lineTo(cx - w, cy - tilt);   // Bottom Left
            ctx.lineTo(cx, cy);              // Bottom Center
            ctx.closePath();
            ctx.fill();

            // 2. Right Face (Dark) - Matches Terrain Right Face
            ctx.fillStyle = style.dark;
            ctx.beginPath();
            ctx.moveTo(cx, topY + tilt);     // Top Center
            ctx.lineTo(cx + w, topY);        // Top Right
            ctx.lineTo(cx + w, cy - tilt);   // Bottom Right
            ctx.lineTo(cx, cy);              // Bottom Center
            ctx.closePath();
            ctx.fill();

            // 3. Top Face (Highlight)
            ctx.fillStyle = style.light;
            ctx.beginPath();
            ctx.moveTo(cx, topY + tilt);
            ctx.lineTo(cx + w, topY);
            ctx.lineTo(cx, topY - tilt);     // Top Back
            ctx.lineTo(cx - w, topY);
            ctx.closePath();
            ctx.fill();

            // 4. Highlight Edges
            ctx.strokeStyle = style.highlight;
            ctx.lineWidth = 1;
            ctx.lineJoin = 'round';

            // Vertical Spine
            ctx.beginPath(); ctx.moveTo(cx, topY + tilt); ctx.lineTo(cx, cy); ctx.stroke();
            // Top Diamond Outline
            ctx.beginPath(); 
            ctx.moveTo(cx, topY + tilt); ctx.lineTo(cx + w, topY); ctx.lineTo(cx, topY - tilt); ctx.lineTo(cx - w, topY); ctx.closePath();
            ctx.stroke();

            // Rivet Details
            ctx.fillStyle = style.dark;
            ctx.beginPath(); ctx.arc(cx, topY + tilt + 10, 2, 0, Math.PI*2); ctx.fill();
            ctx.beginPath(); ctx.arc(cx, topY + tilt + 25, 2, 0, Math.PI*2); ctx.fill();
        }

        return canvas;
    },

    generateIceBlock(): HTMLCanvasElement {
        const width = 96;
        const height = 128;
        const { canvas, ctx } = createCanvas(width, height);
        const cx = width / 2;
        const cy = height - 20;

        // Ice block uses ICE_CRYSTAL theme
        const style = OBSTACLE_STYLES['ICE_CRYSTAL'] || { 
            main: '#7dd3fc', light: '#bae6fd', dark: '#0ea5e9', detail: '#e0f2fe', highlight: '#ffffff' 
        };

        const drawShard = (x: number, y: number, w: number, h: number, angle: number) => {
            ctx.save();
            ctx.translate(x, y);
            ctx.rotate(angle);

            // Left Face
            ctx.fillStyle = style.dark;
            ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(-w, 0); ctx.lineTo(0, w/2); ctx.fill();

            // Right Face
            const grad = ctx.createLinearGradient(0, -h, 0, w/2);
            grad.addColorStop(0, '#fff');
            grad.addColorStop(0.4, style.light);
            grad.addColorStop(1, style.main);
            ctx.fillStyle = grad;

            ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(w, 0); ctx.lineTo(0, w/2); ctx.fill();

            // Highlights
            ctx.strokeStyle = style.highlight;
            ctx.lineWidth = 1;
            ctx.stroke();
            ctx.restore();
        };

        // Cluster of ice shards
        drawShard(cx - 20, cy, 15, 60, -0.3);
        drawShard(cx + 20, cy - 5, 18, 50, 0.3);
        drawShard(cx, cy + 10, 25, 90, 0); // Main center shard

        // Ground ice
        ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';
        ctx.beginPath();
        ctx.ellipse(cx, cy, 30, 10, 0, 0, Math.PI*2);
        ctx.fill();

        return canvas;
    }
};

import { HEX_SIZE, ISO_SCALE_Y } from "../../../constants";

// 1. Static Geometry Cache (Flat Top Hexagon)
// Angles: 0, 60, 120, 180, 240, 300 degrees.
// Vertex 0: Right
// Vertex 1: Bottom-Right
// Vertex 2: Bottom-Left
// Vertex 3: Left
// Vertex 4: Top-Left
// Vertex 5: Top-Right
const START_ANGLE = 0; 

// Pre-calculate base vertices (Flat 2D, Radius 1.0)
const BASE_VERTICES: {x: number, y: number}[] = [];
for (let i = 0; i < 6; i++) {
    const angle = START_ANGLE + i * Math.PI / 3;
    BASE_VERTICES.push({
        x: Math.cos(angle),
        y: Math.sin(angle)
    });
}

// 2. Performance Cache
let CACHED_PATH_STD: Path2D | null = null;

export const HexGeometry = {

    /**
     * Get exact vertices for a hex at (0,0) with specified radius.
     * Applies ISO scaling to Y axis.
     * @param radius - The outer radius of the hex (usually HEX_SIZE)
     * @param applyIso - Whether to squash Y for 2.5D view (default true)
     */
    getVertices(radius: number, applyIso: boolean = true): {x: number, y: number}[] {
        const scaleY = applyIso ? ISO_SCALE_Y : 1.0;
        return BASE_VERTICES.map(v => ({
            x: v.x * radius,
            y: v.y * radius * scaleY
        }));
    },

    /**
     * Draw a hex path on the context at (x,y).
     * @param x - Center Screen X
     * @param y - Center Screen Y
     * @param radius - Size
     * @param applyIso - Use ISO projection
     */
    traceHex(ctx: CanvasRenderingContext2D, x: number, y: number, radius: number, applyIso: boolean = true) {
        // Optimization: Use Path2D for standard grid size
        const isStandard = Math.abs(radius - HEX_SIZE) < 0.01 && applyIso;

        if (isStandard) {
            if (!CACHED_PATH_STD) this.rebuildCache();
            ctx.translate(x, y);
            // Path2D must be filled/stroked by caller using the path object, 
            // but to support generic context drawing we manually trace here if not using explicit path API.
            // Using the pre-calc cache is still faster.
        }

        const verts = this.getVertices(radius, applyIso);
        ctx.beginPath();
        ctx.moveTo(x + verts[0].x, y + verts[0].y);
        for (let i = 1; i < 6; i++) {
            ctx.lineTo(x + verts[i].x, y + verts[i].y);
        }
        ctx.closePath();
    },

    rebuildCache() {
        const path = new Path2D();
        const verts = this.getVertices(HEX_SIZE, true);
        path.moveTo(verts[0].x, verts[0].y);
        for (let i = 1; i < 6; i++) {
            path.lineTo(verts[i].x, verts[i].y);
        }
        path.closePath();
        CACHED_PATH_STD = path;
    },

    /**
     * Get vertices for a rotated hexagon (used by VFX).
     */
    traceRotatedHex(ctx: CanvasRenderingContext2D, x: number, y: number, radius: number, rotation: number, applyIso: boolean = true) {
        ctx.beginPath();
        const scaleY = applyIso ? ISO_SCALE_Y : 1.0;

        for (let i = 0; i < 6; i++) {
            const angle = START_ANGLE + i * Math.PI / 3 + rotation;
            const px = x + Math.cos(angle) * radius;
            const py = y + Math.sin(angle) * radius * scaleY;

            if (i === 0) ctx.moveTo(px, py);
            else ctx.lineTo(px, py);
        }
        ctx.closePath();
    }
};

import { Hex, Point, Cube } from "../../types";
import { HEX_SIZE, ISO_SCALE_Y } from "../../constants";

export { Cube };

const SQRT3 = Math.sqrt(3);

export const HexMath = {

    // --- COORDINATE SYSTEMS ---

    axialToCube(h: Hex): Cube {
        return { x: h.q, z: h.r, y: -h.q - h.r };
    },

    cubeToAxial(c: Cube): Hex {
        return { q: c.x, r: c.z };
    },

    cubeRound(frac: Cube): Cube {
        let q = Math.round(frac.x);
        let r = Math.round(frac.z);
        let s = Math.round(frac.y);

        const q_diff = Math.abs(q - frac.x);
        const r_diff = Math.abs(r - frac.z);
        const s_diff = Math.abs(s - frac.y);

        if (q_diff > r_diff && q_diff > s_diff) {
            q = -r - s;
        } else if (r_diff > s_diff) {
            r = -q - s;
        } else {
            s = -q - r;
        }
        return { x: q, y: s, z: r };
    },

    // --- PROJECTION CORE (FLAT-TOP SOURCE OF TRUTH) ---

    /**
     * Converts Hex(q, r) to Screen Pixel(x, y).
     * @returns The CENTER POINT of the hexagon's GROUND BASE (Z=0).
     * Updated for FLAT TOP orientation.
     */
    hexToPixel(q: number, r: number, offsetX: number, offsetY: number): Point {
        // Flat Top Hex to Pixel
        // x = size * 3/2 * q
        // y = size * sqrt(3) * (r + q/2)
        const x = (3 / 2 * q) * HEX_SIZE;
        const y = (SQRT3 * (r + q / 2)) * HEX_SIZE;

        // Apply ISO Squash (2.5D Projection)
        // Only scale Y.
        return {
            x: x + offsetX,
            y: (y * ISO_SCALE_Y) + offsetY
        };
    },

    /**
     * Converts Screen Pixel(x, y) to Fractional Hex.
     * Inverse of hexToPixel (Flat Top). Assumes Z=0 input.
     */
    pixelToHex(x: number, y: number, offsetX: number, offsetY: number): Hex {
        const dx = x - offsetX;
        const dy = (y - offsetY) / ISO_SCALE_Y; // Un-squash

        // Inverse Flat Top Matrix
        const q = (2 / 3 * dx) / HEX_SIZE;
        const r = (-1 / 3 * dx + SQRT3 / 3 * dy) / HEX_SIZE;

        return { q, r };
    },

    // --- GEOMETRY UTILS ---

    distance(a: Hex, b: Hex): number {
        const ac = HexMath.axialToCube(a);
        const bc = HexMath.axialToCube(b);
        return Math.max(Math.abs(ac.x - bc.x), Math.abs(ac.y - bc.y), Math.abs(ac.z - bc.z));
    },

    lerp(a: Hex, b: Hex, t: number): Hex {
        const ac = HexMath.axialToCube(a);
        const bc = HexMath.axialToCube(b);
        const cubeLerp = {
            x: ac.x + (bc.x - ac.x) * t,
            y: ac.y + (bc.y - ac.y) * t,
            z: ac.z + (bc.z - ac.z) * t
        };
        return HexMath.cubeToAxial(HexMath.cubeRound(cubeLerp));
    },

    line(a: Hex, b: Hex): Hex[] {
        const N = HexMath.distance(a, b);
        const results: Hex[] = [];
        const ac = { x: a.q + 1e-6, z: a.r + 1e-6, y: -a.q - a.r - 2e-6 };
        const bc = { x: b.q + 1e-6, z: b.r + 1e-6, y: -b.q - b.r - 2e-6 };
        for (let i = 0; i <= N; i++) {
            const t = N === 0 ? 0.0 : i / N;
            const cubeLerp = {
                x: ac.x + (bc.x - ac.x) * t,
                y: ac.y + (bc.y - ac.y) * t,
                z: ac.z + (bc.z - ac.z) * t
            };
            results.push(HexMath.cubeToAxial(HexMath.cubeRound(cubeLerp)));
        }
        return results;
    },

    range(center: Hex, n: number): Hex[] {
        const results: Hex[] = [];
        for (let q = -n; q <= n; q++) {
            for (let r = Math.max(-n, -q - n); r <= Math.min(n, -q + n); r++) {
                results.push({ q: center.q + q, r: center.r + r });
            }
        }
        return results;
    }
};

import { ISO_SCALE_Y } from "../../../constants";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { SurfacePainter } from "../../graphics/painters/SurfacePainter";

export const TerrainRenderer = {

    /**
     * Renders a solid 2.5D hexagonal prism (The Block).
     * @param x Screen X of the base center
     * @param y Screen Y of the base center (Ground Level)
     * @param size Hex radius
     * @param height Vertical extrusion amount (Positive value)
     */
    drawBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number
    ) {
        // Pre-calc visual coordinates
        const topOffset = -height; // Y axis goes down, so height moves Up (Negative Y)

        // Vertices relative to (0,0) center.
        // Indices for Flat Top (0 deg start):
        // 0: Right (0)
        // 1: Bottom-Right (60)
        // 2: Bottom-Left (120)
        // 3: Left (180)
        // 4: Top-Left (240)
        // 5: Top-Right (300)
        const vertices = HexGeometry.getVertices(size, true); 

        ctx.save();
        ctx.translate(x, y);

        // --- 1. DRAW SIDE WALLS (The Pedestal) ---
        // For Flat Top Hex viewed from South, we see 3 Faces:
        // Face A: Vertex 3 -> Vertex 2 (Front-Left) - Lit
        // Face B: Vertex 2 -> Vertex 1 (Front-Center) - Medium
        // Face C: Vertex 1 -> Vertex 0 (Front-Right) - Dark

        if (height > 0) {
            // Left-Front (Lit)
            this.drawSideFace(ctx, vertices, 3, 2, topOffset, theme.sideLight);

            // Front-Center (Medium/Dark)
            this.drawSideFace(ctx, vertices, 2, 1, topOffset, theme.sideDark);

            // Right-Front (Shadow)
            // We darken the sideDark color slightly for the rightmost face for depth
            // Or just reuse sideDark. Let's make it distinct if possible, otherwise reuse.
            this.drawSideFace(ctx, vertices, 1, 0, topOffset, theme.sideDark);
        }

        // --- 2. DRAW TOP FACE (The Platform) ---
        ctx.translate(0, topOffset);

        // Gradient Top
        const topGrad = ctx.createLinearGradient(-size, -size, size, size);
        topGrad.addColorStop(0, theme.rim); // Light source top-left
        topGrad.addColorStop(0.5, theme.top);
        topGrad.addColorStop(1, theme.sideDark); // Shadow bottom-right

        ctx.fillStyle = topGrad;

        ctx.beginPath();
        ctx.moveTo(vertices[0].x, vertices[0].y);
        for (let i = 1; i < 6; i++) {
            ctx.lineTo(vertices[i].x, vertices[i].y);
        }
        ctx.closePath();
        ctx.fill();

        // --- 3. EDGE HIGHLIGHT (The Bevel) ---
        // Highlight the top-front edges for distinctness
        ctx.strokeStyle = theme.rim;
        ctx.lineWidth = 1.5;

        // Draw just the front rim: 3 -> 2 -> 1 -> 0
        ctx.beginPath();
        ctx.moveTo(vertices[3].x, vertices[3].y);
        ctx.lineTo(vertices[2].x, vertices[2].y);
        ctx.lineTo(vertices[1].x, vertices[1].y);
        ctx.lineTo(vertices[0].x, vertices[0].y);
        ctx.stroke();

        // --- 4. SURFACE DETAILS ---
        if (type === 'MAGMA') {
            SurfacePainter.drawLiquid(ctx, 0, 0, '#ef4444', globalTime, 1.0);
        } else if (type === 'VOID') {
            ctx.strokeStyle = '#334155';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(-10, 0); ctx.lineTo(10, 0);
            ctx.moveTo(0, -10); ctx.lineTo(0, 10);
            ctx.stroke();
        }

        ctx.restore();
    },

    drawSideFace(ctx: CanvasRenderingContext2D, verts: {x:number, y:number}[], i1: number, i2: number, topOffset: number, color: string) {
        ctx.fillStyle = color;
        ctx.beginPath();
        // Start at Bottom-Left of the face
        ctx.moveTo(verts[i1].x, verts[i1].y);
        // Draw to Bottom-Right of the face
        ctx.lineTo(verts[i2].x, verts[i2].y);
        // Draw Up to Top-Right
        ctx.lineTo(verts[i2].x, verts[i2].y + topOffset);
        // Draw to Top-Left
        ctx.lineTo(verts[i1].x, verts[i1].y + topOffset);
        ctx.closePath();
        ctx.fill();

        // Vertical Seam line
        ctx.strokeStyle = 'rgba(0,0,0,0.2)';
        ctx.lineWidth = 0.5;
        ctx.beginPath();
        ctx.moveTo(verts[i1].x, verts[i1].y);
        ctx.lineTo(verts[i1].x, verts[i1].y + topOffset);
        ctx.stroke();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        baseX: number, baseY: number, // Base coords
        height: number,
        type: string, 
        detailColor: string,
        q: number, r: number
    ) {
        // Details sit on top face
        const visualY = baseY - height;

        if (type === 'FOREST') {
            const seed = Math.abs(Math.sin(q * 12.9898 + r * 78.233));
            if (seed > 0.6) {
                SurfacePainter.drawDetailTexture(ctx, baseX, visualY, type, detailColor, seed);
            }
        }
    }
};

import { OBSTACLE_STYLES } from "../../constants";
import { createCanvas } from "./CanvasUtils";

export const EnvironmentFactory = {

    generateObstacle(styleKey: string): HTMLCanvasElement {
        // Dimensions
        const width = 80;
        const height = 110;
        const { canvas, ctx } = createCanvas(width, height);
        const cx = width / 2;
        const cy = height - 15; // Bottom anchor point (Ground level)

        // Default Fallback
        const style = OBSTACLE_STYLES[styleKey] || OBSTACLE_STYLES['WALL'];

        // Common Shadow (Flat Top Hex Shape)
        ctx.fillStyle = 'rgba(0,0,0,0.4)';
        ctx.filter = 'blur(4px)';
        ctx.beginPath();
        // Squashed flat-top hexagon shadow
        ctx.moveTo(cx - 25, cy);
        ctx.lineTo(cx - 12, cy + 10);
        ctx.lineTo(cx + 12, cy + 10);
        ctx.lineTo(cx + 25, cy);
        ctx.lineTo(cx + 12, cy - 10);
        ctx.lineTo(cx - 12, cy - 10);
        ctx.fill();
        ctx.filter = 'none';

        if (styleKey === 'TREE') {
            // --- STYLIZED PINE ---
            // Trunk
            ctx.fillStyle = '#291815'; 
            ctx.beginPath();
            ctx.moveTo(cx - 6, cy); 
            ctx.lineTo(cx + 6, cy);
            ctx.lineTo(cx + 4, cy - 25);
            ctx.lineTo(cx - 4, cy - 25);
            ctx.fill();

            const layers = 3;
            const topY = cy - 95;
            const bottomY = cy - 20;

            for (let i = 0; i < layers; i++) {
                const ratio = i / layers;
                const layerY = topY + (bottomY - topY) * ratio;
                const spread = 20 + i * 14; // Wider for flat top

                const grad = ctx.createLinearGradient(0, topY, 0, bottomY);
                grad.addColorStop(0, style.highlight); 
                grad.addColorStop(0.4, style.main); 
                grad.addColorStop(1, style.dark); 

                ctx.fillStyle = grad;
                ctx.beginPath();
                ctx.moveTo(cx, layerY - 18); // Tip
                ctx.quadraticCurveTo(cx - spread * 0.5, layerY + 5, cx - spread, layerY + 15);
                ctx.quadraticCurveTo(cx, layerY + 10, cx + spread, layerY + 15);
                ctx.quadraticCurveTo(cx + spread * 0.5, layerY + 5, cx, layerY - 18);
                ctx.fill();

                ctx.strokeStyle = style.light;
                ctx.lineWidth = 1;
                ctx.beginPath();
                ctx.moveTo(cx, layerY - 18);
                ctx.lineTo(cx - spread, layerY + 15);
                ctx.stroke();
            }

        } else if (styleKey === 'ICE_CRYSTAL') {
            // --- SHARP CRYSTAL CLUSTER ---
            const drawCrystal = (x: number, y: number, w: number, h: number, angle: number, color: string) => {
                ctx.save();
                ctx.translate(x, y);
                ctx.rotate(angle);

                // Left Face
                ctx.fillStyle = style.dark;
                ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(-w, 0); ctx.lineTo(0, 5); ctx.fill();

                // Right Face
                const grad = ctx.createLinearGradient(0, -h, 0, 5);
                grad.addColorStop(0, '#ffffff');
                grad.addColorStop(0.3, style.light);
                grad.addColorStop(1, style.main);
                ctx.fillStyle = grad;
                ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(w, 0); ctx.lineTo(0, 5); ctx.fill();

                ctx.strokeStyle = style.highlight;
                ctx.lineWidth = 2;
                ctx.stroke();
                ctx.restore();
            };

            drawCrystal(cx - 15, cy - 5, 10, 40, -0.2, '#fff');
            drawCrystal(cx + 12, cy, 12, 35, 0.3, '#fff');
            drawCrystal(cx, cy + 5, 16, 65, 0, '#fff'); 

        } else if (styleKey === 'OBSIDIAN_PILLAR') {
            // --- MONOLITH (Flat Top Hex Prism) ---
            const topY = cy - 75;
            const w = 18;

            // Front-Left Face
            ctx.fillStyle = style.main;
            ctx.beginPath();
            ctx.moveTo(cx - w, topY);
            ctx.lineTo(cx - w * 0.5, topY + 8);
            ctx.lineTo(cx - w * 0.5, cy + 8);
            ctx.lineTo(cx - w, cy);
            ctx.fill();

            // Front-Right Face
            ctx.fillStyle = style.dark;
            ctx.beginPath();
            ctx.moveTo(cx + w, topY);
            ctx.lineTo(cx + w * 0.5, topY + 8);
            ctx.lineTo(cx + w * 0.5, cy + 8);
            ctx.lineTo(cx + w, cy);
            ctx.fill();

            // Center Face
            ctx.fillStyle = style.detail;
            ctx.beginPath();
            ctx.moveTo(cx - w * 0.5, topY + 8);
            ctx.lineTo(cx + w * 0.5, topY + 8);
            ctx.lineTo(cx + w * 0.5, cy + 8);
            ctx.lineTo(cx - w * 0.5, cy + 8);
            ctx.fill();

            // Top Face (Flat Hex)
            ctx.fillStyle = style.light;
            ctx.beginPath();
            ctx.moveTo(cx - w, topY);
            ctx.lineTo(cx - w*0.5, topY - 5);
            ctx.lineTo(cx + w*0.5, topY - 5);
            ctx.lineTo(cx + w, topY);
            ctx.lineTo(cx + w*0.5, topY + 8);
            ctx.lineTo(cx - w*0.5, topY + 8);
            ctx.fill();

            // Emissive
            ctx.strokeStyle = style.highlight;
            ctx.shadowColor = style.highlight;
            ctx.shadowBlur = 10;
            ctx.lineWidth = 2;

            ctx.beginPath();
            ctx.moveTo(cx, cy - 20); ctx.lineTo(cx, cy - 50);
            ctx.stroke();
            ctx.shadowBlur = 0;

        } else {
            // --- WALL / STONE BLOCK (Correct ISO Geometry for Flat Top) ---
            const w = 35; // Wider for flat top
            const h = 50; 
            const topY = cy - h;
            const tilt = 10;

            // 1. Left Face (Lit)
            ctx.fillStyle = style.main;
            ctx.beginPath();
            ctx.moveTo(cx - w, topY + tilt); 
            ctx.lineTo(cx, topY + tilt*2); 
            ctx.lineTo(cx, cy + tilt);
            ctx.lineTo(cx - w, cy);
            ctx.fill();

            // 2. Right Face (Dark)
            ctx.fillStyle = style.dark;
            ctx.beginPath();
            ctx.moveTo(cx + w, topY + tilt); 
            ctx.lineTo(cx, topY + tilt*2); 
            ctx.lineTo(cx, cy + tilt);
            ctx.lineTo(cx + w, cy);
            ctx.fill();

            // 3. Top Face
            ctx.fillStyle = style.light;
            ctx.beginPath();
            ctx.moveTo(cx - w, topY + tilt);
            ctx.lineTo(cx, topY);
            ctx.lineTo(cx + w, topY + tilt);
            ctx.lineTo(cx, topY + tilt*2);
            ctx.fill();

            // 4. Highlight Edges
            ctx.strokeStyle = style.highlight;
            ctx.lineWidth = 1;
            ctx.lineJoin = 'round';

            // Center Spine
            ctx.beginPath(); ctx.moveTo(cx, topY + tilt*2); ctx.lineTo(cx, cy + tilt); ctx.stroke();
            // Top Outline
            ctx.beginPath(); 
            ctx.moveTo(cx - w, topY + tilt); ctx.lineTo(cx, topY); ctx.lineTo(cx + w, topY + tilt); 
            ctx.stroke();

            // Rivet Details
            ctx.fillStyle = style.dark;
            ctx.beginPath(); ctx.arc(cx, topY + tilt*2 + 10, 2, 0, Math.PI*2); ctx.fill();
            ctx.beginPath(); ctx.arc(cx, topY + tilt*2 + 25, 2, 0, Math.PI*2); ctx.fill();
        }

        return canvas;
    },

    generateIceBlock(): HTMLCanvasElement {
        const width = 96;
        const height = 128;
        const { canvas, ctx } = createCanvas(width, height);
        const cx = width / 2;
        const cy = height - 20;

        // Ice block uses ICE_CRYSTAL theme
        const style = OBSTACLE_STYLES['ICE_CRYSTAL'] || { 
            main: '#7dd3fc', light: '#bae6fd', dark: '#0ea5e9', detail: '#e0f2fe', highlight: '#ffffff' 
        };

        const drawShard = (x: number, y: number, w: number, h: number, angle: number) => {
            ctx.save();
            ctx.translate(x, y);
            ctx.rotate(angle);

            // Left Face
            ctx.fillStyle = style.dark;
            ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(-w, 0); ctx.lineTo(0, w/2); ctx.fill();

            // Right Face
            const grad = ctx.createLinearGradient(0, -h, 0, w/2);
            grad.addColorStop(0, '#fff');
            grad.addColorStop(0.4, style.light);
            grad.addColorStop(1, style.main);
            ctx.fillStyle = grad;

            ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(w, 0); ctx.lineTo(0, w/2); ctx.fill();

            // Highlights
            ctx.strokeStyle = style.highlight;
            ctx.lineWidth = 1;
            ctx.stroke();
            ctx.restore();
        };

        // Cluster of ice shards
        drawShard(cx - 20, cy, 15, 60, -0.3);
        drawShard(cx + 20, cy - 5, 18, 50, 0.3);
        drawShard(cx, cy + 10, 25, 90, 0); // Main center shard

        // Ground ice
        ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';
        ctx.beginPath();
        ctx.ellipse(cx, cy, 30, 10, 0, 0, Math.PI*2);
        ctx.fill();

        return canvas;
    }
};

import { ISO_SCALE_Y } from "../../../constants";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { SurfacePainter } from "../../graphics/painters/SurfacePainter";

const SLAB_THICKNESS = 12; // Visual thickness of the base floor plate

export const TerrainRenderer = {

    /**
     * Renders a solid 2.5D hexagonal prism (The Block).
     * @param x Screen X of the base center
     * @param y Screen Y of the base center (Ground Level)
     * @param size Hex radius
     * @param height Vertical extrusion amount (Positive value)
     */
    drawBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number
    ) {
        // Pre-calc visual coordinates
        // Top Surface is at y - height
        // Bottom Surface is at y + SLAB_THICKNESS
        const topOffset = -height;
        const bottomOffset = SLAB_THICKNESS;

        // Vertices relative to (0,0) center.
        // Indices for Flat Top (0 deg start):
        // 0: Right (0)
        // 1: Bottom-Right (60)
        // 2: Bottom-Left (120)
        // 3: Left (180)
        // 4: Top-Left (240)
        // 5: Top-Right (300)
        const vertices = HexGeometry.getVertices(size, true); 

        ctx.save();
        ctx.translate(x, y);

        // --- 1. DRAW SIDE WALLS (The Pedestal) ---
        // For Flat Top Hex viewed from South, we see 3 Faces:
        // Face A: Vertex 3 -> Vertex 2 (Front-Left) - Lit
        // Face B: Vertex 2 -> Vertex 1 (Front-Center) - Medium
        // Face C: Vertex 1 -> Vertex 0 (Front-Right) - Dark

        // Always draw walls if there is height OR slab thickness (which is always true now)
        // Left-Front (Lit)
        this.drawSideFace(ctx, vertices, 3, 2, topOffset, bottomOffset, theme.sideLight);

        // Front-Center (Medium/Dark)
        this.drawSideFace(ctx, vertices, 2, 1, topOffset, bottomOffset, theme.sideDark);

        // Right-Front (Shadow)
        this.drawSideFace(ctx, vertices, 1, 0, topOffset, bottomOffset, theme.sideDark);

        // --- 2. DRAW TOP FACE (The Platform) ---
        ctx.translate(0, topOffset);

        // Gradient Top
        const topGrad = ctx.createLinearGradient(-size, -size, size, size);
        topGrad.addColorStop(0, theme.rim); // Light source top-left
        topGrad.addColorStop(0.5, theme.top);
        topGrad.addColorStop(1, theme.sideDark); // Shadow bottom-right

        ctx.fillStyle = topGrad;

        ctx.beginPath();
        ctx.moveTo(vertices[0].x, vertices[0].y);
        for (let i = 1; i < 6; i++) {
            ctx.lineTo(vertices[i].x, vertices[i].y);
        }
        ctx.closePath();
        ctx.fill();

        // --- 3. EDGE HIGHLIGHT (The Bevel) ---
        // Highlight the top-front edges for distinctness
        ctx.strokeStyle = theme.rim;
        ctx.lineWidth = 1.5;

        // Draw just the front rim: 3 -> 2 -> 1 -> 0
        ctx.beginPath();
        ctx.moveTo(vertices[3].x, vertices[3].y);
        ctx.lineTo(vertices[2].x, vertices[2].y);
        ctx.lineTo(vertices[1].x, vertices[1].y);
        ctx.lineTo(vertices[0].x, vertices[0].y);
        ctx.stroke();

        // --- 4. SURFACE DETAILS ---
        if (type === 'MAGMA') {
            SurfacePainter.drawLiquid(ctx, 0, 0, '#ef4444', globalTime, 1.0);
        } else if (type === 'VOID') {
            ctx.strokeStyle = '#334155';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(-10, 0); ctx.lineTo(10, 0);
            ctx.moveTo(0, -10); ctx.lineTo(0, 10);
            ctx.stroke();
        }

        ctx.restore();
    },

    drawSideFace(ctx: CanvasRenderingContext2D, verts: {x:number, y:number}[], i1: number, i2: number, topOffset: number, bottomOffset: number, color: string) {
        ctx.fillStyle = color;
        ctx.beginPath();
        // Start at Bottom-Left of the face (at Slab Base)
        ctx.moveTo(verts[i1].x, verts[i1].y + bottomOffset);
        // Draw to Bottom-Right of the face (at Slab Base)
        ctx.lineTo(verts[i2].x, verts[i2].y + bottomOffset);
        // Draw Up to Top-Right (at Platform Top)
        ctx.lineTo(verts[i2].x, verts[i2].y + topOffset);
        // Draw to Top-Left (at Platform Top)
        ctx.lineTo(verts[i1].x, verts[i1].y + topOffset);
        ctx.closePath();
        ctx.fill();

        // Vertical Seam line
        ctx.strokeStyle = 'rgba(0,0,0,0.2)';
        ctx.lineWidth = 0.5;
        ctx.beginPath();
        ctx.moveTo(verts[i1].x, verts[i1].y + bottomOffset);
        ctx.lineTo(verts[i1].x, verts[i1].y + topOffset);
        ctx.stroke();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        baseX: number, baseY: number, // Base coords
        height: number,
        type: string, 
        detailColor: string,
        q: number, r: number
    ) {
        // Details sit on top face
        const visualY = baseY - height;

        if (type === 'FOREST') {
            const seed = Math.abs(Math.sin(q * 12.9898 + r * 78.233));
            if (seed > 0.6) {
                SurfacePainter.drawDetailTexture(ctx, baseX, visualY, type, detailColor, seed);
            }
        }
    }
};

import { OBSTACLE_STYLES } from "../../constants";
import { createCanvas } from "./CanvasUtils";

export const EnvironmentFactory = {

    generateObstacle(styleKey: string): HTMLCanvasElement {
        // Dimensions
        const width = 96; // Slightly wider for 3-face geometry
        const height = 110;
        const { canvas, ctx } = createCanvas(width, height);
        const cx = width / 2;
        const cy = height - 15; // Bottom anchor point (Ground level)

        // Default Fallback
        const style = OBSTACLE_STYLES[styleKey] || OBSTACLE_STYLES['WALL'];

        // Common Shadow (Flat Top Hex Shape)
        ctx.fillStyle = 'rgba(0,0,0,0.4)';
        ctx.filter = 'blur(4px)';
        ctx.beginPath();
        // Squashed flat-top hexagon shadow
        ctx.moveTo(cx - 30, cy);
        ctx.lineTo(cx - 15, cy + 12);
        ctx.lineTo(cx + 15, cy + 12);
        ctx.lineTo(cx + 30, cy);
        ctx.lineTo(cx + 15, cy - 12);
        ctx.lineTo(cx - 15, cy - 12);
        ctx.fill();
        ctx.filter = 'none';

        if (styleKey === 'TREE') {
            // --- STYLIZED PINE (Rounder for Flat Top) ---
            // Trunk
            ctx.fillStyle = '#291815'; 
            ctx.beginPath();
            ctx.moveTo(cx - 7, cy); 
            ctx.lineTo(cx + 7, cy);
            ctx.lineTo(cx + 5, cy - 25);
            ctx.lineTo(cx - 5, cy - 25);
            ctx.fill();

            const layers = 3;
            const topY = cy - 95;
            const bottomY = cy - 20;

            for (let i = 0; i < layers; i++) {
                const ratio = i / layers;
                const layerY = topY + (bottomY - topY) * ratio;
                const spread = 24 + i * 14; 

                const grad = ctx.createLinearGradient(0, topY, 0, bottomY);
                grad.addColorStop(0, style.highlight); 
                grad.addColorStop(0.4, style.main); 
                grad.addColorStop(1, style.dark); 

                ctx.fillStyle = grad;
                ctx.beginPath();
                ctx.moveTo(cx, layerY - 18); // Tip
                ctx.quadraticCurveTo(cx - spread * 0.5, layerY + 5, cx - spread, layerY + 15);
                ctx.quadraticCurveTo(cx, layerY + 10, cx + spread, layerY + 15);
                ctx.quadraticCurveTo(cx + spread * 0.5, layerY + 5, cx, layerY - 18);
                ctx.fill();

                ctx.strokeStyle = style.light;
                ctx.lineWidth = 1;
                ctx.beginPath();
                ctx.moveTo(cx, layerY - 18);
                ctx.lineTo(cx - spread, layerY + 15);
                ctx.stroke();
            }

        } else if (styleKey === 'ICE_CRYSTAL') {
            // --- SHARP CRYSTAL CLUSTER ---
            // Adjusted spread for flat top base
            const drawCrystal = (x: number, y: number, w: number, h: number, angle: number, color: string) => {
                ctx.save();
                ctx.translate(x, y);
                ctx.rotate(angle);

                // Left Face
                ctx.fillStyle = style.dark;
                ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(-w, 0); ctx.lineTo(0, 5); ctx.fill();

                // Right Face
                const grad = ctx.createLinearGradient(0, -h, 0, 5);
                grad.addColorStop(0, '#ffffff');
                grad.addColorStop(0.3, style.light);
                grad.addColorStop(1, style.main);
                ctx.fillStyle = grad;
                ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(w, 0); ctx.lineTo(0, 5); ctx.fill();

                ctx.strokeStyle = style.highlight;
                ctx.lineWidth = 2;
                ctx.stroke();
                ctx.restore();
            };

            drawCrystal(cx - 18, cy - 5, 12, 45, -0.3, '#fff');
            drawCrystal(cx + 15, cy, 14, 40, 0.3, '#fff');
            drawCrystal(cx, cy + 5, 18, 70, 0, '#fff'); 

        } else if (styleKey === 'OBSIDIAN_PILLAR') {
            // --- MONOLITH (Flat Top Hex Prism) ---
            const topY = cy - 85;
            const w = 22; // Half Width
            const d = 12; // Depth skew

            // 3 Faces Visible from Front

            // 1. Left (Dark)
            ctx.fillStyle = style.dark;
            ctx.beginPath();
            ctx.moveTo(cx - w, topY + d);
            ctx.lineTo(cx - w/2, topY + d*2);
            ctx.lineTo(cx - w/2, cy + d*2);
            ctx.lineTo(cx - w, cy + d);
            ctx.fill();

            // 2. Center (Main)
            ctx.fillStyle = style.main;
            ctx.beginPath();
            ctx.moveTo(cx - w/2, topY + d*2);
            ctx.lineTo(cx + w/2, topY + d*2);
            ctx.lineTo(cx + w/2, cy + d*2);
            ctx.lineTo(cx - w/2, cy + d*2);
            ctx.fill();

            // 3. Right (Lit)
            ctx.fillStyle = style.light;
            ctx.beginPath();
            ctx.moveTo(cx + w/2, topY + d*2);
            ctx.lineTo(cx + w, topY + d);
            ctx.lineTo(cx + w, cy + d);
            ctx.lineTo(cx + w/2, cy + d*2);
            ctx.fill();

            // Top Cap
            ctx.fillStyle = '#000';
            ctx.beginPath();
            ctx.moveTo(cx - w, topY + d);
            ctx.lineTo(cx - w/2, topY + d*2);
            ctx.lineTo(cx + w/2, topY + d*2);
            ctx.lineTo(cx + w, topY + d);
            ctx.lineTo(cx + w/2, topY);
            ctx.lineTo(cx - w/2, topY);
            ctx.fill();

            // Emissive Veins
            ctx.strokeStyle = style.detail;
            ctx.shadowColor = style.highlight;
            ctx.shadowBlur = 10;
            ctx.lineWidth = 2;

            ctx.beginPath();
            ctx.moveTo(cx, cy - 20); ctx.lineTo(cx, cy - 60);
            ctx.stroke();
            ctx.shadowBlur = 0;

        } else {
            // --- WALL / STONE BLOCK (3-Face Perspective) ---
            const w = 40; // Total width
            const h = 55; 
            const topY = cy - h;
            const skew = 10;

            // Coordinates for 3 vertical columns (Left, Center, Right faces)
            const xL = cx - w/2 - 10;
            const xLM = cx - 15;
            const xRM = cx + 15;
            const xR = cx + w/2 + 10;

            const yBack = topY;
            const yFront = topY + skew;
            const yBaseBack = cy;
            const yBaseFront = cy + skew;

            // 1. Left Face (Angled)
            ctx.fillStyle = style.dark;
            ctx.beginPath();
            ctx.moveTo(xL, yBack);
            ctx.lineTo(xLM, yFront);
            ctx.lineTo(xLM, yBaseFront);
            ctx.lineTo(xL, yBaseBack);
            ctx.fill();

            // 2. Center Face (Flat)
            ctx.fillStyle = style.main;
            ctx.beginPath();
            ctx.moveTo(xLM, yFront);
            ctx.lineTo(xRM, yFront);
            ctx.lineTo(xRM, yBaseFront);
            ctx.lineTo(xLM, yBaseFront);
            ctx.fill();

            // 3. Right Face (Angled)
            ctx.fillStyle = style.light; // Simulate light from right
            ctx.beginPath();
            ctx.moveTo(xRM, yFront);
            ctx.lineTo(xR, yBack);
            ctx.lineTo(xR, yBaseBack);
            ctx.lineTo(xRM, yBaseFront);
            ctx.fill();

            // 4. Top Face
            ctx.fillStyle = style.light;
            ctx.globalAlpha = 0.8;
            ctx.beginPath();
            ctx.moveTo(xL, yBack);
            ctx.lineTo(xLM, yFront);
            ctx.lineTo(xRM, yFront);
            ctx.lineTo(xR, yBack);
            ctx.lineTo(xRM, yBack - skew);
            ctx.lineTo(xLM, yBack - skew);
            ctx.fill();
            ctx.globalAlpha = 1.0;

            // 5. Edges
            ctx.strokeStyle = style.highlight;
            ctx.lineWidth = 1;
            ctx.lineJoin = 'round';

            // Vertical Spines
            ctx.beginPath(); ctx.moveTo(xLM, yFront); ctx.lineTo(xLM, yBaseFront); ctx.stroke();
            ctx.beginPath(); ctx.moveTo(xRM, yFront); ctx.lineTo(xRM, yBaseFront); ctx.stroke();

            // Top Outline
            ctx.beginPath(); 
            ctx.moveTo(xL, yBack); ctx.lineTo(xLM, yFront); ctx.lineTo(xRM, yFront); ctx.lineTo(xR, yBack);
            ctx.stroke();

            // Rivets
            ctx.fillStyle = style.dark;
            ctx.beginPath(); ctx.arc(cx, yFront + 15, 3, 0, Math.PI*2); ctx.fill();
        }

        return canvas;
    },

    generateIceBlock(): HTMLCanvasElement {
        const width = 96;
        const height = 128;
        const { canvas, ctx } = createCanvas(width, height);
        const cx = width / 2;
        const cy = height - 20;

        // Ice block uses ICE_CRYSTAL theme
        const style = OBSTACLE_STYLES['ICE_CRYSTAL'] || { 
            main: '#7dd3fc', light: '#bae6fd', dark: '#0ea5e9', detail: '#e0f2fe', highlight: '#ffffff' 
        };

        const drawShard = (x: number, y: number, w: number, h: number, angle: number) => {
            ctx.save();
            ctx.translate(x, y);
            ctx.rotate(angle);

            // Left Face
            ctx.fillStyle = style.dark;
            ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(-w, 0); ctx.lineTo(0, w/2); ctx.fill();

            // Right Face
            const grad = ctx.createLinearGradient(0, -h, 0, w/2);
            grad.addColorStop(0, '#fff');
            grad.addColorStop(0.4, style.light);
            grad.addColorStop(1, style.main);
            ctx.fillStyle = grad;

            ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(w, 0); ctx.lineTo(0, w/2); ctx.fill();

            // Highlights
            ctx.strokeStyle = style.highlight;
            ctx.lineWidth = 1;
            ctx.stroke();
            ctx.restore();
        };

        // Cluster of ice shards
        drawShard(cx - 20, cy, 15, 60, -0.3);
        drawShard(cx + 20, cy - 5, 18, 50, 0.3);
        drawShard(cx, cy + 10, 25, 90, 0); // Main center shard

        // Ground ice
        ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';
        ctx.beginPath();
        ctx.ellipse(cx, cy, 30, 10, 0, 0, Math.PI*2);
        ctx.fill();

        return canvas;
    }
};

import { SceneTheme } from "../../types";
import { HEX_SIZE } from "../../constants";
import { AssetManager } from "../assets";
import { MapConfig } from "../utils";
import { createCanvas } from "../graphics/CanvasUtils";
import { VFXFactory } from "../graphics/VFXFactory";

export class BackgroundRenderer {
    private staticCache: HTMLCanvasElement | null = null;
    private lastSceneId: string = "";
    private lastWidth: number = 0;
    private lastHeight: number = 0;

    public draw(
        ctx: CanvasRenderingContext2D, 
        width: number, 
        height: number, 
        scene: SceneTheme, 
        mapConfig: MapConfig, 
        globalTime: number
    ): void {
        // 1. Check if we need to regenerate static cache
        if (!this.staticCache || this.lastSceneId !== scene.id || this.lastWidth !== width || this.lastHeight !== height) {
            this.updateStaticCache(width, height, scene);
        }

        // 2. Draw Static Layer (Instant blit)
        if (this.staticCache) {
            ctx.drawImage(this.staticCache, 0, 0);
        }

        // 3. Dynamic Elements (Optimized)
        this.drawDynamicElements(ctx, width, height, scene, mapConfig, globalTime);
    }

    private updateStaticCache(w: number, h: number, scene: SceneTheme) {
        // Create or Resize Canvas
        if (!this.staticCache) {
            const { canvas } = createCanvas(w, h);
            this.staticCache = canvas;
        } else {
            this.staticCache.width = w;
            this.staticCache.height = h;
        }

        this.lastSceneId = scene.id;
        this.lastWidth = w;
        this.lastHeight = h;

        const ctx = this.staticCache.getContext('2d')!;
        ctx.clearRect(0, 0, w, h);

        // --- DRAW STATIC CONTENT ---

        // 1. Base Gradient
        const bgGrad = ctx.createLinearGradient(0, 0, 0, h);
        bgGrad.addColorStop(0, scene.background);
        bgGrad.addColorStop(0.5, scene.horizon);
        bgGrad.addColorStop(1, '#020617');
        ctx.fillStyle = bgGrad;
        ctx.fillRect(0, 0, w, h);

        // 2. Horizon Glow (Static)
        const hY = h * 0.6;
        const hGlow = ctx.createRadialGradient(w/2, hY, w*0.1, w/2, hY, w*0.8);
        hGlow.addColorStop(0, scene.horizon);
        hGlow.addColorStop(1, 'rgba(0,0,0,0)');
        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.4;
        ctx.fillStyle = hGlow;
        ctx.fillRect(0, 0, w, h);
        ctx.globalCompositeOperation = 'source-over';
        ctx.globalAlpha = 1.0;

        // 3. Static Stars / Nebula Base
        if (scene.id === 'VOID' || scene.id === 'ICE' || scene.id === 'FOREST') {
             ctx.fillStyle = '#fff';
             const seed = 123; 
             for(let i=0; i<80; i++) {
                 const sx = (Math.sin(i * seed) * 0.5 + 0.5) * w;
                 const sy = (Math.cos(i * seed * 1.5) * 0.5 + 0.5) * h * 0.8;
                 const size = Math.random() * 2;
                 ctx.globalAlpha = 0.6 * (scene.id === 'VOID' ? 0.8 : 0.4);
                 ctx.beginPath(); ctx.arc(sx, sy, size, 0, Math.PI*2); ctx.fill();
             }
        }

        // 4. Distant Silhouette (Static Mountains)
        if (scene.id === 'FOREST' || scene.id === 'ICE' || scene.id === 'DESERT' || scene.id === 'MAGMA') {
            ctx.globalCompositeOperation = 'source-over';
            const drawMountainLayer = (yOffset: number, color: string, roughness: number, seedOffset: number) => {
                ctx.fillStyle = color;
                ctx.beginPath();
                ctx.moveTo(0, h);
                for(let x=0; x<=w; x+=20) {
                    const n = Math.sin(x * 0.01 + seedOffset) * Math.cos(x * 0.03) * roughness;
                    ctx.lineTo(x, h * 0.55 + yOffset + n);
                }
                ctx.lineTo(w, h);
                ctx.fill();
            };
            ctx.globalAlpha = 0.3;
            drawMountainLayer(0, scene.fogColor, 60, 0);
            ctx.globalAlpha = 0.5;
            drawMountainLayer(60, scene.horizon, 40, 100);
        }

        // 5. Vignette (Baked)
        const rad = Math.min(w, h) * 0.8;
        const vig = ctx.createRadialGradient(w/2, h/2, rad * 0.5, w/2, h/2, rad * 1.5);
        vig.addColorStop(0, 'transparent');
        vig.addColorStop(1, 'rgba(0,0,0,0.5)');
        ctx.globalCompositeOperation = 'source-over';
        ctx.globalAlpha = 1.0;
        ctx.fillStyle = vig;
        ctx.fillRect(0, 0, w, h);
    }

    private drawDynamicElements(ctx: CanvasRenderingContext2D, w: number, h: number, scene: SceneTheme, mapConfig: MapConfig, t: number) {
        ctx.save();

        // 1. God Rays (Optimized using Sprite Cache)
        if (scene.id === 'FOREST' || scene.id === 'DESERT') {
            const raySprite = VFXFactory.getTexture('BEAM', 'rgba(255,255,255,0.1)'); // Reuse existing beam texture or specific ray
            const sourceX = w * 0.8 + Math.sin(t * 0.1) * 100;
            const sourceY = -100;

            ctx.globalCompositeOperation = 'overlay';
            ctx.globalAlpha = 0.3; // Lower alpha for subtlety

            // Draw a few large rotated beams instead of complex paths
            ctx.translate(sourceX, sourceY);
            ctx.rotate(Math.PI * 0.6); // Angle down-left

            // Stretch the beam texture to look like a ray
            const rayLen = w * 1.5;
            const rayWidth = 200;

            ctx.drawImage(raySprite, 0, -rayWidth/2, rayLen, rayWidth);

            // Secondary Ray
            ctx.rotate(0.2);
            ctx.drawImage(raySprite, 0, -rayWidth/3, rayLen, rayWidth*0.8);
        }

        // 2. Atmospheric Fog (Screen Space) - Optimized using Cached Sprite
        const mapPxW = mapConfig.w * HEX_SIZE * 2;
        const mapPxH = mapConfig.h * HEX_SIZE * 2;

        ctx.globalCompositeOperation = 'screen';
        const fogColor = scene.fogColor || '#fff';
        const fogSprite = AssetManager.getFogCloud(fogColor); 
        const numClouds = 4; // Reduced from 6

        ctx.setTransform(1, 0, 0, 1, 0, 0); // Reset transform for screen space absolute positioning

        for (let i = 0; i < numClouds; i++) {
            const speed = 20;
            const x = ((t * speed + i * (mapPxW / numClouds)) % (mapPxW * 1.5)) - mapPxW * 0.25;
            const y = (Math.sin(i * 123 + t * 0.1) * 0.5 + 0.5) * mapPxH;
            const size = 300;

            ctx.globalAlpha = 0.05; 
            ctx.drawImage(fogSprite, x - size/2, y - size/2, size, size * 0.6);
        }

        // 3. Ice Aurora (Special)
        if (scene.id === 'ICE') {
            const auroraH = h * 0.4;
            const grad = ctx.createLinearGradient(0, 0, w, 0);
            const offset = (t * 0.2) % 1;
            grad.addColorStop(0, 'transparent');
            grad.addColorStop((0.3 + offset)%1, '#06b6d4');
            grad.addColorStop((0.7 + offset)%1, '#818cf8');
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.globalAlpha = 0.2;
            ctx.globalCompositeOperation = 'screen';
            ctx.beginPath();
            ctx.moveTo(0, auroraH);
            for(let x=0; x<=w; x+=50) {
                ctx.lineTo(x, auroraH + Math.sin(x * 0.01 + t) * 50);
            }
            ctx.lineTo(w, 0);
            ctx.lineTo(0, 0);
            ctx.fill();
        }

        ctx.restore();
    }
}

import { OBSTACLE_STYLES } from "../../constants";
import { createCanvas } from "./CanvasUtils";

export const EnvironmentFactory = {

    generateObstacle(styleKey: string): HTMLCanvasElement {
        // Dimensions
        const width = 96; // Slightly wider for 3-face geometry
        const height = 110;
        const { canvas, ctx } = createCanvas(width, height);
        const cx = width / 2;
        const cy = height - 15; // Bottom anchor point (Ground level)

        // Default Fallback
        const style = OBSTACLE_STYLES[styleKey] || OBSTACLE_STYLES['WALL'];

        // Common Shadow (Flat Top Hex Shape)
        ctx.fillStyle = 'rgba(0,0,0,0.4)';
        ctx.filter = 'blur(4px)';
        ctx.beginPath();
        // Squashed flat-top hexagon shadow
        ctx.moveTo(cx - 30, cy);
        ctx.lineTo(cx - 15, cy + 12);
        ctx.lineTo(cx + 15, cy + 12);
        ctx.lineTo(cx + 30, cy);
        ctx.lineTo(cx + 15, cy - 12);
        ctx.lineTo(cx - 15, cy - 12);
        ctx.fill();
        ctx.filter = 'none';

        if (styleKey === 'TREE') {
            // --- STYLIZED PINE (Rounder for Flat Top) ---
            // Trunk
            ctx.fillStyle = '#291815'; 
            ctx.beginPath();
            ctx.moveTo(cx - 7, cy); 
            ctx.lineTo(cx + 7, cy);
            ctx.lineTo(cx + 5, cy - 25);
            ctx.lineTo(cx - 5, cy - 25);
            ctx.fill();

            const layers = 3;
            const topY = cy - 95;
            const bottomY = cy - 20;

            for (let i = 0; i < layers; i++) {
                const ratio = i / layers;
                const layerY = topY + (bottomY - topY) * ratio;
                const spread = 24 + i * 14; 

                const grad = ctx.createLinearGradient(0, topY, 0, bottomY);
                grad.addColorStop(0, style.highlight); 
                grad.addColorStop(0.4, style.main); 
                grad.addColorStop(1, style.dark); 

                ctx.fillStyle = grad;
                ctx.beginPath();
                ctx.moveTo(cx, layerY - 18); // Tip
                ctx.quadraticCurveTo(cx - spread * 0.5, layerY + 5, cx - spread, layerY + 15);
                ctx.quadraticCurveTo(cx, layerY + 10, cx + spread, layerY + 15);
                ctx.quadraticCurveTo(cx + spread * 0.5, layerY + 5, cx, layerY - 18);
                ctx.fill();

                ctx.strokeStyle = style.light;
                ctx.lineWidth = 1;
                ctx.beginPath();
                ctx.moveTo(cx, layerY - 18);
                ctx.lineTo(cx - spread, layerY + 15);
                ctx.stroke();
            }

        } else if (styleKey === 'ICE_CRYSTAL') {
            // --- SHARP CRYSTAL CLUSTER ---
            // Adjusted spread for flat top base
            const drawCrystal = (x: number, y: number, w: number, h: number, angle: number, color: string) => {
                ctx.save();
                ctx.translate(x, y);
                ctx.rotate(angle);

                // Left Face
                ctx.fillStyle = style.dark;
                ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(-w, 0); ctx.lineTo(0, 5); ctx.fill();

                // Right Face
                const grad = ctx.createLinearGradient(0, -h, 0, 5);
                grad.addColorStop(0, '#ffffff');
                grad.addColorStop(0.3, style.light);
                grad.addColorStop(1, style.main);
                ctx.fillStyle = grad;
                ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(w, 0); ctx.lineTo(0, 5); ctx.fill();

                ctx.strokeStyle = style.highlight;
                ctx.lineWidth = 2;
                ctx.stroke();
                ctx.restore();
            };

            drawCrystal(cx - 18, cy - 5, 12, 45, -0.3, '#fff');
            drawCrystal(cx + 15, cy, 14, 40, 0.3, '#fff');
            drawCrystal(cx, cy + 5, 18, 70, 0, '#fff'); 

        } else if (styleKey === 'OBSIDIAN_PILLAR') {
            // --- MONOLITH (Flat Top Hex Prism) ---
            const topY = cy - 85;
            const w = 22; // Half Width
            const d = 12; // Depth skew

            // 3 Faces Visible from Front

            // 1. Left (Dark)
            ctx.fillStyle = style.dark;
            ctx.beginPath();
            ctx.moveTo(cx - w, topY + d);
            ctx.lineTo(cx - w/2, topY + d*2);
            ctx.lineTo(cx - w/2, cy + d*2);
            ctx.lineTo(cx - w, cy + d);
            ctx.fill();

            // 2. Center (Main)
            ctx.fillStyle = style.main;
            ctx.beginPath();
            ctx.moveTo(cx - w/2, topY + d*2);
            ctx.lineTo(cx + w/2, topY + d*2);
            ctx.lineTo(cx + w/2, cy + d*2);
            ctx.lineTo(cx - w/2, cy + d*2);
            ctx.fill();

            // 3. Right (Lit)
            ctx.fillStyle = style.light;
            ctx.beginPath();
            ctx.moveTo(cx + w/2, topY + d*2);
            ctx.lineTo(cx + w, topY + d);
            ctx.lineTo(cx + w, cy + d);
            ctx.lineTo(cx + w/2, cy + d*2);
            ctx.fill();

            // Top Cap
            ctx.fillStyle = '#000';
            ctx.beginPath();
            ctx.moveTo(cx - w, topY + d);
            ctx.lineTo(cx - w/2, topY + d*2);
            ctx.lineTo(cx + w/2, topY + d*2);
            ctx.lineTo(cx + w, topY + d);
            ctx.lineTo(cx + w/2, topY);
            ctx.lineTo(cx - w/2, topY);
            ctx.fill();

            // Emissive Veins
            ctx.strokeStyle = style.detail;
            ctx.shadowColor = style.highlight;
            ctx.shadowBlur = 10;
            ctx.lineWidth = 2;

            ctx.beginPath();
            ctx.moveTo(cx, cy - 20); ctx.lineTo(cx, cy - 60);
            ctx.stroke();
            ctx.shadowBlur = 0;

        } else {
            // --- WALL / STONE BLOCK (3-Face Perspective) ---
            const w = 40; // Total width
            const h = 55; 
            const topY = cy - h;
            const skew = 10;

            // Coordinates for 3 vertical columns (Left, Center, Right faces)
            const xL = cx - w/2 - 10;
            const xLM = cx - 15;
            const xRM = cx + 15;
            const xR = cx + w/2 + 10;

            const yBack = topY;
            const yFront = topY + skew;
            const yBaseBack = cy;
            const yBaseFront = cy + skew;

            // 1. Left Face (Angled)
            ctx.fillStyle = style.dark;
            ctx.beginPath();
            ctx.moveTo(xL, yBack);
            ctx.lineTo(xLM, yFront);
            ctx.lineTo(xLM, yBaseFront);
            ctx.lineTo(xL, yBaseBack);
            ctx.fill();

            // 2. Center Face (Flat)
            ctx.fillStyle = style.main;
            ctx.beginPath();
            ctx.moveTo(xLM, yFront);
            ctx.lineTo(xRM, yFront);
            ctx.lineTo(xRM, yBaseFront);
            ctx.lineTo(xLM, yBaseFront);
            ctx.fill();

            // 3. Right Face (Angled)
            ctx.fillStyle = style.light; // Simulate light from right
            ctx.beginPath();
            ctx.moveTo(xRM, yFront);
            ctx.lineTo(xR, yBack);
            ctx.lineTo(xR, yBaseBack);
            ctx.lineTo(xRM, yBaseFront);
            ctx.fill();

            // 4. Top Face
            ctx.fillStyle = style.light;
            ctx.globalAlpha = 0.8;
            ctx.beginPath();
            ctx.moveTo(xL, yBack);
            ctx.lineTo(xLM, yFront);
            ctx.lineTo(xRM, yFront);
            ctx.lineTo(xR, yBack);
            ctx.lineTo(xRM, yBack - skew);
            ctx.lineTo(xLM, yBack - skew);
            ctx.fill();
            ctx.globalAlpha = 1.0;

            // 5. Edges
            ctx.strokeStyle = style.highlight;
            ctx.lineWidth = 1;
            ctx.lineJoin = 'round';

            // Vertical Spines
            ctx.beginPath(); ctx.moveTo(xLM, yFront); ctx.lineTo(xLM, yBaseFront); ctx.stroke();
            ctx.beginPath(); ctx.moveTo(xRM, yFront); ctx.lineTo(xRM, yBaseFront); ctx.stroke();

            // Top Outline
            ctx.beginPath(); 
            ctx.moveTo(xL, yBack); ctx.lineTo(xLM, yFront); ctx.lineTo(xRM, yFront); ctx.lineTo(xR, yBack);
            ctx.stroke();

            // Rivets
            ctx.fillStyle = style.dark;
            ctx.beginPath(); ctx.arc(cx, yFront + 15, 3, 0, Math.PI*2); ctx.fill();
        }

        return canvas;
    },

    generateIceBlock(): HTMLCanvasElement {
        const width = 96;
        const height = 128;
        const { canvas, ctx } = createCanvas(width, height);
        const cx = width / 2;
        const cy = height - 20;

        // Ice block uses ICE_CRYSTAL theme
        const style = OBSTACLE_STYLES['ICE_CRYSTAL'] || { 
            main: '#7dd3fc', light: '#bae6fd', dark: '#0ea5e9', detail: '#e0f2fe', highlight: '#ffffff' 
        };

        const drawShard = (x: number, y: number, w: number, h: number, angle: number) => {
            ctx.save();
            ctx.translate(x, y);
            ctx.rotate(angle);

            // Left Face
            ctx.fillStyle = style.dark;
            ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(-w, 0); ctx.lineTo(0, w/2); ctx.fill();

            // Right Face
            const grad = ctx.createLinearGradient(0, -h, 0, w/2);
            grad.addColorStop(0, '#fff');
            grad.addColorStop(0.4, style.light);
            grad.addColorStop(1, style.main);
            ctx.fillStyle = grad;

            ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(w, 0); ctx.lineTo(0, w/2); ctx.fill();

            // Highlights
            ctx.strokeStyle = style.highlight;
            ctx.lineWidth = 1;
            ctx.stroke();
            ctx.restore();
        };

        // Cluster of ice shards
        drawShard(cx - 20, cy, 15, 60, -0.3);
        drawShard(cx + 20, cy - 5, 18, 50, 0.3);
        drawShard(cx, cy + 10, 25, 90, 0); // Main center shard

        // Ground ice
        ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';
        ctx.beginPath();
        ctx.ellipse(cx, cy, 30, 10, 0, 0, Math.PI*2);
