import { Agent, GameEngine } from "../../game";
import { AnimState } from "../../../types";
import { HexUtils } from "../../utils";
import { STATUS_VISUALS } from "../../../data/vfx/status_visuals";

export class ControlSystem {
    // VFX throttling map
    private vfxTimers = new Map<string, number>();

    public update(agent: Agent, dt: number, engine: GameEngine) {
        // 1. Diminishing Returns (DR) Decay
        // DR resets if not applied again within window
        for (const type in agent.drTimers) {
            if (Object.prototype.hasOwnProperty.call(agent.drTimers, type)) {
                agent.drTimers[type] -= dt;
                if (agent.drTimers[type] <= 0) {
                    agent.drStacks[type] = 0;
                    delete agent.drTimers[type];
                }
            }
        }

        // 2. Status Timer Ticks (Mathematical decrement)
        if (agent.banishTimer > 0) agent.banishTimer = Math.max(0, agent.banishTimer - dt);
        if (agent.stunTimer > 0) agent.stunTimer = Math.max(0, agent.stunTimer - dt);
        if (agent.silenceTimer > 0) agent.silenceTimer = Math.max(0, agent.silenceTimer - dt);
        if (agent.rootTimer > 0) agent.rootTimer = Math.max(0, agent.rootTimer - dt);
        if (agent.fearTimer > 0) agent.fearTimer = Math.max(0, agent.fearTimer - dt);
        if (agent.blindTimer > 0) agent.blindTimer = Math.max(0, agent.blindTimer - dt);
        if (agent.tauntTimer > 0) {
            agent.tauntTimer = Math.max(0, agent.tauntTimer - dt);
            if (agent.tauntTimer <= 0) agent.tauntTargetId = null;
        }

        // 3. State Resolution & Priority Logic
        // Priority: Dead > Banish > Stun > Fear > Root

        // A. Banishment (Stasis)
        if (agent.banishTimer > 0) {
            // Apply State
            agent.banished = true;
            agent.isMoving = false;
            agent.path = []; // Clear path

            // Visual override allowed for POLYMORPH/STASIS, otherwise default
            if (agent.visualStatus !== 'POLYMORPH' && agent.visualStatus !== 'STASIS') {
                // Ensure generic banish visual isn't overwriting special ones
            }
            return; // Hard stop
        } else {
            // Cleanup Banish exit
            if (agent.banished) {
                agent.banished = false;
                agent.visualStatus = 'NONE'; // Reset visual
                engine.log(agent, 'CC', '放逐結束', null, '重返戰場');
            }
        }

        // B. Stun (Hard CC)
        if (agent.stunTimer > 0) {
            agent.isMoving = false;
            agent.path = [];
            agent.setAnim(AnimState.STUN);
            return; // Hard stop
        } else {
            // Cleanup Frozen visual if stun ended
            if (agent.visualStatus === 'FROZEN') agent.visualStatus = 'NONE';
        }

        // C. Fear (Uncontrolled Movement)
        if (agent.fearTimer > 0) {
            // Fear overrides normal AI movement
            if (!agent.isMoving && agent.rootTimer <= 0) {
                // Pick random valid neighbor to run to
                const neighbors = HexUtils.neighbors(agent);
                const valid = neighbors.filter(n => 
                    engine.map.isValid(n.q, n.r) && 
                    !engine.map.isBlocked(n.q, n.r, engine, agent.id)
                );

                if (valid.length > 0) {
                    const next = valid[Math.floor(Math.random() * valid.length)];
                    // Panic run speed (1.5x)
                    engine.movement.moveAgentToHex(agent, next, 0, engine, 1.5);
                }
            }
            return; // Logic stop (AI shouldn't run)
        }

        // D. Root (Immobilize)
        if (agent.rootTimer > 0) {
            agent.isMoving = false;
            agent.path = [];
            // Root allows casting/attacking, so we don't return here, 
            // just prevent movement (handled in MovementSystem)
        }

        // 4. Default State Restoration
        // If no Hard CC, ensure animation is correct
        if (!agent.isMoving && agent.castingSkillIdx === -1 && agent.hitFlashTimer <= 0 && agent.hp > 0) {
            if (agent.target) agent.setAnim(AnimState.COMBAT_IDLE);
            else agent.setAnim(AnimState.IDLE);
        }

        // 5. Visual Effects Tick
        this.processStatusVFX(agent, dt, engine);
    }

    private processStatusVFX(agent: Agent, dt: number, engine: GameEngine) {
        if (!engine.renderer) return;

        const checkVFX = (key: string, condition: boolean) => {
            if (!condition) return;
            const def = STATUS_VISUALS[key];
            if (!def || !def.particleEffect) return;

            const timerKey = `${agent.id}_${key}`;
            let t = this.vfxTimers.get(timerKey) || 0;
            t -= dt;

            if (t <= 0) {
                t = def.particleInterval || 0.5;
                const h = engine.map.getTerrainHeight(agent.q, agent.r);
                // Adjust height to body center (approx 45px up)
                engine.renderer.vfx.playEffect(
                    def.particleEffect, 
                    agent.px, agent.py, 
                    h + agent.physics.z + 45
                );
            }
            this.vfxTimers.set(timerKey, t);
        };

        checkVFX('POISON', agent.dotTimer > 0 && agent.dotDmg > 0);
        checkVFX('REGEN', agent.hotTimer > 0);
        checkVFX('BANISH', agent.banished);
        checkVFX('FEAR', agent.fearTimer > 0);
    }
}

import { Agent, GameEngine } from "../../game";

export class EffectSystem {

    // Throttle visual numbers to avoid UI clutter
    private readonly FEEDBACK_INTERVAL = 0.5; 
    private feedbackTimers = new Map<string, number>();

    public update(agent: Agent, dt: number, engine: GameEngine) {
        if (agent.hp <= 0 || agent.banished) return;

        const feedbackKey = agent.id;
        let timer = this.feedbackTimers.get(feedbackKey) || 0;
        timer -= dt;

        // 1. Damage over Time (DoT)
        // Mathematically apply damage per second
        if (agent.dotTimer > 0) {
            agent.dotTimer = Math.max(0, agent.dotTimer - dt);

            const damagePerSec = agent.dotDmg;
            let frameDamage = damagePerSec * dt;

            // Shield Mitigation logic (Standardized)
            if (agent.shield > 0) {
                const absorbed = Math.min(agent.shield, frameDamage);
                agent.shield -= absorbed;
                frameDamage -= absorbed;
            }

            if (frameDamage > 0) {
                agent.hp -= frameDamage;
            }

            // Periodic Visual Feedback
            if (timer <= 0 && agent.dotDmg > 0) { 
                engine.events.push({ 
                    type: 'DAMAGE', 
                    pos: {x: agent.px, y: agent.py}, 
                    value: -Math.floor(damagePerSec), 
                    color: '#10b981', // Poison Green default
                    skill: { ccType: 'DOT' } as any 
                });
                agent.hitFlashTimer = 0.1;
                // Don't reset timer yet, wait for HoT check
            }
        }

        // 2. Heal over Time (HoT)
        if (agent.hotTimer > 0) {
            agent.hotTimer = Math.max(0, agent.hotTimer - dt);

            const healPerSec = agent.hotVal;
            const frameHeal = healPerSec * dt;

            agent.hp = Math.min(agent.maxHp, agent.hp + frameHeal);

            // Periodic Visual Feedback
            if (timer <= 0 && agent.hotVal > 0) {
                engine.events.push({ 
                    type: 'HEAL', 
                    pos: {x: agent.px, y: agent.py}, 
                    value: Math.floor(healPerSec), 
                    color: '#86efac' 
                });
                // Reset timer now
                this.feedbackTimers.set(feedbackKey, this.FEEDBACK_INTERVAL);
            }
        } else {
            // Update timer if we didn't reset it
            if (timer <= 0) this.feedbackTimers.set(feedbackKey, this.FEEDBACK_INTERVAL);
            else this.feedbackTimers.set(feedbackKey, timer);
        }
    }
}

import { GameEngine } from "../game";
import { GroundHazard, Team } from "../../types";
import { HexUtils } from "../utils";
import { HAZARD_VISUALS } from "../../data/vfx/hazard_visuals";

export class HazardSystem {
    // Spatial Hash Map: "q,r" -> Hazard
    public hazards: Map<string, GroundHazard> = new Map();

    public reset() {
        this.hazards.clear();
    }

    public addHazard(
        q: number, r: number, 
        type: 'POISON' | 'FIRE' | 'ICE' | 'GRAVITY' | 'GENERIC', 
        duration: number, 
        sourceId: string, 
        team: Team, 
        color: string,
        power: number,
        interval: number,
        engine?: GameEngine 
    ) {
        if (!engine || !engine.map.isValid(q, r)) return;
        const key = HexUtils.key({q, r});

        // Persistence Logic: Extend existing hazards of same type/team
        const existing = this.hazards.get(key);

        if (existing) {
            if (existing.type === type && existing.team === team) {
                existing.duration = Math.max(existing.duration, duration);
                existing.power = Math.max(existing.power, power); 
                existing.sourceId = sourceId; 
                return;
            }
        }

        // New Hazard Instance
        const hazard: GroundHazard = {
            id: Math.random().toString(36).substr(2, 6),
            q, r, type, duration, sourceId, team, color, power, interval, timer: 0 
        };

        this.hazards.set(key, hazard);

        // Spawn VFX
        if (engine.renderer) {
            const def = HAZARD_VISUALS[type];
            if (def && def.spawnVfx) {
                const px = HexUtils.toPx(q, r, engine.mapConfig);
                const h = engine.map.getTerrainHeight(q, r);
                engine.renderer.vfx.playEffect(def.spawnVfx, px.x, px.y, h);
            }
        }
    }

    public getHazardAt(q: number, r: number): GroundHazard | undefined {
        return this.hazards.get(HexUtils.key({q, r}));
    }

    public update(dt: number, engine: GameEngine) {
        const toRemove: string[] = [];

        // 1. Hazard Lifecycle Management
        for (const [key, h] of this.hazards.entries()) {
            h.duration -= dt;
            h.timer -= dt; 
            if (h.duration <= 0) toRemove.push(key);
        }
        toRemove.forEach(k => this.hazards.delete(k));

        // 2. Spatial Effect Application (Iterate Agents O(N))
        engine.agents.forEach(agent => {
            if (agent.hp <= 0 || agent.banished) return;

            // O(1) Lookup
            const hazard = this.getHazardAt(agent.q, agent.r);
            if (!hazard) return;

            // Hostility Check
            const isHostile = hazard.team !== agent.team;
            if (!isHostile) return;

            // Flyer Immunity Check
            // Flying units avoid Ground Fire/Poison, but Gravity/Generic (Magic) hits them
            if (agent.movementType === 1 && (hazard.type === 'FIRE' || hazard.type === 'POISON')) {
                return;
            }

            // A. Damage Tick
            if (hazard.timer <= 0) {
                const dmg = hazard.power;
                agent.hp = Math.max(0, agent.hp - dmg);

                engine.events.push({ 
                    type: 'DAMAGE', 
                    pos: {x: agent.px, y: agent.py}, 
                    value: -Math.floor(dmg), 
                    color: hazard.color,
                    skill: { color: hazard.color, ccType: 'DOT' } as any 
                });

                engine.log(agent, 'HAZARD', hazard.type, `(${hazard.q},${hazard.r})`, `地形傷害 ${Math.floor(dmg)}`);
            }

            // B. Physics Tick (Continuous)
            if (hazard.type === 'GRAVITY') {
                const center = HexUtils.toPx(hazard.q, hazard.r, engine.mapConfig);
                const dx = center.x - agent.px;
                const dy = center.y - agent.py;
                const dist = Math.sqrt(dx*dx + dy*dy);

                if (dist > 5) {
                    const pullForce = 300; 
                    const fx = (dx/dist) * pullForce;
                    const fy = (dy/dist) * pullForce;

                    // Directly modify physics velocity
                    agent.physics.vx += fx * dt;
                    agent.physics.vy += fy * dt;

                    // Strong Slow
                    agent.moveSpeedMult = 0.3; 
                }
            } else if (hazard.type === 'ICE') {
                // Minor slip? Or just slow?
                agent.moveSpeedMult = 0.6;
            }
        });

        // 3. Reset Hazard Timers (Safe Batch Reset)
        for (const h of this.hazards.values()) {
            if (h.timer <= 0) {
                h.timer = h.interval;
            }
        }
    }
}

import { Agent, GameEngine } from "../../game";
import { Skill, AnimState } from "../../../types";
import { Vector, HexUtils } from "../../utils";

export const CCManager = {

    // Unified Entry Point
    applyCC(
        source: Agent, 
        target: Agent, 
        skill: Skill, 
        type: string | undefined, 
        dur: number | undefined, 
        force: number | undefined, 
        origin: {x: number, y: number} | undefined, 
        engine: GameEngine
    ) {
        if (!type || type === 'NONE') return;

        // 1. DR Check
        const { effectiveDuration, isImmune } = this.checkDR(target, type, dur || 0);

        if (isImmune) {
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "免疫", color: "#9ca3af" });
            return;
        }

        let statusText = "";
        let statusColor = "#fff";

        // 2. Application Logic
        switch (type) {
            case 'STUN':
                // Extend duration logic
                if (effectiveDuration > target.stunTimer) {
                    target.stunTimer = effectiveDuration;
                    target.stunMax = effectiveDuration;
                }
                target.isMoving = false;
                // Don't override DEATH animation
                if (target.hp > 0) target.setAnim(AnimState.STUN);
                statusText = "暈眩"; statusColor = "#facc15";

                // Special Visuals
                if (skill.element === 'ICE') target.visualStatus = 'FROZEN';
                break;

            case 'SILENCE':
                if (effectiveDuration > target.silenceTimer) {
                    target.silenceTimer = effectiveDuration;
                    target.silenceMax = effectiveDuration;
                }
                statusText = "沉默"; statusColor = "#94a3b8";
                break;

            case 'BANISH':
                if (effectiveDuration > target.banishTimer) {
                    target.banishTimer = effectiveDuration;
                    target.banishMax = effectiveDuration;
                }
                target.banished = true;
                target.isMoving = false;
                if (target.hp > 0) target.setAnim(AnimState.STUN);

                statusText = "放逐"; statusColor = "#c084fc";

                // Model Swap
                if (skill.specialVisualStatus) target.visualStatus = skill.specialVisualStatus;
                break;

            case 'ROOT':
                if (effectiveDuration > target.rootTimer) target.rootTimer = effectiveDuration;
                target.isMoving = false;
                statusText = "禁錮"; statusColor = "#fbbf24";
                break;

            case 'FEAR':
                if (effectiveDuration > target.fearTimer) target.fearTimer = effectiveDuration;
                statusText = "恐懼"; statusColor = "#a855f7";
                break;

            case 'TAUNT':
                if (effectiveDuration > target.tauntTimer) {
                    target.tauntTimer = effectiveDuration;
                    target.tauntTargetId = source.id; 
                }
                statusText = "嘲諷"; statusColor = "#ef4444";
                break;

            case 'BLIND':
                if (effectiveDuration > target.blindTimer) target.blindTimer = effectiveDuration;
                statusText = "致盲"; statusColor = "#cbd5e1";
                break;

            case 'SHIELD':
                // Force = Shield Amount
                const amount = force || 50;
                target.shield += amount;
                target.maxShield = Math.max(target.maxShield, target.shield);
                statusText = "護盾"; statusColor = "#bae6fd";
                break;

            case 'KNOCKBACK':
            case 'PULL':
                const result = this.calculateKnockback(target, force || 0, source, origin, type, engine);
                if (result.applied) {
                    statusText = type === 'PULL' ? "牽引" : "擊退";
                    if (target.hp > 0) target.setAnim(AnimState.HIT);
                    target.physics.vz += 150; // Pop up slightly
                }
                break;

            case 'DOT':
                target.dotDmg = force || 10;
                target.dotTimer = effectiveDuration;
                statusText = "中毒"; statusColor = "#10b981";
                break;

            case 'HOT':
                target.hotVal = force || 10;
                target.hotTimer = effectiveDuration;
                statusText = "再生"; statusColor = "#86efac";
                break;
        }

        if (statusText) {
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: statusText, color: statusColor });
            engine.log(source, 'CC', type, target.id, `施加 ${statusText} (${effectiveDuration.toFixed(1)}s)`);
        }
    },

    checkDR(target: Agent, type: string, baseDuration: number) {
        const isHardCC = ['STUN', 'SILENCE', 'BANISH', 'FEAR', 'TAUNT', 'ROOT'].includes(type);
        if (!isHardCC) return { effectiveDuration: baseDuration, isImmune: false };

        const stacks = target.drStacks[type] || 0;
        // Standard exponential decay: 100% -> 50% -> 25% -> 12.5% (Immune)
        const multiplier = Math.pow(0.5, stacks); 

        if (multiplier < 0.2) return { effectiveDuration: 0, isImmune: true };

        // Apply stack
        target.drStacks[type] = stacks + 1;
        target.drTimers[type] = 10.0; // Reset 10s window

        return { effectiveDuration: baseDuration * multiplier, isImmune: false };
    },

    calculateKnockback(target: Agent, force: number, source: Agent, origin: {x: number, y: number} | undefined, type: string, engine: GameEngine) {
        // Force = Number of tiles to push
        const rawForce = Math.max(1, force);
        const resistance = target.weight || 1; 

        const tilesToPush = Math.max(0, rawForce - resistance);
        if (tilesToPush === 0) return { applied: false };

        const originPx = origin ? origin : {x: source.px, y: source.py};

        // Vector from Origin to Target
        const dir = Vector.normalize(Vector.sub({x: target.px, y: target.py}, originPx));

        // PULL inverts direction
        const vector = type === 'KNOCKBACK' ? dir : Vector.mult(dir, -1); 

        let currentH = {q: target.q, r: target.r};
        let finalH = currentH;

        // Iterative Step-Checking (To handle collisions per tile)
        for(let k=0; k<tilesToPush; k++) {
            const neighbors = HexUtils.neighbors(currentH);
            let bestN: any = null;
            let bestDot = -2.0; // Dot product range is -1 to 1

            // Find neighbor that best aligns with force vector
            for(const n of neighbors) {
                const nPx = HexUtils.toPx(n.q, n.r, engine.mapConfig);
                const cPx = HexUtils.toPx(currentH.q, currentH.r, engine.mapConfig);
                const nDir = Vector.normalize(Vector.sub(nPx, cPx));

                const dot = nDir.x * vector.x + nDir.y * vector.y;
                if (dot > bestDot) {
                    bestDot = dot;
                    bestN = n;
                }
            }

            if (bestN) {
                // Collision Logic
                // 1. Map Valid
                if (!engine.map.isValid(bestN.q, bestN.r) || engine.map.hasObstacle(bestN.q, bestN.r)) break; 

                // 2. Unit Collision
                if (engine.getAgentAt(bestN.q, bestN.r)) break; 

                // 3. Cliff Check (Can't be knocked up a huge wall)
                const curHeight = engine.map.getTerrainHeight(currentH.q, currentH.r);
                const nextHeight = engine.map.getTerrainHeight(bestN.q, bestN.r);
                if (nextHeight > curHeight + 24) break; 

                // Success
                currentH = bestN;
                finalH = bestN;
            } else {
                break;
            }
        }

        if (finalH.q !== target.q || finalH.r !== target.r) {
            engine.updateAgentPosition(target, finalH.q, finalH.r);
            // Break any current move
            if (target.isMoving) {
                target.isMoving = false;
                target.path = [];
            }
            return { applied: true };
        }
        return { applied: false };
    }
};

import { OBSTACLE_STYLES } from "../../constants";
import { createCanvas } from "./CanvasUtils";
import { HexGeometry } from "./utils/HexGeometry";

// Standardize Canvas Size to ensure consistent centering
const CANVAS_W = 128;
const CANVAS_H = 160;
const ANCHOR_X = CANVAS_W / 2;
const ANCHOR_Y = CANVAS_H - 20; // Leave small padding at bottom

export const EnvironmentFactory = {

    generateObstacle(styleKey: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(CANVAS_W, CANVAS_H);

        // Setup Anchor: (0,0) is now the center of the hex on the ground
        ctx.translate(ANCHOR_X, ANCHOR_Y);

        const style = OBSTACLE_STYLES[styleKey] || OBSTACLE_STYLES['WALL'];

        // 1. Draw Base Shadow (Strict Hexagon Footprint)
        // Uses HexGeometry to ensure it matches the grid perfectly
        ctx.save();
        ctx.fillStyle = 'rgba(0,0,0,0.3)';
        ctx.filter = 'blur(4px)';
        // Radius 30 matches standard obstacle footprint size relative to HEX_SIZE 36
        HexGeometry.traceHex(ctx, 0, 0, 30, true); 
        ctx.fill();
        ctx.restore();

        // 2. Draw Object based on Type
        if (styleKey === 'TREE') {
            this.drawTree(ctx, style);
        } else if (styleKey === 'ICE_CRYSTAL') {
            this.drawCrystal(ctx, style);
        } else if (styleKey === 'OBSIDIAN_PILLAR') {
            this.drawPillar(ctx, style);
        } else {
            this.drawWall(ctx, style);
        }

        // Mark Anchor for Debugging (Optional, commented out)
        // ctx.fillStyle = 'red'; ctx.fillRect(-2, -2, 4, 4);

        return canvas;
    },

    generateIceBlock(): HTMLCanvasElement {
        // Reuse same coordinate system
        const { canvas, ctx } = createCanvas(CANVAS_W, CANVAS_H);
        ctx.translate(ANCHOR_X, ANCHOR_Y);

        const style = OBSTACLE_STYLES['ICE_CRYSTAL'] || { 
            main: '#7dd3fc', light: '#bae6fd', dark: '#0ea5e9', detail: '#e0f2fe', highlight: '#ffffff' 
        };

        this.drawCrystalShard(ctx, -15, 0, 15, 60, -0.3, style);
        this.drawCrystalShard(ctx, 15, -5, 18, 50, 0.3, style);
        this.drawCrystalShard(ctx, 0, 5, 25, 80, 0, style); // Main Center

        // Ground frost
        ctx.globalCompositeOperation = 'source-over';
        ctx.fillStyle = 'rgba(255, 255, 255, 0.3)';
        ctx.beginPath();
        ctx.ellipse(0, 0, 25, 12, 0, 0, Math.PI*2);
        ctx.fill();

        return canvas;
    },

    // --- PAINTER SUB-ROUTINES (Relative to Ground Center) ---

    drawTree(ctx: CanvasRenderingContext2D, style: any) {
        // Trunk
        ctx.fillStyle = '#291815'; 
        ctx.beginPath();
        ctx.moveTo(-6, 0); 
        ctx.lineTo(6, 0);
        ctx.lineTo(4, -20);
        ctx.lineTo(-4, -20);
        ctx.fill();

        const layers = 3;
        const topY = -100;
        const bottomY = -20;

        for (let i = 0; i < layers; i++) {
            const ratio = i / layers;
            const layerY = topY + (bottomY - topY) * ratio;
            const spread = 24 + i * 12; 

            const grad = ctx.createLinearGradient(0, topY, 0, bottomY);
            grad.addColorStop(0, style.highlight); 
            grad.addColorStop(0.4, style.main); 
            grad.addColorStop(1, style.dark); 

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(0, layerY - 18); // Tip
            ctx.quadraticCurveTo(-spread * 0.5, layerY + 5, -spread, layerY + 15);
            ctx.quadraticCurveTo(0, layerY + 10, spread, layerY + 15);
            ctx.quadraticCurveTo(spread * 0.5, layerY + 5, 0, layerY - 18);
            ctx.fill();

            // Edge Light
            ctx.strokeStyle = style.light;
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(0, layerY - 18);
            ctx.lineTo(-spread, layerY + 15);
            ctx.stroke();
        }
    },

    drawCrystal(ctx: CanvasRenderingContext2D, style: any) {
        this.drawCrystalShard(ctx, -12, -2, 12, 45, -0.3, style);
        this.drawCrystalShard(ctx, 12, 0, 14, 40, 0.3, style);
        this.drawCrystalShard(ctx, 0, 2, 18, 70, 0, style);
    },

    drawCrystalShard(ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, angle: number, style: any) {
        ctx.save();
        ctx.translate(x, y);
        ctx.rotate(angle);

        // Left Face
        ctx.fillStyle = style.dark;
        ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(-w, 0); ctx.lineTo(0, 5); ctx.fill();

        // Right Face
        const grad = ctx.createLinearGradient(0, -h, 0, 5);
        grad.addColorStop(0, '#ffffff');
        grad.addColorStop(0.3, style.light);
        grad.addColorStop(1, style.main);
        ctx.fillStyle = grad;
        ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(w, 0); ctx.lineTo(0, 5); ctx.fill();

        ctx.strokeStyle = style.highlight;
        ctx.lineWidth = 1;
        ctx.stroke();
        ctx.restore();
    },

    drawPillar(ctx: CanvasRenderingContext2D, style: any) {
        // Hex Prism (3-Face)
        const h = 80;
        const w = 20; 
        const topY = -h;
        const d = 10; // Perspective depth

        // Left Face
        ctx.fillStyle = style.dark;
        ctx.beginPath();
        ctx.moveTo(-w, topY + d); ctx.lineTo(-w/2, topY + d*2);
        ctx.lineTo(-w/2, d*2); ctx.lineTo(-w, d);
        ctx.fill();

        // Center Face
        ctx.fillStyle = style.main;
        ctx.beginPath();
        ctx.moveTo(-w/2, topY + d*2); ctx.lineTo(w/2, topY + d*2);
        ctx.lineTo(w/2, d*2); ctx.lineTo(-w/2, d*2);
        ctx.fill();

        // Right Face
        ctx.fillStyle = style.light;
        ctx.beginPath();
        ctx.moveTo(w/2, topY + d*2); ctx.lineTo(w, topY + d);
        ctx.lineTo(w, d); ctx.lineTo(w/2, d*2);
        ctx.fill();

        // Cap
        ctx.fillStyle = '#000';
        ctx.beginPath();
        ctx.moveTo(-w, topY + d); ctx.lineTo(-w/2, topY + d*2);
        ctx.lineTo(w/2, topY + d*2); ctx.lineTo(w, topY + d);
        ctx.lineTo(w/2, topY); ctx.lineTo(-w/2, topY);
        ctx.fill();

        // Vein
        ctx.strokeStyle = style.detail;
        ctx.shadowColor = style.highlight;
        ctx.shadowBlur = 8;
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.moveTo(0, -20); ctx.lineTo(0, -60); ctx.stroke();
        ctx.shadowBlur = 0;
    },

    drawWall(ctx: CanvasRenderingContext2D, style: any) {
        const w = 35;
        const h = 50;
        const skew = 8;

        const xL = -w - 5;
        const xLM = -12;
        const xRM = 12;
        const xR = w + 5;

        // Draw from bottom up
        const yBaseFront = skew;
        const yBaseBack = 0;
        const yTopFront = -h + skew;
        const yTopBack = -h;

        // Left Face
        ctx.fillStyle = style.dark;
        ctx.beginPath();
        ctx.moveTo(xL, yTopBack); ctx.lineTo(xLM, yTopFront);
        ctx.lineTo(xLM, yBaseFront); ctx.lineTo(xL, yBaseBack);
        ctx.fill();

        // Center Face
        ctx.fillStyle = style.main;
        ctx.beginPath();
        ctx.moveTo(xLM, yTopFront); ctx.lineTo(xRM, yTopFront);
        ctx.lineTo(xRM, yBaseFront); ctx.lineTo(xLM, yBaseFront);
        ctx.fill();

        // Right Face
        ctx.fillStyle = style.light;
        ctx.beginPath();
        ctx.moveTo(xRM, yTopFront); ctx.lineTo(xR, yTopBack);
        ctx.lineTo(xR, yBaseBack); ctx.lineTo(xRM, yBaseFront);
        ctx.fill();

        // Top Cap
        ctx.fillStyle = style.light;
        ctx.globalAlpha = 0.8;
        ctx.beginPath();
        ctx.moveTo(xL, yTopBack); ctx.lineTo(xLM, yTopFront);
        ctx.lineTo(xRM, yTopFront); ctx.lineTo(xR, yTopBack);
        ctx.lineTo(xRM, yTopBack - skew); ctx.lineTo(xLM, yTopBack - skew);
        ctx.fill();
        ctx.globalAlpha = 1.0;

        // Edges
        ctx.strokeStyle = style.highlight;
        ctx.lineWidth = 1;
        ctx.beginPath(); 
        ctx.moveTo(xL, yTopBack); ctx.lineTo(xLM, yTopFront); ctx.lineTo(xRM, yTopFront); ctx.lineTo(xR, yTopBack);
        ctx.stroke();
    }
};

import { createCanvas } from "./CanvasUtils";
import { ParticlePainter } from "./painters/ParticlePainter";
import { ProjectilePainter } from "./painters/ProjectilePainter";
import { IconPainter } from "./painters/IconPainter";
import { HexGeometry } from "./utils/HexGeometry";
import { HEX_SIZE } from "../../constants";

// High fidelity texture size
const TEXTURE_SIZE = 128; 
const CENTER = TEXTURE_SIZE / 2;

export class VFXTextureCache {
    private cache: Map<string, HTMLCanvasElement> = new Map();

    public getTexture(type: string, color: string): HTMLCanvasElement {
        // Normalize aliases
        if (type === 'DUST' || type === 'PEBBLE') type = 'RUBBLE';
        if (type === 'RING' || type === 'SHOCKWAVE_RING') type = 'SHOCKWAVE';

        const key = `VFX_${type}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const { canvas, ctx } = createCanvas(TEXTURE_SIZE, TEXTURE_SIZE);
        // Base radius for tile effects
        const r = 40; 

        ctx.translate(CENTER, CENTER);

        // NOTE: For Ground Effects (Zone, Grid, Shockwave), we draw REGULAR geometry (applyIso = false).
        // The Renderer/Painter will handle the 2.5D projection (scale Y).

        switch (type) {
            case 'ZONE_BASE':
                this.drawRegularHex(ctx, r, color, 'FILL_GLOW');
                break;
            case 'GRID_FIELD':
                this.drawGridField(ctx, r, color);
                break;
            case 'ATMOSPHERE':
            case 'GLOW':
                ParticlePainter.drawAtmosphere(ctx, r, color);
                break;
            case 'CLOUD': 
                this.drawCloudTexture(ctx, r, color);
                break;
            case 'SMOKE':
            case 'SMOKE_PUFF':
                ParticlePainter.drawSmoke(ctx, r, color);
                break;
            case 'SHOCKWAVE':
                this.drawShockwave(ctx, r, color);
                break;
            case 'SPIKE':
            case 'SPARK':
                ParticlePainter.drawSpike(ctx, r * (type === 'SPARK' ? 0.3 : 0.8), color);
                break;
            case 'SHARD':
            case 'RUBBLE':
            case 'ROCK':
            case 'CHIP':
                ctx.fillStyle = color;
                // Physical debris is small enough to not care about exact projection
                HexGeometry.traceHex(ctx, 0, 0, r * 0.5, false);
                ctx.fill();
                break;
            case 'HEX_HALO':
            case 'HEX_FRAME':
                IconPainter.drawHexHalo(ctx, r, color);
                break;
            case 'HEX_LOCK':
            case 'HEX_RUNE':
                IconPainter.drawHexLock(ctx, r, color);
                break;
            case 'MAGIC_CIRCLE':
                this.drawMagicCircle(ctx, r, color);
                break;
            case 'SHADOW_BLOB':
                this.drawShadowBlob(ctx, r, color);
                break;
            case 'BEAM':
                const grad = ctx.createLinearGradient(-r, 0, r, 0);
                grad.addColorStop(0, 'transparent');
                grad.addColorStop(0.5, color);
                grad.addColorStop(1, 'transparent');
                ctx.fillStyle = grad;
                ctx.fillRect(-r*2, -r, r*4, r*2);
                break;
            default:
                ctx.fillStyle = color;
                ctx.beginPath(); ctx.arc(0, 0, 5, 0, Math.PI*2); ctx.fill();
                break;
        }

        this.cache.set(key, canvas);
        return canvas;
    }

    // --- GEOMETRY GENERATORS (MATH COMPLIANT) ---

    private drawRegularHex(ctx: CanvasRenderingContext2D, r: number, color: string, style: 'FILL' | 'STROKE' | 'FILL_GLOW') {
        // applyIso = false to ensure we get a Regular Hexagon. 
        // This texture will be squashed by the painter later.

        if (style === 'FILL_GLOW') {
            const grad = ctx.createRadialGradient(0, 0, r*0.2, 0, 0, r);
            grad.addColorStop(0, color);
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;
            HexGeometry.traceHex(ctx, 0, 0, r * 0.95, false);
            ctx.fill();
        } else {
            HexGeometry.traceHex(ctx, 0, 0, r, false);
            if (style === 'FILL') {
                ctx.fillStyle = color; ctx.fill();
            } else {
                ctx.strokeStyle = color; ctx.stroke();
            }
        }
    }

    private drawGridField(ctx: CanvasRenderingContext2D, r: number, color: string) {
        // Grid pattern inside a hex
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        HexGeometry.traceHex(ctx, 0, 0, r * 0.9, false);
        ctx.stroke();

        // Inner cross
        ctx.beginPath();
        ctx.moveTo(-r*0.5, 0); ctx.lineTo(r*0.5, 0);
        ctx.moveTo(0, -r*0.5); ctx.lineTo(0, r*0.5);
        ctx.stroke();
    }

    private drawShockwave(ctx: CanvasRenderingContext2D, r: number, color: string) {
        ctx.strokeStyle = color;
        ctx.lineWidth = 4;
        ctx.shadowColor = color;
        ctx.shadowBlur = 10;
        HexGeometry.traceHex(ctx, 0, 0, r * 0.8, false);
        ctx.stroke();

        ctx.strokeStyle = 'rgba(255,255,255,0.8)';
        ctx.lineWidth = 1;
        ctx.shadowBlur = 0;
        HexGeometry.traceHex(ctx, 0, 0, r * 0.6, false);
        ctx.stroke();
    }

    private drawMagicCircle(ctx: CanvasRenderingContext2D, r: number, color: string) {
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        HexGeometry.traceHex(ctx, 0, 0, r * 0.9, false);
        ctx.stroke();
        // Inner circle
        ctx.beginPath(); 
        ctx.arc(0, 0, r*0.7, 0, Math.PI*2);
        ctx.stroke();
    }

    private drawShadowBlob(ctx: CanvasRenderingContext2D, r: number, color: string) {
        ctx.fillStyle = color;
        ctx.filter = 'blur(8px)'; 
        ctx.beginPath();
        // Regular Circle or Hex (Painter will squash it to fit isometric)
        ctx.arc(0, 0, r * 0.8, 0, Math.PI*2);
        ctx.fill();
        ctx.filter = 'none';
    }

    private drawCloudTexture(ctx: CanvasRenderingContext2D, r: number, color: string) {
        const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
        grad.addColorStop(0, color);
        grad.addColorStop(0.7, color);
        grad.addColorStop(1, 'transparent');
        ctx.fillStyle = grad;
        const count = 5;
        for(let i=0; i<count; i++) {
            const angle = (i / count) * Math.PI * 2;
            const dist = r * 0.3;
            const size = r * 0.6;
            const x = Math.cos(angle) * dist;
            const y = Math.sin(angle) * dist; // Regular circular distribution
            ctx.beginPath(); ctx.arc(x, y, size, 0, Math.PI*2); ctx.fill();
        }
        ctx.beginPath(); ctx.arc(0, 0, r * 0.5, 0, Math.PI*2); ctx.fill();
    }

    public getTerrainDetail(type: string, color: string, variant: number): HTMLCanvasElement {
        const vIdx = variant % 4;
        const key = `TERRAIN_${type}_${color}_${vIdx}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const size = HEX_SIZE * 2; 
        const { canvas, ctx } = createCanvas(size, size);
        const cx = size / 2;
        const cy = size / 2;

        ctx.translate(cx, cy);
        // Pre-project details for terrain since TerrainRenderer draws them flat
        ctx.scale(1, 0.58); 

        const rnd = (offset: number) => {
            const v = Math.sin(vIdx * 999 + offset) * 1000;
            return v - Math.floor(v);
        };

        ctx.fillStyle = color;
        ctx.globalAlpha = type === 'VOID' ? 0.1 : 0.3;

        for(let i=0; i<5; i++) {
            const px = (rnd(i*2) - 0.5) * HEX_SIZE * 1.2;
            const py = (rnd(i*2+1) - 0.5) * HEX_SIZE * 1.2;
            if (px*px + py*py > (HEX_SIZE*0.7)**2) continue;
            ctx.beginPath();
            ctx.arc(px, py, 1.5 + rnd(i*3), 0, Math.PI*2);
            ctx.fill();
        }

        this.cache.set(key, canvas);
        return canvas;
    }

    public generateProjectileSprite(visual: string, color: string): HTMLCanvasElement {
        const key = `PROJ_${visual}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;
        const { canvas, ctx } = createCanvas(128, 64);
        ctx.translate(64, 32);
        switch (visual) {
            case 'HEX_DART': ProjectilePainter.drawImperialSniper(ctx, color); break;
            case 'CRYSTAL': ProjectilePainter.drawImperialCrystal(ctx, color); break;
            case 'ORB': ProjectilePainter.drawImperialOrb(ctx, color); break;
            case 'BOLT': ProjectilePainter.drawCovenantBolt(ctx, color); break;
            case 'AXE': ProjectilePainter.drawCovenantAxe(ctx, color); break;
            case 'FIREBALL': ProjectilePainter.drawCovenantFireball(ctx, color); break;
            case 'BOMB': ProjectilePainter.drawBomb(ctx, color); break;
            default: ProjectilePainter.drawCovenantBolt(ctx, color); break;
        }
        this.cache.set(key, canvas);
        return canvas;
    }

    public generateGlowOrb(color: string): HTMLCanvasElement { return this.getTexture('ATMOSPHERE', color); }
    public generateCracks(color: string): HTMLCanvasElement { return this.getTexture('CRACKS', color); }

    public generateFogCloud(color: string): HTMLCanvasElement {
        const key = `FOG_CLOUD_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;
        const { canvas, ctx } = createCanvas(128, 64);
        const grad = ctx.createRadialGradient(64, 32, 0, 64, 32, 64);
        grad.addColorStop(0, color); 
        grad.addColorStop(1, 'transparent');
        ctx.fillStyle = grad;
        ctx.beginPath(); ctx.ellipse(64, 32, 40, 25, 0, 0, Math.PI*2); ctx.fill();
        this.cache.set(key, canvas);
        return canvas;
    }

    public generateBlastZone(color: string): HTMLCanvasElement {
        return this.getTexture('SHOCKWAVE', color); 
    }
}

export const VFXFactory = new VFXTextureCache();

import { GameEngine, Agent } from "../../game";
import { GridCache } from "./GridCache";
import { RenderList, RenderOpType } from "../../renderers/RenderList";
import { Hex, Skill, Projectile } from "../../../types";
import { TERRAIN_THEMES, HEX_SIZE } from "../../../constants";
import { HexUtils, getTransitionOffset } from "../../utils";
import { HexMath } from "../../math/HexMath";

// Constants
const PROJ_LIGHT_RADIUS_SQ = 1600;
const OBSTACLE_Z = 10; // Draw order offset

export class GridRenderStrategy {

    // Fast lookup sets
    private _unitPresence = new Set<string>();
    private _unitVisualStatus = new Map<string, string>();

    public submit(
        cache: GridCache,
        renderList: RenderList,
        engine: GameEngine, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null, 
        highlightAgent: Agent | null, 
        projectiles: Projectile[],
        transitionT: number,      
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        globalTime: number
    ) {
        // Culling optimization
        if (transitionPhase === 'OUT' && transitionT > 0.95) return;

        cache.ensure(engine);
        const scene = engine.currentScene;
        const theme = TERRAIN_THEMES[scene.textureType] || TERRAIN_THEMES['VOID'];

        this.prepareUnitLookups(engine);

        // Iterate Cached Tiles
        const len = cache.tileList.length;
        for (let i = 0; i < len; i++) {
            const tile = cache.tileList[i];
            const { q, r, px, py, h, key } = tile;

            // 1. Calculate Transforms
            const transOffset = getTransitionOffset(px, py, engine.mapConfig, transitionT, transitionPhase);
            if (Math.abs(transOffset) > 800) continue; // Cull off-screen

            // --- STRICT COORDINATE SYSTEM ---
            // Base Y = The logical center of the hex on the Z=0 plane (Screen Y)
            // Visual Surface Y = Base Y - Terrain Height

            const visualBaseY = py + transOffset;
            const visualSurfaceY = visualBaseY - h;

            // Sorting: We sort by Base Y (Ground level) to ensure tall objects in front cover those behind.
            const sortY = visualBaseY; 

            // 2. Obstacles (Anchored to Surface)
            const obstacleType = engine.obstacles.get(key);
            if (obstacleType) {
                const op = renderList.next();
                op.type = RenderOpType.OBSTACLE;
                op.y = sortY;
                op.z = OBSTACLE_Z; 
                op.tx = px;
                // Anchor is strictly the surface center. 
                // The SpriteFactory produces images where (width/2, height-padding) is the anchor.
                // DrawImage will handle the offset centering.
                op.ty = visualSurfaceY; 
                op.ttype = obstacleType;
            }

            // 3. Terrain Block
            const op = renderList.next();
            op.type = RenderOpType.TERRAIN;
            op.y = sortY; 
            op.z = 0; 

            op.tx = px; 
            op.ty = visualBaseY; // Prism draws upwards from base
            op.th = h;

            op.tsize = HEX_SIZE;
            op.ttheme = theme;
            op.ttype = scene.textureType;
            op.tdetail = theme.detail;
            op.tq = q; op.tr = r;

            // 4. Overlays & Logic
            op.oStatus = this._unitVisualStatus.get(key);
            op.oDanger = engine.zones.getZoneAt(q, r);
            op.oHazard = engine.hazards.getHazardAt(q, r);
            op.oHasUnit = !engine.isRunning && this._unitPresence.has(key);

            // 5. Interactive Highlights
            this.calculateHighlights(op, q, r, px, py, h, hoveredHex, hoveredSkill, highlightAgent, projectiles, engine);

            op.time = globalTime;
        }
    }

    private prepareUnitLookups(engine: GameEngine) {
        this._unitPresence.clear();
        this._unitVisualStatus.clear();
        for (const a of engine.agents) {
            if (a.hp > 0) {
                const key = HexUtils.key({q: a.q, r: a.r});
                this._unitPresence.add(key);
                if (a.visualStatus !== 'NONE') this._unitVisualStatus.set(key, a.visualStatus);
            }
        }
    }

    private calculateHighlights(
        op: any, 
        q: number, r: number, px: number, py: number, h: number,
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null, 
        highlightAgent: Agent | null, 
        projectiles: Projectile[],
        engine: GameEngine
    ) {
        // Projectile Lighting (Distance Check)
        let lightColor = null;
        let lightIntensity = 0;
        for (const p of projectiles) {
            const distSq = (p.x - px)**2 + (p.y - py)**2;
            if (distSq < PROJ_LIGHT_RADIUS_SQ) {
                lightColor = p.skill.color;
                lightIntensity += (1 - Math.sqrt(distSq) / 40);
            }
        }
        op.oLightCol = lightColor;
        op.oLightInt = Math.min(1, lightIntensity);

        // Skill Range
        let isRange = false;
        let rangeColor = '';
        if (hoveredSkill && highlightAgent) {
            const agentH = engine.map.getTerrainHeight(highlightAgent.q, highlightAgent.r);
            const deltaH = agentH - h;
            // Range logic proxies engine behavior
            const bonus = Math.max(0, Math.floor(deltaH / 24)); 
            const dist = HexMath.distance({q, r}, {q: highlightAgent.q, r: highlightAgent.r});

            if (dist <= hoveredSkill.range + bonus) { 
                isRange = true; 
                rangeColor = hoveredSkill.color; 
            }
        }
        op.oRange = isRange; 
        op.oRangeCol = rangeColor;

        // Mouse Hover
        op.oHover = hoveredHex ? (hoveredHex.q === q && hoveredHex.r === r) : false;
    }
}

import { Particle } from "../../state";
import { ISO_SCALE_Y } from "../../../../../constants";
import { VFXFactory } from "../../../../graphics/VFXFactory";

export const GroundPainter = {
    draw(ctx: CanvasRenderingContext2D, p: Particle, progress: number, drawX: number, drawY: number) {
        if (!p.image && !p.texture) {
            p.image = VFXFactory.getTexture(p.type as any, p.color);
        }
        const img = p.image || p.texture;

        let scale = 1.0;
        let alpha = 1.0 - progress;

        if (p.type === 'SHOCKWAVE' || p.type === 'RING' || p.type === 'BLAST') {
            scale = 0.5 + progress * 2.5; 
            alpha = 1.0 - Math.pow(progress, 3);
        } else if (p.type === 'CRACKS' || p.type === 'GRID_FIELD') {
            scale = 1.0;
            alpha = 1.0 - Math.pow(progress, 4); 
        }

        if (alpha <= 0.01) return;

        ctx.save();
        ctx.translate(drawX, drawY);

        // --- PROJECTION MATRIX ---
        // 1. Scale Y to project regular textures onto isometric floor
        ctx.scale(1, ISO_SCALE_Y);

        // 2. Rotation applied in ground-plane (Visualized as spinning on floor)
        if (p.rotation) ctx.rotate(p.rotation);

        if (p.blendMode) ctx.globalCompositeOperation = p.blendMode;
        else if (p.type === 'CRACKS') ctx.globalCompositeOperation = 'source-over'; 
        else ctx.globalCompositeOperation = 'screen'; 

        ctx.globalAlpha = Math.min(1, alpha);

        if (img) {
            const size = p.size * scale;
            // Draw centered
            ctx.drawImage(img, -size, -size, size * 2, size * 2);
        } else {
            ctx.fillStyle = p.color;
            ctx.beginPath(); ctx.arc(0, 0, p.size * scale, 0, Math.PI*2); ctx.fill();
        }

        ctx.restore();
    }
};

import { OBSTACLE_STYLES } from "../../constants";
import { createCanvas } from "./CanvasUtils";
import { HexGeometry } from "./utils/HexGeometry";

// --- STRICT ALIGNMENT CONSTANTS ---
// These must match the offsets used in RenderPipeline
export const ENV_CANVAS_W = 128;
export const ENV_CANVAS_H = 160;
export const ENV_ANCHOR_X = 64;  // Center X
export const ENV_ANCHOR_Y = 140; // Bottom Y (leaving 20px padding)

export const EnvironmentFactory = {

    generateObstacle(styleKey: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(ENV_CANVAS_W, ENV_CANVAS_H);

        // 1. Setup Anchor: (0,0) is now the CENTER of the hexagonal surface
        ctx.translate(ENV_ANCHOR_X, ENV_ANCHOR_Y);

        const style = OBSTACLE_STYLES[styleKey] || OBSTACLE_STYLES['WALL'];

        // 2. Draw Base Shadow (Strict Hexagon Footprint)
        // This ensures the object visually "sits" on the tile
        ctx.save();
        ctx.fillStyle = 'rgba(0,0,0,0.25)';
        ctx.filter = 'blur(4px)';
        ctx.scale(1, 0.58); // ISO shadow
        ctx.beginPath();
        ctx.arc(0, 0, 28, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();

        // 3. Draw Object based on Type (Growing Upwards y < 0)
        if (styleKey === 'TREE') {
            this.drawTree(ctx, style);
        } else if (styleKey === 'ICE_CRYSTAL') {
            this.drawCrystal(ctx, style);
        } else if (styleKey === 'OBSIDIAN_PILLAR') {
            this.drawPillar(ctx, style);
        } else {
            this.drawWall(ctx, style);
        }

        // Debug: Mark Anchor Point (Comment out in production)
        // ctx.fillStyle = 'red'; ctx.fillRect(-2, -2, 4, 4);

        return canvas;
    },

    generateIceBlock(): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(ENV_CANVAS_W, ENV_CANVAS_H);
        ctx.translate(ENV_ANCHOR_X, ENV_ANCHOR_Y);

        const style = OBSTACLE_STYLES['ICE_CRYSTAL'] || { 
            main: '#7dd3fc', light: '#bae6fd', dark: '#0ea5e9', detail: '#e0f2fe', highlight: '#ffffff' 
        };

        this.drawCrystalShard(ctx, -15, 0, 15, 60, -0.3, style);
        this.drawCrystalShard(ctx, 15, -5, 18, 50, 0.3, style);
        this.drawCrystalShard(ctx, 0, 5, 25, 80, 0, style); // Main Center

        return canvas;
    },

    // --- PAINTER SUB-ROUTINES (Relative to Surface Center (0,0)) ---

    drawTree(ctx: CanvasRenderingContext2D, style: any) {
        // Trunk
        ctx.fillStyle = '#291815'; 
        ctx.beginPath();
        ctx.moveTo(-8, 0); 
        ctx.lineTo(8, 0);
        ctx.lineTo(5, -20);
        ctx.lineTo(-5, -20);
        ctx.fill();

        const layers = 3;
        const topY = -110;
        const bottomY = -20;

        for (let i = 0; i < layers; i++) {
            const ratio = i / layers;
            const layerY = topY + (bottomY - topY) * ratio;
            const spread = 28 + i * 10; 

            const grad = ctx.createLinearGradient(0, topY, 0, bottomY);
            grad.addColorStop(0, style.highlight); 
            grad.addColorStop(0.4, style.main); 
            grad.addColorStop(1, style.dark); 

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(0, layerY - 20); // Tip
            ctx.quadraticCurveTo(-spread * 0.5, layerY + 5, -spread, layerY + 15);
            ctx.quadraticCurveTo(0, layerY + 10, spread, layerY + 15);
            ctx.quadraticCurveTo(spread * 0.5, layerY + 5, 0, layerY - 20);
            ctx.fill();

            // Rim Light
            ctx.strokeStyle = style.light;
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(0, layerY - 20);
            ctx.lineTo(-spread, layerY + 15);
            ctx.stroke();
        }
    },

    drawCrystal(ctx: CanvasRenderingContext2D, style: any) {
        this.drawCrystalShard(ctx, -12, -2, 12, 45, -0.3, style);
        this.drawCrystalShard(ctx, 12, 0, 14, 40, 0.3, style);
        this.drawCrystalShard(ctx, 0, 2, 18, 70, 0, style);
    },

    drawCrystalShard(ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, angle: number, style: any) {
        ctx.save();
        ctx.translate(x, y);
        ctx.rotate(angle);

        // Left Face
        ctx.fillStyle = style.dark;
        ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(-w, 0); ctx.lineTo(0, 6); ctx.fill();

        // Right Face
        const grad = ctx.createLinearGradient(0, -h, 0, 5);
        grad.addColorStop(0, '#ffffff');
        grad.addColorStop(0.3, style.light);
        grad.addColorStop(1, style.main);
        ctx.fillStyle = grad;
        ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(w, 0); ctx.lineTo(0, 6); ctx.fill();

        ctx.strokeStyle = style.highlight;
        ctx.lineWidth = 1;
        ctx.stroke();
        ctx.restore();
    },

    drawPillar(ctx: CanvasRenderingContext2D, style: any) {
        // Hex Prism (3-Face)
        const h = 90;
        const w = 24; 
        const topY = -h;
        const d = 12; // Perspective depth

        // Left Face
        ctx.fillStyle = style.dark;
        ctx.beginPath();
        ctx.moveTo(-w, topY + d); ctx.lineTo(-w/2, topY + d*2);
        ctx.lineTo(-w/2, d*2); ctx.lineTo(-w, d);
        ctx.fill();

        // Center Face
        ctx.fillStyle = style.main;
        ctx.beginPath();
        ctx.moveTo(-w/2, topY + d*2); ctx.lineTo(w/2, topY + d*2);
        ctx.lineTo(w/2, d*2); ctx.lineTo(-w/2, d*2);
        ctx.fill();

        // Right Face
        ctx.fillStyle = style.light;
        ctx.beginPath();
        ctx.moveTo(w/2, topY + d*2); ctx.lineTo(w, topY + d);
        ctx.lineTo(w, d); ctx.lineTo(w/2, d*2);
        ctx.fill();

        // Cap
        ctx.fillStyle = '#000';
        ctx.beginPath();
        ctx.moveTo(-w, topY + d); ctx.lineTo(-w/2, topY + d*2);
        ctx.lineTo(w/2, topY + d*2); ctx.lineTo(w, topY + d);
        ctx.lineTo(w/2, topY); ctx.lineTo(-w/2, topY);
        ctx.fill();

        // Glowing Rune
        ctx.strokeStyle = style.detail;
        ctx.shadowColor = style.highlight;
        ctx.shadowBlur = 10;
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.moveTo(0, -25); ctx.lineTo(0, -65); ctx.stroke();
        ctx.shadowBlur = 0;
    },

    drawWall(ctx: CanvasRenderingContext2D, style: any) {
        const w = 36;
        const h = 55;
        const skew = 10;

        const xL = -w - 5;
        const xLM = -12;
        const xRM = 12;
        const xR = w + 5;

        // Draw from bottom up
        const yBaseFront = skew;
        const yBaseBack = 0;
        const yTopFront = -h + skew;
        const yTopBack = -h;

        // Left Face
        ctx.fillStyle = style.dark;
        ctx.beginPath();
        ctx.moveTo(xL, yTopBack); ctx.lineTo(xLM, yTopFront);
        ctx.lineTo(xLM, yBaseFront); ctx.lineTo(xL, yBaseBack);
        ctx.fill();

        // Center Face
        ctx.fillStyle = style.main;
        ctx.beginPath();
        ctx.moveTo(xLM, yTopFront); ctx.lineTo(xRM, yTopFront);
        ctx.lineTo(xRM, yBaseFront); ctx.lineTo(xLM, yBaseFront);
        ctx.fill();

        // Right Face
        ctx.fillStyle = style.light;
        ctx.beginPath();
        ctx.moveTo(xRM, yTopFront); ctx.lineTo(xR, yTopBack);
        ctx.lineTo(xR, yBaseBack); ctx.lineTo(xRM, yBaseFront);
        ctx.fill();

        // Top Cap
        ctx.fillStyle = style.light;
        ctx.globalAlpha = 0.8;
        ctx.beginPath();
        ctx.moveTo(xL, yTopBack); ctx.lineTo(xLM, yTopFront);
        ctx.lineTo(xRM, yTopFront); ctx.lineTo(xR, yTopBack);
        ctx.lineTo(xRM, yTopBack - skew); ctx.lineTo(xLM, yTopBack - skew);
        ctx.fill();
        ctx.globalAlpha = 1.0;

        // Edges
        ctx.strokeStyle = style.highlight;
        ctx.lineWidth = 1;
        ctx.beginPath(); 
        ctx.moveTo(xL, yTopBack); ctx.lineTo(xLM, yTopFront); ctx.lineTo(xRM, yTopFront); ctx.lineTo(xR, yTopBack);
        ctx.stroke();
    }
};

import { GameEngine, Agent } from "../../game";
import { GridCache } from "./GridCache";
import { RenderList, RenderOpType } from "../../renderers/RenderList";
import { Hex, Skill, Projectile } from "../../../types";
import { TERRAIN_THEMES, HEX_SIZE } from "../../../constants";
import { HexUtils, getTransitionOffset } from "../../utils";
import { HexMath } from "../../math/HexMath";

const OBSTACLE_Z_INDEX = 10;
const PROJ_LIGHT_RADIUS_SQ = 1600;

export class GridRenderStrategy {

    // Transient Sets for faster lookup during render loop
    private _unitPresence = new Set<string>();
    private _unitVisualStatus = new Map<string, string>();

    public submit(
        cache: GridCache,
        renderList: RenderList,
        engine: GameEngine, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null, 
        highlightAgent: Agent | null, 
        projectiles: Projectile[],
        transitionT: number,      
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        globalTime: number
    ) {
        // Cull if map is effectively gone
        if (transitionPhase === 'OUT' && transitionT > 0.95) return;

        cache.ensure(engine);
        const scene = engine.currentScene;
        const theme = TERRAIN_THEMES[scene.textureType] || TERRAIN_THEMES['VOID'];

        // 1. Pre-calc Unit Presence
        this._unitPresence.clear();
        this._unitVisualStatus.clear();
        for (const a of engine.agents) {
            if (a.hp > 0) {
                const key = `${a.q},${a.r}`;
                this._unitPresence.add(key);
                if (a.visualStatus !== 'NONE') this._unitVisualStatus.set(key, a.visualStatus);
            }
        }

        // 2. Iterate Tiles
        const len = cache.tileList.length;
        for (let i = 0; i < len; i++) {
            const tile = cache.tileList[i];
            const { q, r, px, py, h, key } = tile;

            const offset = getTransitionOffset(px, py, engine.mapConfig, transitionT, transitionPhase);

            // Visual Base Y: The bottom of the prism (Ground Level Z=0)
            const visualBaseY = py + offset;

            // Visual Surface Y: The top face of the prism (Base - Height)
            // This is where Units, Obstacles, and Decals should anchor.
            const visualSurfaceY = visualBaseY - h;

            // Cull off-screen transition elements
            if (Math.abs(offset) > 800) continue;

            const sortY = py; // Stable sort key based on logic ground position

            // A. Obstacles
            const obstacleType = engine.obstacles.get(key);
            if (obstacleType) {
                const op = renderList.next();
                op.type = RenderOpType.OBSTACLE;
                op.y = sortY; 
                op.z = OBSTACLE_Z_INDEX;
                op.tx = px; 
                // CRITICAL FIX: Anchor strictly to Surface Y
                // The Sprite has padding handled by EnvironmentFactory
                op.ty = visualSurfaceY; 
                op.ttype = obstacleType;
            }

            // B. Zones (Delegated to ZoneSystem)
            const zoneInfo = engine.zones.getZoneAt(q, r);

            // C. Interactive Highlights
            let isRange = false;
            let rangeColor = '';
            if (hoveredSkill && highlightAgent) {
                const agentH = engine.map.getTerrainHeight(highlightAgent.q, highlightAgent.r);
                const deltaH = agentH - h;
                const bonus = Math.max(0, Math.floor(deltaH / 24)); 
                const dist = HexMath.distance({q, r}, {q: highlightAgent.q, r: highlightAgent.r});

                if (dist <= hoveredSkill.range + bonus) { 
                    isRange = true; 
                    rangeColor = hoveredSkill.color; 
                }
            }

            const isHover = hoveredHex ? (hoveredHex.q === q && hoveredHex.r === r) : false;
            const hasUnit = !engine.isRunning && this._unitPresence.has(key);
            const hazard = engine.hazards.getHazardAt(q, r);

            // D. Projectile Lights
            let lightColor = null;
            let lightIntensity = 0;
            for (const p of projectiles) {
                const distSq = (p.x - px)**2 + (p.y - py)**2;
                if (distSq < PROJ_LIGHT_RADIUS_SQ) {
                    lightColor = p.skill.color;
                    lightIntensity += (1 - Math.sqrt(distSq) / 40);
                }
            }

            // E. Create Terrain Op
            const op = renderList.next();
            op.type = RenderOpType.TERRAIN;
            op.y = sortY; 
            op.z = 0; 

            op.tx = px; 
            op.ty = visualBaseY; 
            op.th = h;

            op.tsize = HEX_SIZE;
            op.ttheme = theme;
            op.ttype = scene.textureType;
            op.tdetail = theme.detail;
            op.tq = q; op.tr = r;

            // Overlays
            op.oStatus = this._unitVisualStatus.get(key);
            op.oDanger = zoneInfo; 
            op.oHazard = hazard;
            op.oLightCol = lightColor; op.oLightInt = Math.min(1, lightIntensity);
            op.oRange = isRange; op.oRangeCol = rangeColor;
            op.oHover = isHover; op.oHasUnit = hasUnit;
            op.time = globalTime;
        }
    }
}

import { Agent, GameEngine, VICTORY_PHASE_DURATION } from "../game";
import { Camera, GameRenderer } from "../renderer"; 
import { Hex, Skill } from "../../types";
import { HexUtils } from "../utils";

// Sub-renderers
import { BackgroundRenderer } from "./background";
import { TacticalRenderer } from "./tactical";
import { HUDRenderer } from "./HUDRenderer";
import { PostProcessor } from "./PostProcessor"; 
import { RenderList, RenderOpType } from "./RenderList";
import { ProjectileDrawer } from "./ProjectileDrawer";

// Painters
import { TerrainRenderer } from "./grid/TerrainRenderer";
import { GridOverlays } from "./grid/GridOverlays";
import { ParticleRenderer } from "../systems/vfx/renderers/ParticleRenderer";
import { SpriteManager } from "../sprites";
import { AssetManager } from "../assets";
import { ENV_ANCHOR_X, ENV_ANCHOR_Y } from "../graphics/EnvironmentFactory";

export class RenderPipeline {
    private renderer: GameRenderer;

    private backgroundRenderer: BackgroundRenderer;
    private tacticalRenderer: TacticalRenderer;
    private hudRenderer: HUDRenderer;
    private postProcessor: PostProcessor;
    private renderList: RenderList;

    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor(renderer: GameRenderer) {
        this.renderer = renderer;
        this.backgroundRenderer = new BackgroundRenderer();
        this.tacticalRenderer = new TacticalRenderer();
        this.hudRenderer = new HUDRenderer();
        this.postProcessor = new PostProcessor();
        this.renderList = new RenderList();
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    public update(dt: number, engine: GameEngine) {
        this.tacticalRenderer.update(dt, engine);
    }

    public draw(
        ctx: CanvasRenderingContext2D, 
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null,
        globalTime: number
    ): void {
        const physicalWidth = ctx.canvas.width;
        const physicalHeight = ctx.canvas.height;

        if (physicalWidth === 0 || physicalHeight === 0) return;

        const dpr = window.devicePixelRatio || 1;
        const logicalWidth = physicalWidth / dpr;
        const logicalHeight = physicalHeight / dpr;

        const scene = engine.currentScene;

        // 1. Reset & Clear
        ctx.resetTransform();
        ctx.clearRect(0, 0, physicalWidth, physicalHeight);

        // 2. Apply Global Scale
        ctx.scale(dpr, dpr);

        // 3. Background
        this.backgroundRenderer.draw(ctx, logicalWidth, logicalHeight, scene, engine.mapConfig, globalTime);

        // 4. Camera Transform
        ctx.save();
        this.renderer.camera.sync(camera); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        // 5. MAIN PASS: Collect and Sort Renderables
        this.renderList.reset();

        const terrainHeightFunc = (q: number, r: number) => this.renderer.grid.getTerrainHeight(q, r, engine);

        // Collect Grid
        this.renderer.grid.submitRenderables(
            this.renderList,
            engine, hoveredHex, hoveredSkill, highlight, 
            engine.projectiles,
            this.transitionT, this.transitionPhase,
            globalTime
        );

        // Collect VFX
        this.renderer.vfxRenderer.submitRenderables(
            this.renderList,
            engine,
            this.renderer.vfx,
            terrainHeightFunc,
            engine.mapConfig,
            this.transitionT,
            this.transitionPhase,
            { width: logicalWidth, height: logicalHeight, camera } 
        );

        // Collect Units
        this.renderer.unit.submitRenderables(
            this.renderList,
            engine.agents, 
            terrainHeightFunc, 
            globalTime, 
            highlight, 
            engine.mapConfig
        );

        // Sort In-Place
        this.renderList.sort();

        // Execute Draws
        for (let i = 0; i < this.renderList.count; i++) {
            const op = this.renderList.ops[i];

            const snapX = Math.round(op.tx);
            const snapY = Math.round(op.ty);

            switch (op.type) {
                case RenderOpType.TERRAIN:
                    // Draw Solid Block
                    TerrainRenderer.drawBlock(
                        ctx, snapX, snapY, op.tsize, op.th, op.ttheme, op.ttype, globalTime
                    );

                    // Draw Details on Top Face (Y - Height)
                    const visualTopY = snapY - op.th;
                    TerrainRenderer.drawTerrainDetail(ctx, snapX, snapY, op.th, op.ttype, op.tdetail, op.tq, op.tr);

                    // Draw Overlays on Top Face
                    GridOverlays.drawOverlays(
                        ctx, snapX, visualTopY, op.tsize,
                        op.oStatus, op.oDanger,
                        op.oLightCol, op.oLightInt,
                        op.oRange, op.oRangeCol, op.oHover, op.oHasUnit,
                        op.tq, op.tr, op.time,
                        op.oHazard
                    );
                    break;

                case RenderOpType.OBSTACLE:
                    const sprite = SpriteManager.getObstacleSprite(op.ttype);
                    // Standardized drawing:
                    // op.tx, op.ty is exactly the Surface Center of the hex.
                    // We offset by the factory's anchor point to align it perfectly.
                    ctx.drawImage(sprite, snapX - ENV_ANCHOR_X, snapY - ENV_ANCHOR_Y);
                    break;

                case RenderOpType.UNIT:
                    if (op.agent) {
                        this.renderer.unit.drawAssembly(ctx, op.agent, snapX, snapY, op.th, op.time, op.uSelected, op.uSilhouette);
                    }
                    break;

                case RenderOpType.DECAL:
                    const dImg = AssetManager.getBlastZone(op.dColor);
                    ctx.save();
                    ctx.translate(snapX, snapY);
                    ctx.scale(op.dScale, op.dScale);
                    ctx.globalAlpha = Math.min(1, op.dLife);
                    ctx.drawImage(dImg, -64, -32, 128, 64);
                    ctx.restore();
                    break;

                case RenderOpType.VFX:
                    if (op.particle) {
                        const p = op.particle;
                        ctx.save();
                        ctx.translate(snapX, snapY);
                        ParticleRenderer.drawSingleParticle(ctx, p, 0, 0, op.vProgress, op.vChaos);
                        ctx.restore();
                    }
                    break;

                case RenderOpType.PROJECTILE:
                    ProjectileDrawer.draw(ctx, op, globalTime);
                    break;
            }
        }

        // 6. Occlusion & Status Layers
        const occludedAgents = this.renderer.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) {
            ctx.save();
            occludedAgents.forEach(agent => {
                this.renderer.unit.drawSilhouette(ctx, agent, terrainHeightFunc, globalTime, engine.mapConfig);
            });
            ctx.restore();
        }

        this.renderer.statusOrchestrator.draw(ctx, engine.agents, globalTime);
        this.renderer.vfxRenderer.drawTopLayerParticles(ctx, this.renderer.vfx, scene, engine.mapConfig, this.transitionT, this.transitionPhase);

        ctx.restore(); 

        // 9. Post Processing
        let transitionAberration = 0;
        if (this.transitionPhase !== 'IDLE') {
            transitionAberration = 4 * this.transitionT * (1 - this.transitionT) * 0.5;
        }

        this.postProcessor.apply(ctx, physicalWidth, physicalHeight, this.renderer.camera.getTrauma(), transitionAberration);

        // 10. HUD Layer
        ctx.save(); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.renderer.grid, globalTime);
        this.hudRenderer.draw(ctx, this.renderer.hud, engine.agents, terrainHeightFunc, engine.mapConfig, highlight, globalTime);

        ctx.restore(); 

        if (engine.directorTargetId) {
            this.tacticalRenderer.drawHUD(ctx, engine, logicalWidth, logicalHeight, camera, globalTime);
        } 

        this.tacticalRenderer.drawDebug(ctx, fps);

        let blurAmount = 0;
        if (engine.isFinishing) {
            blurAmount = 1.0 - (engine.victoryTimer / VICTORY_PHASE_DURATION);
        } else if (engine.winningTeam !== null) {
            blurAmount = 1.0;
        }

        if (this.transitionPhase === 'OUT') blurAmount = 1.0; 
        else if (this.transitionPhase === 'IN') blurAmount = 1.0 - this.transitionT;

        if (blurAmount > 0) {
            this.postProcessor.applyFinishBlur(ctx, physicalWidth, physicalHeight, Math.max(0, Math.min(1, blurAmount)));
        }
    }
}

import { Agent } from "../../game";
import { MovementType } from "../../../types";
import { HexUtils, MapConfig } from "../../utils";
import { UNIT_BODY_OFFSET } from "../../../constants";
import { HexMath } from "../../math/HexMath";

export interface UnitVisualState {
    agent: Agent;

    // Position (Screen Space / Render Space)
    x: number;
    y: number; // Ground Y (Base of the tile unit is standing on)
    z: number; // Height (Terrain + Physics)

    // Derived
    terrainHeight: number;
    scale: number;
    isSilhouette: boolean;
    isSelected: boolean;
    sortY: number; // New: Explicit sort key

    // Flags
    isDead: boolean;
    isVisible: boolean;
}

export class UnitVisualProcessor {

    public static process(
        agent: Agent, 
        getTerrainHeight: (q: number, r: number) => number,
        mapConfig: MapConfig,
        highlightAgent: Agent | null
    ): UnitVisualState {

        const isDead = agent.hp <= 0;

        // 1. Interpolate Ground Position (Lerp if moving)
        let logicalX = 0;
        let logicalY = 0;
        let terrainH = 0;
        let sortY = 0;

        if (agent.isMoving && agent.path.length > 0) {
            const startPx = HexMath.hexToPixel(agent.q, agent.r, mapConfig.offsetX, mapConfig.offsetY);
            const nextHex = agent.path[0];
            const endPx = HexMath.hexToPixel(nextHex.q, nextHex.r, mapConfig.offsetX, mapConfig.offsetY);

            // Re-calculate lerp to ensure it matches motion engine visual exactly
            logicalX = startPx.x + (endPx.x - startPx.x) * agent.moveProgress;
            logicalY = startPx.y + (endPx.y - startPx.y) * agent.moveProgress;

            const startH = getTerrainHeight(agent.q, agent.r);
            const endH = getTerrainHeight(nextHex.q, nextHex.r);

            // STEP LOGIC: Snap height at midpoint to assume "stepping up/down" the block
            // This prevents the unit from clipping through the wall of a higher block or floating diagonally.
            terrainH = agent.moveProgress < 0.5 ? startH : endH;

            // SORT LOGIC: When moving, always sort in front of BOTH the start and end tiles.
            // In isometric, larger Y = Front.
            // We set the sort key to the 'most front' tile involved in the move.
            sortY = Math.max(startPx.y, endPx.y);

        } else {
            const pos = HexMath.hexToPixel(agent.q, agent.r, mapConfig.offsetX, mapConfig.offsetY);
            logicalX = pos.x;
            logicalY = pos.y;
            terrainH = getTerrainHeight(agent.q, agent.r);
            sortY = logicalY;
        }

        // Apply visual physics offsets
        const visualX = logicalX + agent.physics.x;
        // visualY corresponds to the Ground Base Y
        const visualY = logicalY + agent.physics.y; 
        const visualZ = terrainH + agent.physics.z; 

        // Apply physics to sort key too (e.g. knocked forward)
        sortY += agent.physics.y;

        const isSelected = (agent === highlightAgent);

        return {
            agent,
            x: visualX,
            y: visualY,
            z: visualZ,
            terrainHeight: terrainH,
            scale: 1.0, 
            isSilhouette: false,
            isSelected,
            sortY,
            isDead,
            isVisible: !agent.fullyDead
        };
    }
}

import { Agent, GameEngine } from "../game";
import { RenderList, RenderOpType } from "../renderers/RenderList";
import { MapConfig } from "../utils";
import { UnitVisualProcessor } from "./unit/UnitVisualProcessor";
import { UnitBodyPainter } from "../renderers/units/painters/UnitBodyPainter";
import { UnitShadowPainter } from "../renderers/units/painters/UnitShadowPainter";

export class UnitRenderSystem {

    public submitRenderables(
        renderList: RenderList,
        agents: Agent[], 
        getTerrainHeight: (q: number, r: number) => number, 
        globalTime: number, 
        highlightAgent: Agent | null,
        mapConfig: MapConfig
    ) {
        agents.forEach(agent => {
            if (agent.hp <= 0 && agent.fullyDead) return;

            // 1. Process Logic -> State
            const state = UnitVisualProcessor.process(agent, getTerrainHeight, mapConfig, highlightAgent);

            const op = renderList.next();
            op.type = RenderOpType.UNIT;

            // Sort by calculated SortY (Safe Max Y approach)
            // Add +1 to ensure it draws slightly in front of the terrain block if positions are identical
            op.y = state.sortY + 1; 
            op.z = 10;

            op.agent = agent;

            // ALIGNMENT FIX:
            // state.x / state.y = Physical Ground Coordinates (Base of block)
            // state.terrainHeight = Height of block
            // visualGroundTop = state.y - state.terrainHeight

            op.tx = state.x; 
            op.ty = state.y - state.terrainHeight; // Anchor Visuals to TOP of block

            // Pass LOCAL Physics Z to painter, NOT Total Z.
            // Painter will translate(0, -pz).
            op.th = agent.physics.z; 

            op.time = globalTime;
            op.uSelected = state.isSelected;
            op.uSilhouette = false;
        });
    }

    public drawSilhouette(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        getTerrainHeight: (q: number, r: number) => number, 
        globalTime: number, 
        mapConfig: MapConfig
    ) {
        // Recalculate state just for the silhouette pass
        const state = UnitVisualProcessor.process(agent, getTerrainHeight, mapConfig, null);

        // Use consistent alignment
        const visualGroundY = state.y - state.terrainHeight;

        this.drawAssembly(ctx, agent, state.x, visualGroundY, agent.physics.z, globalTime, false, true);
    }

    public drawAssembly(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        drawX: number, 
        drawY: number, 
        localZ: number,
        globalTime: number, 
        isSelected: boolean,
        isSilhouette: boolean
    ) {
        const scaleFactor = 1.0; 

        // Global Transform for this Unit
        ctx.save();

        // Move to Visual Ground Top (drawX, drawY)
        ctx.translate(drawX, drawY); 

        // 1. Draw Shadow & Base (At Ground Level)
        // Passes localZ so shadow can scale based on jump height
        if (!isSilhouette && agent.hp > 0) {
            UnitShadowPainter.draw(ctx, agent, 0, 0, localZ, globalTime, isSilhouette);
        }

        // 2. Draw Body (Elevated Layer)
        // UnitBodyPainter handles the `translate(0, -localZ)` internally
        UnitBodyPainter.draw(ctx, agent, 0, 0, localZ, globalTime, isSilhouette, isSelected, scaleFactor);

        ctx.restore(); 
    }
}

