import { OBSTACLE_STYLES, HEX_SIZE, ISO_SCALE_Y } from "../../constants";
import { createCanvas } from "./CanvasUtils";

// --- STRICT ALIGNMENT CONSTANTS ---
// Canvas must be large enough to hold tall objects (Pillars, Trees)
// Anchor X is center (64)
// Anchor Y is bottom (140), allowing 20px padding at bottom for shadow
export const ENV_CANVAS_W = 128;
export const ENV_CANVAS_H = 160;
export const ENV_ANCHOR_X = 64;  
export const ENV_ANCHOR_Y = 140; 

// Helper: Hexagon Vertices for Flat-Top alignment
// 0: Right, 1: Bottom-Right, 2: Bottom-Left, 3: Left, 4: Top-Left, 5: Top-Right
function getHexVertex(index: number, radius: number): {x: number, y: number} {
    const angle = index * Math.PI / 3;
    return {
        x: Math.cos(angle) * radius,
        y: Math.sin(angle) * radius * ISO_SCALE_Y
    };
}

export const EnvironmentFactory = {

    generateObstacle(styleKey: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(ENV_CANVAS_W, ENV_CANVAS_H);

        // Setup Anchor: (0,0) is now the CENTER of the hexagonal SURFACE on the ground
        ctx.translate(ENV_ANCHOR_X, ENV_ANCHOR_Y);

        const style = OBSTACLE_STYLES[styleKey] || OBSTACLE_STYLES['WALL'];

        // 1. Draw Base Shadow (Strict Hexagon Footprint)
        this.drawHexShadow(ctx);

        // 2. Draw Object based on Type (Growing Upwards y < 0)
        if (styleKey === 'TREE') {
            this.drawIsoTree(ctx, style);
        } else if (styleKey === 'ICE_CRYSTAL') {
            this.drawIsoCrystal(ctx, style);
        } else if (styleKey === 'OBSIDIAN_PILLAR') {
            this.drawIsoPillar(ctx, style);
        } else {
            this.drawIsoWall(ctx, style); // Default Wall/Sandstone
        }

        return canvas;
    },

    generateIceBlock(): HTMLCanvasElement {
        // Special case for Frozen Status Model
        const { canvas, ctx } = createCanvas(ENV_CANVAS_W, ENV_CANVAS_H);
        ctx.translate(ENV_ANCHOR_X, ENV_ANCHOR_Y);
        const style = OBSTACLE_STYLES['ICE_CRYSTAL'];

        // Draw a translucent block enclosing the unit
        this.drawIsoCrystal(ctx, style, 0.7);
        return canvas;
    },

    // --- GEOMETRY PRIMITIVES ---

    drawHexShadow(ctx: CanvasRenderingContext2D) {
        ctx.save();
        ctx.fillStyle = 'rgba(0,0,0,0.3)';
        ctx.filter = 'blur(4px)';
        ctx.beginPath();
        const r = HEX_SIZE * 0.9;
        for (let i = 0; i < 6; i++) {
            const v = getHexVertex(i, r);
            if(i===0) ctx.moveTo(v.x, v.y);
            else ctx.lineTo(v.x, v.y);
        }
        ctx.closePath();
        ctx.fill();
        ctx.restore();
    },

    /**
     * Draws a generic ISO Prism (Wall/Pillar base)
     * For Flat-Top Hex viewed from South:
     * Visible Faces: Top, Front-Left (3->2), Front-Center (2->1), Front-Right (1->0)??
     * Actually for Flat Top:
     * Verts: 0(R), 1(BR), 2(BL), 3(L), 4(TL), 5(TR)
     * Visible Side Walls: 
     *  - Face A: 3 -> 2 (Left-Front)
     *  - Face B: 2 -> 1 (Right-Front)
     *  - Face C: 1 -> 0 (Right - usually back-ish or side)
     * Let's stick to a 3-face logic: Top, Left-Side, Right-Side.
     */
    drawIsoWall(ctx: CanvasRenderingContext2D, style: any) {
        const height = 55;
        const r = HEX_SIZE * 0.9; // Slightly smaller than tile

        // Vertices
        const v3 = getHexVertex(3, r); // Left
        const v2 = getHexVertex(2, r); // Bottom Left
        const v1 = getHexVertex(1, r); // Bottom Right
        const v0 = getHexVertex(0, r); // Right

        // Draw Sides (Extrude Up)
        const topY = -height;

        // Left Face (v3 -> v2)
        ctx.fillStyle = style.dark;
        ctx.beginPath();
        ctx.moveTo(v3.x, v3.y);
        ctx.lineTo(v2.x, v2.y);
        ctx.lineTo(v2.x, v2.y + topY);
        ctx.lineTo(v3.x, v3.y + topY);
        ctx.closePath();
        ctx.fill();
        ctx.strokeStyle = style.highlight; ctx.lineWidth = 1; ctx.stroke();

        // Front Face (v2 -> v1)
        ctx.fillStyle = style.main;
        ctx.beginPath();
        ctx.moveTo(v2.x, v2.y);
        ctx.lineTo(v1.x, v1.y);
        ctx.lineTo(v1.x, v1.y + topY);
        ctx.lineTo(v2.x, v2.y + topY);
        ctx.closePath();
        ctx.fill();
        ctx.stroke();

        // Right Face (v1 -> v0)
        ctx.fillStyle = style.light;
        ctx.beginPath();
        ctx.moveTo(v1.x, v1.y);
        ctx.lineTo(v0.x, v0.y);
        ctx.lineTo(v0.x, v0.y + topY);
        ctx.lineTo(v1.x, v1.y + topY);
        ctx.closePath();
        ctx.fill();
        ctx.stroke();

        // Top Face (Full Hex)
        ctx.save();
        ctx.translate(0, topY);
        ctx.fillStyle = style.light;
        ctx.globalAlpha = 0.9;
        ctx.beginPath();
        for (let i = 0; i < 6; i++) {
            const v = getHexVertex(i, r);
            if(i===0) ctx.moveTo(v.x, v.y); else ctx.lineTo(v.x, v.y);
        }
        ctx.closePath();
        ctx.fill();

        // Inner Detail
        ctx.fillStyle = style.detail;
        ctx.beginPath(); ctx.arc(0, 0, r*0.4, 0, Math.PI*2); ctx.fill();

        ctx.restore();
    },

    drawIsoPillar(ctx: CanvasRenderingContext2D, style: any) {
        const height = 90;
        const r = HEX_SIZE * 0.7; // Thinner than wall

        // Similar to wall but taller and thinner
        const v3 = getHexVertex(3, r); 
        const v2 = getHexVertex(2, r); 
        const v1 = getHexVertex(1, r); 
        const v0 = getHexVertex(0, r); 
        const topY = -height;

        // Left Face
        ctx.fillStyle = style.dark;
        ctx.beginPath();
        ctx.moveTo(v3.x, v3.y); ctx.lineTo(v2.x, v2.y); 
        ctx.lineTo(v2.x, v2.y + topY); ctx.lineTo(v3.x, v3.y + topY);
        ctx.fill();

        // Front Face
        ctx.fillStyle = style.main;
        ctx.beginPath();
        ctx.moveTo(v2.x, v2.y); ctx.lineTo(v1.x, v1.y);
        ctx.lineTo(v1.x, v1.y + topY); ctx.lineTo(v2.x, v2.y + topY);
        ctx.fill();

        // Rune on Front
        ctx.strokeStyle = style.detail;
        ctx.lineWidth = 2;
        ctx.shadowColor = style.detail;
        ctx.shadowBlur = 5;
        ctx.beginPath();
        ctx.moveTo(0, -30); ctx.lineTo(0, -60);
        ctx.moveTo(-5, -45); ctx.lineTo(5, -45);
        ctx.stroke();
        ctx.shadowBlur = 0;

        // Right Face
        ctx.fillStyle = style.light;
        ctx.beginPath();
        ctx.moveTo(v1.x, v1.y); ctx.lineTo(v0.x, v0.y);
        ctx.lineTo(v0.x, v0.y + topY); ctx.lineTo(v1.x, v1.y + topY);
        ctx.fill();

        // Top
        ctx.save();
        ctx.translate(0, topY);
        ctx.fillStyle = '#000';
        ctx.beginPath();
        for (let i = 0; i < 6; i++) {
            const v = getHexVertex(i, r);
            if(i===0) ctx.moveTo(v.x, v.y); else ctx.lineTo(v.x, v.y);
        }
        ctx.fill();
        ctx.restore();
    },

    drawIsoTree(ctx: CanvasRenderingContext2D, style: any) {
        // 1. Trunk (Cylinder-ish base)
        const trunkW = 10;
        const trunkH = 20;

        ctx.fillStyle = '#291815'; // Dark Wood
        ctx.beginPath();
        ctx.ellipse(0, 0, trunkW, trunkW * ISO_SCALE_Y, 0, 0, Math.PI, true); // Bottom arc
        ctx.lineTo(trunkW, -trunkH);
        ctx.ellipse(0, -trunkH, trunkW, trunkW * ISO_SCALE_Y, 0, 0, Math.PI * 2); // Top circle
        ctx.lineTo(-trunkW, 0);
        ctx.fill();

        // 2. Foliage Layers (Cone-like but with volume)
        const layers = 3;
        const startY = -trunkH + 5;
        const endY = -110;
        const maxSpread = 32;
        const minSpread = 10;

        for (let i = 0; i < layers; i++) {
            const t = i / (layers - 1); // 0 to 1
            const y = startY + (endY - startY) * t;
            const nextY = startY + (endY - startY) * ((i + 1) / (layers - 1));

            const spread = maxSpread * (1 - t) + minSpread * t;

            // Draw a "blob" that represents a volume of leaves
            // We fake 3D by drawing a dark bottom and light top

            const grad = ctx.createLinearGradient(0, y, 0, y + 20);
            grad.addColorStop(0, style.highlight);
            grad.addColorStop(0.5, style.main);
            grad.addColorStop(1, style.dark);

            ctx.fillStyle = grad;
            ctx.beginPath();
            // Diamond/Spade shape
            ctx.moveTo(0, y - 10); // Top tip
            ctx.quadraticCurveTo(spread, y + 10, 0, y + 15); // Right curve down
            ctx.quadraticCurveTo(-spread, y + 10, 0, y - 10); // Left curve up
            ctx.fill();

            // Rim Light
            ctx.strokeStyle = style.light;
            ctx.lineWidth = 1;
            ctx.stroke();
        }
    },

    drawIsoCrystal(ctx: CanvasRenderingContext2D, style: any, alpha: number = 1.0) {
        // Cluster of sharp crystals
        const drawShard = (x: number, y: number, w: number, h: number, tilt: number) => {
            ctx.save();
            ctx.translate(x, y);
            ctx.rotate(tilt);

            // Diamond profile
            ctx.fillStyle = style.dark;
            ctx.globalAlpha = alpha;
            ctx.beginPath();
            ctx.moveTo(0, 0);
            ctx.lineTo(-w, -h * 0.2);
            ctx.lineTo(0, -h); // Tip
            ctx.lineTo(w, -h * 0.3);
            ctx.closePath();
            ctx.fill();

            // Facet Highlight
            ctx.fillStyle = style.light;
            ctx.globalAlpha = alpha * 0.6;
            ctx.beginPath();
            ctx.moveTo(0, 0);
            ctx.lineTo(w, -h * 0.3);
            ctx.lineTo(0, -h);
            ctx.fill();

            // Edge
            ctx.strokeStyle = style.highlight;
            ctx.lineWidth = 1;
            ctx.globalAlpha = alpha;
            ctx.beginPath();
            ctx.moveTo(0, 0); ctx.lineTo(0, -h);
            ctx.stroke();

            ctx.restore();
        };

        drawShard(-10, 5, 10, 50, -0.2);
        drawShard(10, 2, 12, 40, 0.2);
        drawShard(0, 8, 18, 70, 0); // Main
    }
};

import { Agent, GameEngine, VICTORY_PHASE_DURATION } from "../game";
import { Camera, GameRenderer } from "../renderer"; 
import { Hex, Skill } from "../../types";
import { HexUtils } from "../utils";

// Sub-renderers
import { BackgroundRenderer } from "./background";
import { TacticalRenderer } from "./tactical";
import { HUDRenderer } from "./HUDRenderer";
import { PostProcessor } from "./PostProcessor"; 
import { RenderList, RenderOpType } from "./RenderList";
import { ProjectileDrawer } from "./ProjectileDrawer";

// Painters
import { TerrainRenderer } from "./grid/TerrainRenderer";
import { GridOverlays } from "./grid/GridOverlays";
import { ParticleRenderer } from "../systems/vfx/renderers/ParticleRenderer";
import { SpriteManager } from "../sprites";
import { AssetManager } from "../assets";
import { ENV_ANCHOR_X, ENV_ANCHOR_Y } from "../graphics/EnvironmentFactory";

export class RenderPipeline {
    private renderer: GameRenderer;

    private backgroundRenderer: BackgroundRenderer;
    private tacticalRenderer: TacticalRenderer;
    private hudRenderer: HUDRenderer;
    private postProcessor: PostProcessor;
    private renderList: RenderList;

    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor(renderer: GameRenderer) {
        this.renderer = renderer;
        this.backgroundRenderer = new BackgroundRenderer();
        this.tacticalRenderer = new TacticalRenderer();
        this.hudRenderer = new HUDRenderer();
        this.postProcessor = new PostProcessor();
        this.renderList = new RenderList();
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    public update(dt: number, engine: GameEngine) {
        this.tacticalRenderer.update(dt, engine);
    }

    public draw(
        ctx: CanvasRenderingContext2D, 
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null,
        globalTime: number
    ): void {
        const physicalWidth = ctx.canvas.width;
        const physicalHeight = ctx.canvas.height;

        if (physicalWidth === 0 || physicalHeight === 0) return;

        const dpr = window.devicePixelRatio || 1;
        const logicalWidth = physicalWidth / dpr;
        const logicalHeight = physicalHeight / dpr;

        const scene = engine.currentScene;

        // 1. Reset & Clear
        ctx.resetTransform();
        ctx.clearRect(0, 0, physicalWidth, physicalHeight);

        // 2. Apply Global Scale
        ctx.scale(dpr, dpr);

        // 3. Background
        this.backgroundRenderer.draw(ctx, logicalWidth, logicalHeight, scene, engine.mapConfig, globalTime);

        // 4. Camera Transform
        ctx.save();
        this.renderer.camera.sync(camera); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        // 5. MAIN PASS: Collect and Sort Renderables
        this.renderList.reset();

        const terrainHeightFunc = (q: number, r: number) => this.renderer.grid.getTerrainHeight(q, r, engine);

        // Collect Grid
        this.renderer.grid.submitRenderables(
            this.renderList,
            engine, hoveredHex, hoveredSkill, highlight, 
            engine.projectiles,
            this.transitionT, this.transitionPhase,
            globalTime
        );

        // Collect VFX
        this.renderer.vfxRenderer.submitRenderables(
            this.renderList,
            engine,
            this.renderer.vfx,
            terrainHeightFunc,
            engine.mapConfig,
            this.transitionT,
            this.transitionPhase,
            { width: logicalWidth, height: logicalHeight, camera } 
        );

        // Collect Units
        this.renderer.unit.submitRenderables(
            this.renderList,
            engine.agents, 
            terrainHeightFunc, 
            globalTime, 
            highlight, 
            engine.mapConfig
        );

        // Sort In-Place
        this.renderList.sort();

        // Execute Draws
        for (let i = 0; i < this.renderList.count; i++) {
            const op = this.renderList.ops[i];

            const snapX = Math.round(op.tx);
            const snapY = Math.round(op.ty);

            switch (op.type) {
                case RenderOpType.TERRAIN:
                    // Draw Solid Block
                    TerrainRenderer.drawBlock(
                        ctx, snapX, snapY, op.tsize, op.th, op.ttheme, op.ttype, globalTime
                    );

                    // Draw Details on Top Face (Y - Height)
                    const visualTopY = snapY - op.th;
                    TerrainRenderer.drawTerrainDetail(ctx, snapX, snapY, op.th, op.ttype, op.tdetail, op.tq, op.tr);

                    // Draw Overlays on Top Face
                    GridOverlays.drawOverlays(
                        ctx, snapX, visualTopY, op.tsize,
                        op.oStatus, op.oDanger,
                        op.oLightCol, op.oLightInt,
                        op.oRange, op.oRangeCol, op.oHover, op.oHasUnit,
                        op.tq, op.tr, op.time,
                        op.oHazard
                    );
                    break;

                case RenderOpType.OBSTACLE:
                    const sprite = SpriteManager.getObstacleSprite(op.ttype);
                    // Standardized drawing:
                    // op.tx, op.ty is the Visual Surface Center of the hex.
                    // We offset by the factory's anchor point to align it perfectly.
                    ctx.drawImage(sprite, snapX - ENV_ANCHOR_X, snapY - ENV_ANCHOR_Y);
                    break;

                case RenderOpType.UNIT:
                    if (op.agent) {
                        this.renderer.unit.drawAssembly(ctx, op.agent, snapX, snapY, op.th, op.time, op.uSelected, op.uSilhouette);
                    }
                    break;

                case RenderOpType.DECAL:
                    const dImg = AssetManager.getBlastZone(op.dColor);
                    ctx.save();
                    ctx.translate(snapX, snapY);
                    ctx.scale(op.dScale, op.dScale);
                    ctx.globalAlpha = Math.min(1, op.dLife);
                    ctx.drawImage(dImg, -64, -32, 128, 64);
                    ctx.restore();
                    break;

                case RenderOpType.VFX:
                    if (op.particle) {
                        const p = op.particle;
                        ctx.save();
                        ctx.translate(snapX, snapY);
                        ParticleRenderer.drawSingleParticle(ctx, p, 0, 0, op.vProgress, op.vChaos);
                        ctx.restore();
                    }
                    break;

                case RenderOpType.PROJECTILE:
                    ProjectileDrawer.draw(ctx, op, globalTime);
                    break;
            }
        }

        // 6. Occlusion & Status Layers
        const occludedAgents = this.renderer.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) {
            ctx.save();
            occludedAgents.forEach(agent => {
                this.renderer.unit.drawSilhouette(ctx, agent, terrainHeightFunc, globalTime, engine.mapConfig);
            });
            ctx.restore();
        }

        this.renderer.statusOrchestrator.draw(ctx, engine.agents, globalTime);
        this.renderer.vfxRenderer.drawTopLayerParticles(ctx, this.renderer.vfx, scene, engine.mapConfig, this.transitionT, this.transitionPhase);

        ctx.restore(); 

        // 9. Post Processing
        let transitionAberration = 0;
        if (this.transitionPhase !== 'IDLE') {
            transitionAberration = 4 * this.transitionT * (1 - this.transitionT) * 0.5;
        }

        this.postProcessor.apply(ctx, physicalWidth, physicalHeight, this.renderer.camera.getTrauma(), transitionAberration);

        // 10. HUD Layer
        ctx.save(); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.renderer.grid, globalTime);
        this.hudRenderer.draw(ctx, this.renderer.hud, engine.agents, terrainHeightFunc, engine.mapConfig, highlight, globalTime);

        ctx.restore(); 

        if (engine.directorTargetId) {
            this.tacticalRenderer.drawHUD(ctx, engine, logicalWidth, logicalHeight, camera, globalTime);
        } 

        this.tacticalRenderer.drawDebug(ctx, fps);

        let blurAmount = 0;
        if (engine.isFinishing) {
            blurAmount = 1.0 - (engine.victoryTimer / VICTORY_PHASE_DURATION);
        } else if (engine.winningTeam !== null) {
            blurAmount = 1.0;
        }

        if (this.transitionPhase === 'OUT') blurAmount = 1.0; 
        else if (this.transitionPhase === 'IN') blurAmount = 1.0 - this.transitionT;

        if (blurAmount > 0) {
            this.postProcessor.applyFinishBlur(ctx, physicalWidth, physicalHeight, Math.max(0, Math.min(1, blurAmount)));
        }
    }
}

import { GameEngine, Agent } from "../../game";
import { GridCache } from "./GridCache";
import { RenderList, RenderOpType } from "../../renderers/RenderList";
import { Hex, Skill, Projectile } from "../../../types";
import { TERRAIN_THEMES, HEX_SIZE } from "../../../constants";
import { HexUtils, getTransitionOffset } from "../../utils";
import { HexMath } from "../../math/HexMath";

const OBSTACLE_Z_INDEX = 10;
const PROJ_LIGHT_RADIUS_SQ = 1600;

export class GridRenderStrategy {

    // Transient Sets for faster lookup during render loop
    private _unitPresence = new Set<string>();
    private _unitVisualStatus = new Map<string, string>();

    public submit(
        cache: GridCache,
        renderList: RenderList,
        engine: GameEngine, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null, 
        highlightAgent: Agent | null, 
        projectiles: Projectile[],
        transitionT: number,      
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        globalTime: number
    ) {
        // Cull if map is effectively gone
        if (transitionPhase === 'OUT' && transitionT > 0.95) return;

        cache.ensure(engine);
        const scene = engine.currentScene;
        const theme = TERRAIN_THEMES[scene.textureType] || TERRAIN_THEMES['VOID'];

        // 1. Pre-calc Unit Presence
        this._unitPresence.clear();
        this._unitVisualStatus.clear();
        for (const a of engine.agents) {
            if (a.hp > 0) {
                const key = `${a.q},${a.r}`;
                this._unitPresence.add(key);
                if (a.visualStatus !== 'NONE') this._unitVisualStatus.set(key, a.visualStatus);
            }
        }

        // 2. Iterate Tiles
        const len = cache.tileList.length;
        for (let i = 0; i < len; i++) {
            const tile = cache.tileList[i];
            const { q, r, px, py, h, key } = tile;

            const offset = getTransitionOffset(px, py, engine.mapConfig, transitionT, transitionPhase);

            // Visual Base Y: The bottom of the prism (Ground Level Z=0)
            const visualBaseY = py + offset;

            // Visual Surface Y: The top face of the prism (Base - Height)
            // This is where Units, Obstacles, and Decals should anchor.
            const visualSurfaceY = visualBaseY - h;

            // Cull off-screen transition elements
            if (Math.abs(offset) > 800) continue;

            const sortY = py; // Stable sort key based on logic ground position

            // A. Obstacles
            const obstacleType = engine.obstacles.get(key);
            if (obstacleType) {
                const op = renderList.next();
                op.type = RenderOpType.OBSTACLE;
                op.y = sortY; 
                op.z = OBSTACLE_Z_INDEX;
                op.tx = px; 
                // Obstacles anchor to the visual SURFACE center.
                // The EnvironmentFactory sprite anchor will handle the offset from there.
                op.ty = visualSurfaceY; 
                op.ttype = obstacleType;
            }

            // B. Zones (Delegated to ZoneSystem)
            const zoneInfo = engine.zones.getZoneAt(q, r);

            // C. Interactive Highlights
            let isRange = false;
            let rangeColor = '';
            if (hoveredSkill && highlightAgent) {
                const agentH = engine.map.getTerrainHeight(highlightAgent.q, highlightAgent.r);
                const deltaH = agentH - h;
                const bonus = Math.max(0, Math.floor(deltaH / 24)); 
                const dist = HexMath.distance({q, r}, {q: highlightAgent.q, r: highlightAgent.r});

                if (dist <= hoveredSkill.range + bonus) { 
                    isRange = true; 
                    rangeColor = hoveredSkill.color; 
                }
            }

            const isHover = hoveredHex ? (hoveredHex.q === q && hoveredHex.r === r) : false;
            const hasUnit = !engine.isRunning && this._unitPresence.has(key);
            const hazard = engine.hazards.getHazardAt(q, r);

            // D. Projectile Lights
            let lightColor = null;
            let lightIntensity = 0;
            for (const p of projectiles) {
                const distSq = (p.x - px)**2 + (p.y - py)**2;
                if (distSq < PROJ_LIGHT_RADIUS_SQ) {
                    lightColor = p.skill.color;
                    lightIntensity += (1 - Math.sqrt(distSq) / 40);
                }
            }

            // E. Create Terrain Op
            const op = renderList.next();
            op.type = RenderOpType.TERRAIN;
            op.y = sortY; 
            op.z = 0; 

            op.tx = px; 
            op.ty = visualBaseY; 
            op.th = h;

            op.tsize = HEX_SIZE;
            op.ttheme = theme;
            op.ttype = scene.textureType;
            op.tdetail = theme.detail;
            op.tq = q; op.tr = r;

            // Overlays
            op.oStatus = this._unitVisualStatus.get(key);
            op.oDanger = zoneInfo; 
            op.oHazard = hazard;
            op.oLightCol = lightColor; op.oLightInt = Math.min(1, lightIntensity);
            op.oRange = isRange; op.oRangeCol = rangeColor;
            op.oHover = isHover; op.oHasUnit = hasUnit;
            op.time = globalTime;
        }
    }
}

