import { OBSTACLE_STYLES, HEX_SIZE, ISO_SCALE_Y } from "../../constants";
import { createCanvas } from "./CanvasUtils";

// --- STRICT ALIGNMENT CONSTANTS ---
export const ENV_CANVAS_W = 128;
export const ENV_CANVAS_H = 160;
export const ENV_ANCHOR_X = 64;  
export const ENV_ANCHOR_Y = 140; 

// Helper: Hexagon Vertices for Flat-Top alignment
function getHexVertex(index: number, radius: number): {x: number, y: number} {
    const angle = index * Math.PI / 3;
    return {
        x: Math.cos(angle) * radius,
        y: Math.sin(angle) * radius * ISO_SCALE_Y
    };
}

export const EnvironmentFactory = {

    generateObstacle(styleKey: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(ENV_CANVAS_W, ENV_CANVAS_H);

        // Setup Anchor: (0,0) is now the CENTER of the hexagonal SURFACE on the ground
        ctx.translate(ENV_ANCHOR_X, ENV_ANCHOR_Y);

        const style = OBSTACLE_STYLES[styleKey] || OBSTACLE_STYLES['WALL'];

        // 1. Draw Base Shadow (Strict Hexagon Footprint)
        this.drawHexShadow(ctx);

        // 2. Draw Object based on Type (Growing Upwards y < 0)
        if (styleKey === 'TREE') {
            this.drawIsoTree(ctx, style);
        } else if (styleKey === 'ICE_CRYSTAL') {
            this.drawIsoCrystal(ctx, style);
        } else if (styleKey === 'OBSIDIAN_PILLAR') {
            this.drawIsoPillar(ctx, style);
        } else {
            this.drawIsoWall(ctx, style); // Default Wall/Sandstone
        }

        return canvas;
    },

    generateIceBlock(): HTMLCanvasElement {
        // Special case for Frozen Status Model
        const { canvas, ctx } = createCanvas(ENV_CANVAS_W, ENV_CANVAS_H);
        ctx.translate(ENV_ANCHOR_X, ENV_ANCHOR_Y);
        const style = OBSTACLE_STYLES['ICE_CRYSTAL'];

        // Draw a translucent block enclosing the unit
        this.drawIsoCrystal(ctx, style, 0.7);
        return canvas;
    },

    // --- GEOMETRY PRIMITIVES ---

    drawHexShadow(ctx: CanvasRenderingContext2D) {
        ctx.save();
        ctx.fillStyle = 'rgba(0,0,0,0.3)';
        ctx.filter = 'blur(4px)';
        ctx.beginPath();
        const r = HEX_SIZE * 0.9;
        for (let i = 0; i < 6; i++) {
            const v = getHexVertex(i, r);
            if(i===0) ctx.moveTo(v.x, v.y);
            else ctx.lineTo(v.x, v.y);
        }
        ctx.closePath();
        ctx.fill();
        ctx.restore();
    },

    drawIsoWall(ctx: CanvasRenderingContext2D, style: any) {
        const height = 55;
        const r = HEX_SIZE * 0.9; // Slightly smaller than tile

        // Vertices
        const v3 = getHexVertex(3, r); // Left
        const v2 = getHexVertex(2, r); // Bottom Left
        const v1 = getHexVertex(1, r); // Bottom Right
        const v0 = getHexVertex(0, r); // Right

        // Draw Sides (Extrude Up)
        const topY = -height;

        // Left Face (v3 -> v2)
        ctx.fillStyle = style.dark;
        ctx.beginPath();
        ctx.moveTo(v3.x, v3.y);
        ctx.lineTo(v2.x, v2.y);
        ctx.lineTo(v2.x, v2.y + topY);
        ctx.lineTo(v3.x, v3.y + topY);
        ctx.closePath();
        ctx.fill();
        ctx.strokeStyle = style.highlight; ctx.lineWidth = 1; ctx.stroke();

        // Front Face (v2 -> v1)
        ctx.fillStyle = style.main;
        ctx.beginPath();
        ctx.moveTo(v2.x, v2.y);
        ctx.lineTo(v1.x, v1.y);
        ctx.lineTo(v1.x, v1.y + topY);
        ctx.lineTo(v2.x, v2.y + topY);
        ctx.closePath();
        ctx.fill();
        ctx.stroke();

        // Right Face (v1 -> v0)
        ctx.fillStyle = style.light;
        ctx.beginPath();
        ctx.moveTo(v1.x, v1.y);
        ctx.lineTo(v0.x, v0.y);
        ctx.lineTo(v0.x, v0.y + topY);
        ctx.lineTo(v1.x, v1.y + topY);
        ctx.closePath();
        ctx.fill();
        ctx.stroke();

        // Top Face (Full Hex)
        ctx.save();
        ctx.translate(0, topY);
        ctx.fillStyle = style.light;
        ctx.globalAlpha = 0.9;
        ctx.beginPath();
        for (let i = 0; i < 6; i++) {
            const v = getHexVertex(i, r);
            if(i===0) ctx.moveTo(v.x, v.y); else ctx.lineTo(v.x, v.y);
        }
        ctx.closePath();
        ctx.fill();

        // Inner Detail
        ctx.fillStyle = style.detail;
        ctx.beginPath(); ctx.arc(0, 0, r*0.4, 0, Math.PI*2); ctx.fill();

        ctx.restore();
    },

    drawIsoPillar(ctx: CanvasRenderingContext2D, style: any) {
        const height = 90;
        const r = HEX_SIZE * 0.7; // Thinner than wall

        const v3 = getHexVertex(3, r); 
        const v2 = getHexVertex(2, r); 
        const v1 = getHexVertex(1, r); 
        const v0 = getHexVertex(0, r); 
        const topY = -height;

        // Left Face
        ctx.fillStyle = style.dark;
        ctx.beginPath();
        ctx.moveTo(v3.x, v3.y); ctx.lineTo(v2.x, v2.y); 
        ctx.lineTo(v2.x, v2.y + topY); ctx.lineTo(v3.x, v3.y + topY);
        ctx.fill();

        // Front Face
        ctx.fillStyle = style.main;
        ctx.beginPath();
        ctx.moveTo(v2.x, v2.y); ctx.lineTo(v1.x, v1.y);
        ctx.lineTo(v1.x, v1.y + topY); ctx.lineTo(v2.x, v2.y + topY);
        ctx.fill();

        // Rune on Front
        ctx.strokeStyle = style.detail;
        ctx.lineWidth = 2;
        ctx.shadowColor = style.detail;
        ctx.shadowBlur = 5;
        ctx.beginPath();
        ctx.moveTo(0, -30); ctx.lineTo(0, -60);
        ctx.moveTo(-5, -45); ctx.lineTo(5, -45);
        ctx.stroke();
        ctx.shadowBlur = 0;

        // Right Face
        ctx.fillStyle = style.light;
        ctx.beginPath();
        ctx.moveTo(v1.x, v1.y); ctx.lineTo(v0.x, v0.y);
        ctx.lineTo(v0.x, v0.y + topY); ctx.lineTo(v1.x, v1.y + topY);
        ctx.fill();

        // Top
        ctx.save();
        ctx.translate(0, topY);
        ctx.fillStyle = '#000';
        ctx.beginPath();
        for (let i = 0; i < 6; i++) {
            const v = getHexVertex(i, r);
            if(i===0) ctx.moveTo(v.x, v.y); else ctx.lineTo(v.x, v.y);
        }
        ctx.fill();
        ctx.restore();
    },

    drawIsoTree(ctx: CanvasRenderingContext2D, style: any) {
        // --- Redesigned: Stylized Pine Tree ---

        // 1. Trunk
        const trunkW = 14;
        const trunkH = 20;

        ctx.fillStyle = '#3f2e1e'; // Darker Wood
        ctx.beginPath();
        ctx.fillRect(-trunkW/2, -trunkH, trunkW, trunkH + 5); 

        // 2. Foliage Stack (Cones)
        const layers = 3;
        const baseWidth = 48;
        const layerHeight = 35;
        const overlap = 15;
        let currentY = -trunkH + 5;

        for (let i = 0; i < layers; i++) {
            const ratio = 1 - (i / layers);
            const width = baseWidth * (0.6 + ratio * 0.4);
            const height = layerHeight;

            // Draw Cone Triangle
            ctx.beginPath();
            ctx.moveTo(0, currentY - height); // Top
            ctx.lineTo(width/2, currentY);    // Right
            // Curved bottom for volume
            ctx.quadraticCurveTo(0, currentY + 10, -width/2, currentY); // Bottom Curve
            ctx.closePath();

            // Gradient Fill
            const grad = ctx.createLinearGradient(0, currentY - height, 0, currentY);
            grad.addColorStop(0, style.highlight);
            grad.addColorStop(0.5, style.main);
            grad.addColorStop(1, style.dark);
            ctx.fillStyle = grad;
            ctx.fill();

            // Outline/Shadow
            ctx.strokeStyle = style.dark;
            ctx.lineWidth = 1;
            ctx.stroke();

            // Move up for next layer
            currentY -= (height - overlap);
        }
    },

    drawIsoCrystal(ctx: CanvasRenderingContext2D, style: any, alpha: number = 1.0) {
        const drawShard = (x: number, y: number, w: number, h: number, tilt: number) => {
            ctx.save();
            ctx.translate(x, y);
            ctx.rotate(tilt);

            ctx.fillStyle = style.dark;
            ctx.globalAlpha = alpha;
            ctx.beginPath();
            ctx.moveTo(0, 0);
            ctx.lineTo(-w, -h * 0.2);
            ctx.lineTo(0, -h); 
            ctx.lineTo(w, -h * 0.3);
            ctx.closePath();
            ctx.fill();

            ctx.fillStyle = style.light;
            ctx.globalAlpha = alpha * 0.6;
            ctx.beginPath();
            ctx.moveTo(0, 0);
            ctx.lineTo(w, -h * 0.3);
            ctx.lineTo(0, -h);
            ctx.fill();

            ctx.strokeStyle = style.highlight;
            ctx.lineWidth = 1;
            ctx.globalAlpha = alpha;
            ctx.beginPath();
            ctx.moveTo(0, 0); ctx.lineTo(0, -h);
            ctx.stroke();

            ctx.restore();
        };

        drawShard(-10, 5, 10, 50, -0.2);
        drawShard(10, 2, 12, 40, 0.2);
        drawShard(0, 8, 18, 70, 0); 
    }
};

import { Agent } from "../../../../game";
import { STATUS_ICON_OFFSET } from "../../../../../constants";
import { AssetManager } from "../../../assets";
import { STATUS_VISUALS } from "../../../../../data/vfx/status_visuals";

export const OverheadPainter = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, z: number, t: number) {
        // Priority System: Only show most severe CC
        let type = '';
        if (agent.stunTimer > 0) type = 'STUN';
        else if (agent.fearTimer > 0) type = 'FEAR';
        else if (agent.tauntTimer > 0) type = 'TAUNT';
        else if (agent.silenceTimer > 0) type = 'SILENCE';
        else if (agent.blindTimer > 0) type = 'BLIND';

        if (!type) return;

        const icon = AssetManager.getStatusIcon(type);
        if (!icon) return;

        // Bobbing Animation
        const bob = Math.sin(t * 6) * 5;

        // Anchored closer to head, below HP bar
        const anchorY = y - z - STATUS_ICON_OFFSET + bob; 

        ctx.save();
        ctx.translate(x, anchorY);

        // Glow Backing
        const def = STATUS_VISUALS[type];
        const color = def?.primaryColor || '#fff';

        ctx.shadowColor = color;
        ctx.shadowBlur = 15;

        // Draw Icon
        ctx.drawImage(icon, -24, -24, 48, 48);

        // Extra "Dizzy" stars for Stun
        if (type === 'STUN') {
            ctx.rotate(t * 2);
            ctx.fillStyle = '#fff';
            for(let i=0; i<3; i++) {
                const a = i * (Math.PI*2/3);
                const sx = Math.cos(a) * 20;
                const sy = Math.sin(a) * 20;
                ctx.beginPath(); ctx.arc(sx, sy, 3, 0, Math.PI*2); ctx.fill();
            }
        }

        ctx.restore();
    }
};

import { Agent } from "../game";
import { HUD_BAR_OFFSET } from "../../constants";
import { HexUtils, MapConfig } from "../utils";
import { HUDSystem } from "../systems/hud";

// Sub-painters
import { BarPainter } from "./hud/BarPainter";
import { GaugePainter } from "./hud/GaugePainter";
import { TextPainter } from "./hud/TextPainter";

export class HUDRenderer {

    public draw(ctx: CanvasRenderingContext2D, hud: HUDSystem, agents: Agent[], getTerrainHeight: (q: number, r: number) => number, mapConfig: MapConfig, highlight: Agent | null, time: number) {
        agents.forEach(a => {
            if (a.hp <= 0) return;
            if (a.spawnTimer > 0) return; 

            let h = 0;
            if (a.isMoving && a.path.length > 0) {
                const startH = getTerrainHeight(a.q, a.r);
                const endHex = a.path[0];
                const endH = getTerrainHeight(endHex.q, endHex.r);
                h = HexUtils.lerp(startH, endH, a.moveProgress);
            } else {
                const visualHex = HexUtils.fromPx(a.px, a.py, mapConfig);
                h = getTerrainHeight(visualHex.q, visualHex.r);
            }

            const groundY = a.py - h;
            const physicsOffsetY = a.physics.y - a.physics.z; 

            // Draw HP Bar much higher to avoid collision with Stun Icons
            const anchorY = groundY + physicsOffsetY - HUD_BAR_OFFSET;
            const headX = a.px + a.physics.x;

            const isSelected = (a === highlight);

            // Delegate to specialized painters
            BarPainter.drawUnitBars(ctx, a, headX, anchorY, isSelected);
            GaugePainter.drawUnitStatusGauges(ctx, a, headX, anchorY);
        });

        TextPainter.drawFloatingText(ctx, hud);
    }
}

import { Team, Role } from "../../../../types";
import { VFXSystem } from "../../vfx";
import { SpriteManager } from "../../../sprites";
import { FACTION_VISUALS } from "../../../../data/vfx/faction_visuals";

export const UnitShatter = {
    spawn(
        system: VFXSystem, 
        x: number, y: number, z: number, 
        team: Team, 
        role: Role, 
        impulseX: number, impulseY: number
    ) {
        // Ensure assets are generated
        const assets = SpriteManager.getUnitImages(role, team);
        const factionConfig = FACTION_VISUALS[team] || FACTION_VISUALS[Team.BLUE];

        // 1. Base Token (Falls backward like a heavy coin/ragdoll)
        const base = system.state.getParticle();
        base.x = x; base.y = y; base.z = z + 10;
        base.vx = impulseX * 0.8; 
        base.vy = impulseY * 0.8; 
        base.vz = 250 + Math.random() * 100; // Jump up slightly before falling
        base.life = 3.0; base.maxLife = 3.0;
        base.color = '#fff'; base.size = 50; 
        base.type = 'SPRITE'; 
        base.image = assets.base; // Assign Pre-rendered Base
        base.vRotation = (Math.random() - 0.5) * 20;
        base.gravity = 1800; // Ensure it falls
        system.state.particles.push(base);

        // 2. Class Icon (Pops off separately)
        const icon = system.state.getParticle();
        icon.x = x; icon.y = y; icon.z = z + 40; 
        icon.vx = impulseX * 1.2 + (Math.random()-0.5)*100; 
        icon.vy = impulseY * 1.2 + (Math.random()-0.5)*100; 
        icon.vz = 350 + Math.random() * 200;
        icon.life = 2.5; icon.maxLife = 2.5;
        icon.color = '#fff'; icon.size = 64; 
        icon.type = 'SPRITE'; 
        icon.image = assets.icon; // Assign Pre-rendered Icon
        icon.vRotation = (Math.random() - 0.5) * 30; 
        icon.gravity = 1500;
        system.state.particles.push(icon);

        // 3. Faction Debris (Shatter particles)
        const shardCount = 12; // Increased count
        const colors = factionConfig.deathShatterColors;
        for(let i=0; i<shardCount; i++) {
            const p = system.state.getParticle();
            p.x = x + (Math.random()-0.5)*20; p.y = y + (Math.random()-0.5)*20; p.z = z + 30;
            const a = Math.random() * Math.PI * 2;
            const s = 150 + Math.random() * 300;

            p.vx = Math.cos(a)*s + impulseX*0.5; 
            p.vy = Math.sin(a)*s + impulseY*0.5; 
            p.vz = 200 + Math.random()*300; 

            p.life = 1.5; p.maxLife = 1.5;
            p.type = 'SHARD'; 
            p.color = colors[Math.floor(Math.random() * colors.length)];
            p.size = 8 + Math.random()*12; 
            p.vRotation = (Math.random()-0.5)*30; 
            p.gravity = 2000; // Heavy pieces
            system.state.particles.push(p);
        }

        // 4. Soul Release (Rising Light)
        const soul = system.state.getParticle();
        soul.x = x; soul.y = y; soul.z = z + 20;
        soul.vx = 0; soul.vy = 0; 
        soul.vz = 80; // Slow rise
        soul.life = 2.0; soul.maxLife = 2.0;
        soul.color = factionConfig.deathSpiritColor;
        soul.size = 80;
        soul.type = 'GLOW';
        soul.blendMode = 'screen';
        system.state.particles.push(soul);
    }
};

import { Particle } from "../../state";
import { VFXFactory } from "../../../../graphics/VFXFactory";

export const BillboardPainter = {
    draw(ctx: CanvasRenderingContext2D, p: Particle, drawX: number, drawY: number, progress: number) {
        // Logic for simple sprites that face the screen

        let img = p.image;

        // Fallback texture generation if image is missing but type expects one from factory
        if (!img && !p.texture) {
            // Note: SPRITE type assumes p.image is already set by spawner (e.g. UnitShatter)
            if (p.type !== 'SPRITE') {
                p.image = VFXFactory.getTexture(p.type as any, p.color);
                img = p.image;
            }
        }

        let scale = 1.0;
        let alpha = 1.0 - progress;

        // Specialized Animation Curves
        if (p.type === 'SMOKE' || p.type === 'SMOKE_PUFF' || p.type === 'ATMOSPHERE') {
            scale = 0.5 + progress * 1.5; // Expand
            alpha = (1.0 - progress) * 0.6; 
        } else if (p.type === 'SPARK' || p.type === 'GLOW') {
            scale = 1.0 - progress; // Shrink
        } else if (p.type === 'ROCK' && p.size > 30) {
            scale = 1.0; alpha = 1.0; 
        } else if (p.type === 'SPRITE') {
            // "Ragdoll" Tokens: Stay full size, fade out at very end
            scale = 1.0;
            alpha = progress > 0.8 ? (1 - progress) / 0.2 : 1.0;
        } else {
            scale = 1.0 - Math.pow(progress, 2);
        }

        if (alpha <= 0.01) return;

        ctx.save();
        ctx.translate(drawX, drawY);

        // 1. Rotation (Screenspace spin for debris/sparks/sprites)
        if (p.rotation) ctx.rotate(p.rotation);

        // 2. Blend Mode
        if (p.blendMode) ctx.globalCompositeOperation = p.blendMode;
        else if (['SMOKE', 'SMOKE_PUFF', 'ATMOSPHERE', 'SPARK', 'GLOW'].includes(p.type)) {
            ctx.globalCompositeOperation = 'screen';
        } else {
            ctx.globalCompositeOperation = 'source-over'; // Solid for debris/sprites
        }

        ctx.globalAlpha = Math.min(1, alpha);

        const drawSize = p.size * scale;

        // Shadow for physical debris (Fake 3D depth)
        if (['RUBBLE', 'DEBRIS', 'ROCK', 'SHARD', 'SPRITE'].includes(p.type)) {
            ctx.save();
            ctx.globalCompositeOperation = 'multiply';
            ctx.globalAlpha = 0.5 * alpha;
            ctx.fillStyle = 'rgba(0,0,0,0.5)';
            // Draw a small shadow offset
            ctx.beginPath(); ctx.arc(2, 2, drawSize * 0.8, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }

        if (img) {
            // Draw centered
            ctx.drawImage(img, -drawSize, -drawSize, drawSize * 2, drawSize * 2);
        } else {
            ctx.fillStyle = p.color;
            ctx.beginPath(); ctx.arc(0, 0, drawSize, 0, Math.PI*2); ctx.fill();
        }

        ctx.restore();
    }
};

import { Agent } from "../../../../game";
import { SpriteManager } from "../../../sprites";
import { UnitIndicatorPainter } from "./UnitIndicatorPainter";
import { MovementType } from "../../../../../types";
import { UnitFlightPainter } from "./UnitFlightPainter";
import { VFXFactory } from "../../../graphics/VFXFactory";

// Lift the physical token slightly to avoid z-fighting with the floor
const HOVER_LIFT = 6; 

export const UnitShadowPainter = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, px: number, py: number, pz: number, t: number, isSilhouette: boolean) {
        if (isSilhouette || agent.visualStatus === 'POLYMORPH') return;

        const assets = SpriteManager.getUnitImages(agent.role, agent.team);

        // Calculate Surface Y (Where the shadow falls)
        // UnitRenderSystem passes (px, py, pz) where py is BASE ground Y.
        // We calculate terrainH to find the visual surface top.
        const terrainH = Math.max(0, pz - agent.physics.z);
        const surfaceY = py - terrainH;

        // The Token sits slightly above the surface
        const tokenY = surfaceY - HOVER_LIFT;

        ctx.save();

        // 1. Drop Shadow (Stays firmly on the floor surface)
        // Shadow shrinks as unit jumps high
        const jumpHeight = agent.physics.z;
        const shadowScale = Math.max(0.6, 1.0 - (jumpHeight / 400));
        const shadowAlpha = Math.max(0.2, 1.0 - (jumpHeight / 200));

        const shadowBlob = VFXFactory.getTexture('SHADOW_BLOB', 'rgba(0,0,0,0.5)'); 

        ctx.save();
        ctx.translate(px, surfaceY); 
        ctx.scale(shadowScale, shadowScale);
        ctx.globalAlpha = shadowAlpha;
        ctx.drawImage(shadowBlob, -48, -24, 96, 48); 
        ctx.restore();

        // 2. Base Token (Lifted)
        ctx.save();
        ctx.translate(px, tokenY);
        // Only scale token if it's actually jumping significantly, otherwise it looks stable
        // We don't scale the token with jump height usually to keep it readable as a game piece
        ctx.drawImage(assets.base, -64, -64); 
        ctx.restore();

        // 3. Class Icon (Anchored to Token)
        if (agent.hp > 0) {
            ctx.save();
            ctx.translate(px, tokenY);

            const iconBaseY = -20; 
            ctx.translate(0, iconBaseY);
            const breath = Math.sin(t * 2) * 1.5;
            ctx.translate(0, breath);

            ctx.fillStyle = 'rgba(0,0,0,0.4)';
            ctx.beginPath(); ctx.ellipse(0, 28, 14, 6, 0, 0, Math.PI*2); ctx.fill();

            ctx.globalAlpha = 1.0; 
            ctx.shadowColor = 'rgba(0,0,0,0.3)'; ctx.shadowBlur = 5;
            ctx.drawImage(assets.icon, -32, -32, 64, 64);
            ctx.restore();
        }

        // 4. Casting Indicators (Projected on Surface)
        if (agent.castingSkillIdx !== -1) {
            const skill = agent.skills[agent.castingSkillIdx];
            if (skill) {
                const progress = 1 - (agent.castTimer / skill.cast);
                const radius = skill.aoeRadius || 1;
                const isAOE = skill.type === 'AOE';
                const visualRadius = isAOE ? 0.8 : radius;

                // Indicators sit on the surface, not lifted
                ctx.save();
                ctx.translate(px, surfaceY);
                UnitIndicatorPainter.drawSkillGroundIndicator(ctx, 0, 0, skill.color, t, progress, visualRadius, skill.tag, isAOE);
                ctx.restore();
            }
        }

        // 5. Flying Anchor Line (Draws from Surface UP to Body)
        if (agent.movementType === MovementType.FLYING && jumpHeight > 5) {
            // Draw relative to Surface
            UnitFlightPainter.drawFlyingAnchor(ctx, agent, t, px, surfaceY, jumpHeight);
        }

        ctx.restore();
    }
};

import { Agent } from "../../../../game";
import { Team, AnimState, MovementType } from "../../../../../types";
import { UNIT_BODY_OFFSET } from "../../../../../constants";
import { ImperialRenderer } from "../factions/ImperialRenderer";
import { CovenantRenderer } from "../factions/CovenantRenderer";
import { UnitFlightPainter } from "./UnitFlightPainter";
import { UnitAuraPainter } from "./UnitAuraPainter";
import { SpriteManager } from "../../../sprites";

const HOVER_LIFT = 6; // Must match UnitShadowPainter

export const UnitBodyPainter = {
    draw(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        px: number, py: number, pz: number, 
        t: number, 
        isSilhouette: boolean, 
        isSelected: boolean,
        scaleFactor: number
    ) {
        ctx.save(); 

        // 1. Transform to Body Center (Standard Anchor)
        // px, py are Ground Coordinates.
        // pz is Height from terrain.
        // UNIT_BODY_OFFSET shifts from feet to center of mass.
        // HOVER_LIFT shifts up to match the floating chessboard.
        const bodyY = py - pz - UNIT_BODY_OFFSET - HOVER_LIFT;

        ctx.translate(px, bodyY); 
        ctx.rotate(agent.physics.angle); 

        // 2. Animation Bobbing / Floating
        let bodyFloat = 0; 
        if (agent.hp > 0 && agent.movementType !== MovementType.FLYING) {
             bodyFloat = Math.sin(t * 2) * 3; 
        } else if (agent.movementType === MovementType.FLYING) {
             bodyFloat = Math.sin(t * 4) * 2;
        }
        ctx.translate(0, bodyFloat);

        // 3. Spawn Animation
        if (agent.spawnTimer > 0) {
            const SPAWN_DURATION = 0.5; 
            const progress = 1 - (agent.spawnTimer / SPAWN_DURATION); 
            const eased = 1 - Math.pow(1 - progress, 3); 
            ctx.scale(1, 2.0 - eased); 
            ctx.globalAlpha *= eased;
        }

        // 4. Status Filters
        if (agent.hp <= 0 && !isSilhouette) {
            ctx.filter = 'grayscale(100%) opacity(80%)'; 
        } else if (!isSilhouette && agent.hitFlashTimer > 0) {
             ctx.filter = 'brightness(200%)';
        }

        // 5. Flight VFX
        if (agent.movementType === MovementType.FLYING && agent.hp > 0 && !isSilhouette && agent.visualStatus === 'NONE') {
            UnitFlightPainter.drawFlightVFX(ctx, agent, t);
        }

        // 6. Facing Flip
        ctx.scale(agent.facing > 0 ? 1 : -1, 1);

        // 7. Render Strategy
        if (isSilhouette) {
            ctx.globalCompositeOperation = 'source-over'; 
            ctx.globalAlpha = 0.8; 
        }

        if (agent.visualStatus === 'POLYMORPH') {
            const sheep = SpriteManager.getSpecialModel('SHEEP');
            const bounce = Math.abs(Math.sin(t * 5) * 5);
            // Sheep sprite is 64x64. Center is 32,32. 
            // We are at body center. Draw centered.
            ctx.drawImage(sheep, -32, -32 - bounce, 64, 64);
        } else {
            // Faction Specific Renderers
            // Renderers assume (0,0) is Body Center
            if (agent.team === Team.BLUE) {
                ImperialRenderer.draw(ctx, agent, t, isSilhouette);
            } else {
                CovenantRenderer.draw(ctx, agent, t, isSilhouette);
            }

            // Casting Effects (Not in silhouette)
            if (!isSilhouette && agent.hp > 0 && agent.castingSkillIdx !== -1) {
                const skill = agent.skills[agent.castingSkillIdx];
                if (skill && skill.tag === 'ULT') {
                    UnitAuraPainter.drawUltimateChantVFX(ctx, agent, t);
                } else {
                    UnitAuraPainter.drawCastingVFX(ctx, agent, t);
                }
            }

            // Frozen State Overlay
            if (agent.visualStatus === 'FROZEN') {
                const ice = SpriteManager.getSpecialModel('ICE');
                ctx.save();
                ctx.globalCompositeOperation = 'hard-light';
                // Ice sprite is 96x128. Anchor center bottom?
                // Draw centered on body
                ctx.drawImage(ice, -48, -64, 96, 128);
                ctx.restore();
            }
        }

        ctx.restore(); 
    }
};

import { Agent } from "../../../../game";
import { AssetManager } from "../../../assets";
import { UNIT_BODY_OFFSET } from "../../../../../constants";

export const StateModelPainter = {
    drawBanishment(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, z: number, t: number) {
        if (!agent.banished) return;

        const isStasis = agent.visualStatus === 'STASIS';
        const color = isStasis ? '#facc15' : '#c084fc'; // Gold or Purple
        const secondaryColor = isStasis ? '#fef08a' : '#e9d5ff';

        // Calculate Body Center
        const centerY = y - z - UNIT_BODY_OFFSET - 6; // Apply HOVER_LIFT matching body

        ctx.save();
        ctx.translate(x, centerY);

        // --- CRYSTAL CAGE VISUAL ---
        // A rotating Octahedron (Diamond shape)
        // Vertices: Top, Bottom, and 4 equator points

        const size = 50; 
        const height = 70;
        const rotation = t * 0.8;

        // Calculate projected vertices
        const topY = -height;
        const botY = height;

        const points = [];
        for(let i=0; i<4; i++) {
            const angle = rotation + (i * Math.PI / 2);
            points.push({
                x: Math.cos(angle) * size,
                y: Math.sin(angle) * size * 0.3 // Flatten Y for perspective
            });
        }

        // Draw Order: Back faces -> (Unit is theoretically here) -> Front faces
        // Since we are overlaying, we draw semi-transparent front faces.

        // 1. Back Faces (Darker, Inside)
        ctx.lineWidth = 1;
        points.forEach((p, i) => {
            const nextP = points[(i + 1) % 4];
            // Simple Z-sort: if point is "behind" (y is lower in iso usually implies far, but here we rotate)
            // Let's just draw all back faces with low opacity

            // We only really care about the rim for the "Cage" look
        });

        // 2. Front Crystal Faces
        const drawFace = (p1: {x:number, y:number}, p2: {x:number, y:number}, tipY: number, alpha: number) => {
            ctx.beginPath();
            ctx.moveTo(p1.x, p1.y);
            ctx.lineTo(p2.x, p2.y);
            ctx.lineTo(0, tipY);
            ctx.closePath();

            ctx.fillStyle = color;
            ctx.globalAlpha = alpha;
            ctx.fill();

            ctx.strokeStyle = secondaryColor;
            ctx.globalAlpha = 0.8;
            ctx.stroke();
        };

        // Bobbing effect
        const bob = Math.sin(t * 2) * 5;
        ctx.translate(0, bob);

        // Draw Upper Pyramid
        for(let i=0; i<4; i++) {
            const p1 = points[i];
            const p2 = points[(i+1)%4];

            // Visibility check based on rotation to simulate 3D culling?
            // Or just draw all with additive blending for "energy" look
            drawFace(p1, p2, topY, 0.15);
        }

        // Draw Lower Pyramid
        for(let i=0; i<4; i++) {
            const p1 = points[i];
            const p2 = points[(i+1)%4];
            drawFace(p1, p2, botY, 0.1);
        }

        // 3. Central Energy Core
        ctx.globalCompositeOperation = 'screen';
        const pulse = 1.0 + Math.sin(t * 5) * 0.2;

        const icon = AssetManager.getStatusIcon(isStasis ? 'STASIS' : 'BANISH');
        if (icon) {
            ctx.save();
            ctx.scale(pulse, pulse);
            ctx.globalAlpha = 0.8;
            ctx.drawImage(icon, -24, -24, 48, 48);
            ctx.restore();
        } else {
            // Fallback glow
            const grad = ctx.createRadialGradient(0, 0, 5, 0, 0, 30);
            grad.addColorStop(0, '#fff');
            grad.addColorStop(0.5, color);
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;
            ctx.globalAlpha = 0.6;
            ctx.beginPath(); ctx.arc(0, 0, 30 * pulse, 0, Math.PI*2); ctx.fill();
        }

        // 4. Floating Runes/Particles
        for(let i=0; i<3; i++) {
            const rAngle = -t * 1.5 + (i * Math.PI * 2 / 3);
            const rx = Math.cos(rAngle) * 40;
            const ry = Math.sin(rAngle) * 15;

            ctx.fillStyle = secondaryColor;
            ctx.globalAlpha = 0.8;
            ctx.beginPath(); ctx.arc(rx, ry, 3, 0, Math.PI*2); ctx.fill();
        }

        ctx.restore();
    }
};

